export const faceLibrary = {"vertex":"attribute vec2 a_pos;\nvarying vec2 v_uv;\nvoid main(){\n  v_uv = a_pos * 0.5 + 0.5;\n  gl_Position = vec4(a_pos, 0.0, 1.0);\n}","versions":[{"id":"prime","title":"The Seed","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.05,"bgAlphaScale":0.9,"bgAlphaMax":1,"bgTintR":0.2,"bgTintG":1,"bgTintB":1,"tunerFadeSpeed":350,"orbFaceGlow":0.78,"orbEyeBright":0.72,"orbCoronaW":1.45,"orbEyeSize":0.15,"orbMouthY":-0.3,"orbScanFreq":41,"orbSkullSize":1.55,"orbScale":2.05,"orbEyeR":0.48,"orbEyeG":0.34,"orbEyeB":1,"orbSkullR":0,"orbSkullG":0.66,"orbSkullB":1},"bgShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nfloat fbm(vec2 p){\n  float v=0.0;float a=0.5;\n  for(int i=0;i<6;i++){v+=a*noise(p);p*=2.1;a*=0.48;}\n  return v;\n}\n\nvoid main(){\n  vec2 uv=v_uv;\n  vec2 c=uv-0.5;\n  float r=length(c);\n  float a=atan(c.y,c.x);\n  float t=u_time;\n\n  // Warped coordinates — space distortion\n  vec2 warp=c+vec2(noise(c*3.0+t*0.15)-0.5,noise(c*3.0+t*0.12+50.0)-0.5)*0.08;\n  float wr=length(warp);\n  float wa=atan(warp.y,warp.x);\n\n  // === NEBULA — deep space fog ===\n  float neb=fbm(vec2(wa*1.5+t*0.08,wr*4.0-t*0.15));\n  neb+=fbm(vec2(wa*3.0-t*0.12,wr*6.0+t*0.1))*0.6;\n  neb=pow(neb,1.5)*0.6;\n\n  // === CONCENTRIC RINGS — rotating scanner ===\n  float rings=0.0;\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    float ringR=0.1+fi*0.09;\n    float ringW=0.004+fi*0.001;\n    float d=abs(r-ringR);\n    float bright=exp(-d/ringW)*0.4;\n    bright*=0.5+0.5*sin(a*(4.0+fi)+t*(0.8+fi*0.3)+fi*2.0);\n    rings+=bright;\n  }\n\n  // === RADIAL SPOKES — rotating energy beams ===\n  float spokes=0.0;\n  for(int i=0;i<8;i++){\n    float fi=float(i);\n    float sa=fi*0.785+t*(0.15+fi*0.02);\n    float diff=abs(mod(a-sa+3.14159,6.28318)-3.14159);\n    float beam=exp(-diff*15.0)*smoothstep(0.0,0.1,r)*0.25;\n    beam*=0.7+0.3*sin(r*20.0-t*3.0+fi*4.0);\n    spokes+=beam;\n  }\n\n  // === ENERGY STREAMS — flowing plasma rivers ===\n  float streams=0.0;\n  for(int i=0;i<4;i++){\n    float fi=float(i);\n    float baseA=fi*1.5708+t*0.2;\n    float curve=sin(r*12.0+t*2.0+fi*3.0)*0.15;\n    float diff=abs(mod(a-baseA-curve+3.14159,6.28318)-3.14159);\n    float stream=exp(-diff*8.0)*smoothstep(0.05,0.2,r)\n      *smoothstep(0.55,0.35,r);\n    stream*=0.5+0.5*noise(vec2(r*8.0-t*2.0,fi*10.0));\n    streams+=stream*0.4;\n  }\n\n  // === PARTICLES — orbiting embers ===\n  float particles=0.0;\n  for(int i=0;i<30;i++){\n    float fi=float(i);\n    float pa=fi*0.21+t*(0.12+fi*0.015);\n    float pr=0.08+fi*0.015+sin(t*0.4+fi*0.7)*0.04;\n    vec2 pp=vec2(cos(pa),sin(pa))*pr+0.5;\n    float d=length(uv-pp);\n    float bright=hash(vec2(fi,floor(t*3.0+fi*0.2)));\n    particles+=exp(-d*100.0)*bright*0.25;\n  }\n\n  // === GRAVITY WELL — dark center pull ===\n  float well=exp(-r*4.0)*0.3;\n  float wellRing=exp(-abs(r-0.18)*30.0)*0.5;\n\n  // === COMPOSE (tint-driven) ===\n  vec3 tint=u_tint;\n  vec3 tintHot=mix(tint,vec3(1.0),0.3);\n  vec3 purple=vec3(0.06+tint.r*0.1,0.35+tint.g*0.2,0.55+tint.b*0.25);\n  vec3 deepBlue=vec3(0.01+tint.r*0.01,0.05+tint.g*0.02,0.09+tint.b*0.03);\n\n  vec3 nebCol=mix(purple,tint*0.5,neb)*neb;\n  vec3 ringCol=tint*rings;\n  vec3 spokeCol=mix(tint,purple,0.4)*spokes;\n  vec3 streamCol=mix(tint,tintHot,0.3)*streams;\n  vec3 partCol=tint*particles;\n  vec3 wellCol=mix(purple,tint,0.5)*(wellRing+well*0.3);\n\n  vec3 col=deepBlue;\n  col+=nebCol*0.8;\n  col+=ringCol;\n  col+=spokeCol;\n  col+=streamCol;\n  col+=partCol;\n  col+=wellCol;\n\n  // Vignette — darken edges\n  float vig=smoothstep(0.75,0.25,r);\n  col*=0.5+vig*0.5;\n\n  float intensity=max(col.r,max(col.g,col.b));\n  float alpha=u_alphaBase+intensity*u_alphaScale;\n  alpha=min(alpha,u_alphaMax);\n  // Soft edge fade — no visible box at canvas boundary\n  vec2 edge=abs(uv-0.5)*2.0;\n  float edgeFade=1.0-smoothstep(0.85,1.0,max(edge.x,edge.y));\n  alpha*=edgeFade;\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\n\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_atmoW;\nuniform float u_wideW;\nuniform float u_flickBase;\nuniform float u_flashThresh;\nuniform float u_boltMult;\n\n#define MAX_ARCS 32\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform int u_arcCount;\n\nfloat hash(float n){return fract(sin(n)*43758.5453);}\n\nfloat noise1d(float p){\n  float i=floor(p);float f=fract(p);\n  f=f*f*(3.0-2.0*f);\n  return mix(hash(i),hash(i+1.0),f);\n}\n\nfloat boltStrand(vec2 p,vec2 a,vec2 b,float t,float seed,float w){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<0.5)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  vec2 ap=p-a;\n  float along=dot(ap,dir)/len;\n  float perp=dot(ap,n);\n  if(along<-0.05||along>1.05)return 0.0;\n\n  float disp=0.0;\n  float freq=4.0;float amp=0.06*len;\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    disp+=(noise1d(along*freq+t*6.0+seed*17.3+fi*5.1)-0.5)*amp;\n    freq*=2.0;amp*=0.5;\n  }\n\n  // Tight at source (converges at third eye). NO end fade (2026-07-06):\n  // the old smoothstep(1.0,0.92,along) dimmed the final 8% so bolts\n  // visibly died BEFORE the rim. Displacement pinches to zero at the\n  // endpoint instead, so the strand terminates exactly ON the target.\n  float taper=smoothstep(0.0,0.12,along);\n  disp*=smoothstep(1.02,0.85,along);\n  w=w*(2.5-1.5*along);\n  float dist=abs(perp-disp);\n\n  float core=exp(-dist*u_coreW*w/len)*taper;\n  float glow=exp(-dist*u_glowW*w/len)*taper*0.5;\n  float atmo=exp(-dist*u_atmoW*w/len)*taper*0.15;\n  float wide=exp(-dist*u_wideW*w/len)*taper*0.05;\n\n  // IMPACT FLARE — energy splashes where the bolt meets the rim.\n  float impactD=length(p-b);\n  float impact=exp(-impactD*impactD*u_coreW*0.25/(len*len))*1.2\n             +exp(-impactD*u_glowW*2.0/len)*0.4;\n\n  return core+glow+atmo+wide+impact;\n}\n\nfloat bolt(vec2 p,vec2 a,vec2 b,float t,float seed){\n  float main=boltStrand(p,a,b,t,seed,1.0);\n\n  // One or two short forks for character, not bulk\n  vec2 ab=b-a;\n  float len=length(ab);\n  float forks=0.0;\n  if(len>1.0){\n    vec2 dir=ab/len;\n    vec2 n=vec2(-dir.y,dir.x);\n    for(int i=0;i<2;i++){\n      float fi=float(i);\n      float branchT=0.3+fi*0.35;\n      vec2 bs=a+ab*branchT;\n      float ba=(noise1d(seed*7.0+fi*13.0+t*2.0)-0.5)*1.8;\n      vec2 bd=dir*cos(ba)+n*sin(ba);\n      vec2 be=bs+bd*len*0.15;\n      forks+=boltStrand(p,bs,be,t,seed+fi*50.0+300.0,1.8)*0.2;\n    }\n  }\n\n  float flick=u_flickBase+(1.0-u_flickBase)*noise1d(t*12.0+seed*100.0);\n  float flash=step(u_flashThresh,noise1d(t*3.0+seed*50.0));\n  flick+=flash*0.8;\n\n  return (main+forks)*flick;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=bolt(px,u_arcStart[i],u_arcEnd[i],u_time,float(i)*7.7+13.1);\n    col+=u_arcColor[i]*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,vec3(1.0),smoothstep(0.7,2.0,intensity)*0.5);\n\n  float alpha=min(intensity*1.5,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec4 u_cymatics;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// Personality (shared driver in selector.js — nulls are skipped)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  // === CORONA — 4 wave layers (was 8) ===\n  float corona=0.0;\n  float w0=sin(a*3.0+t*1.5)*0.5+0.5;\n  float w1=sin(a*4.0+t*1.9+1.7)*0.5+0.5;\n  float w2=sin(a*5.0+t*2.3+3.4)*0.5+0.5;\n  float w3=sin(a*6.0+t*2.7+5.1)*0.5+0.5;\n  corona+=(w0+w1+w2+w3)*0.15;\n  float cMask=smoothstep(0.95,0.55,r)*smoothstep(0.45,0.6,r);\n  corona*=cMask;\n  float plasma=noise(vec2(a*3.0+t*0.5,r*8.0-t*2.0));\n  corona*=0.6+plasma*0.6;\n  corona*=1.0+u_hover*0.8;\n\n  // === SKULL SHAPE ===\n  float sk=u_skullSize;\n  float skull=smoothstep(0.68*sk,0.50*sk,r)*smoothstep(-0.7,-0.05,uv.y);\n  float jaw=smoothstep(0.55*sk,0.30*sk,r)*smoothstep(0.2,-0.65,uv.y)\n    *smoothstep(0.50*sk,0.18*sk,abs(uv.x));\n  float face=max(skull,jaw);\n\n  float fTex=noise(uv*4.0+t*0.15);\n\n  // === EYES — shared-driver blink + wandering gaze ===\n  float blink=1.0-u_blink*0.95;\n  vec2 eL=vec2(-0.22,0.13)+u_gaze;\n  vec2 eR=vec2(0.22,0.13)+u_gaze;\n  float eS=u_eyeSize+u_hover*0.02;\n  float cL=smoothstep(eS,eS*0.1,length(uv-eL));\n  float cR=smoothstep(eS,eS*0.1,length(uv-eR));\n  float eyes=(cL+cR)*blink;\n  float gL=exp(-length(uv-eL)*4.0);\n  float gR=exp(-length(uv-eR)*4.0);\n  float eyeGlow=(gL+gR)*blink;\n\n  // === NOSE ===\n  float nose=smoothstep(0.03,0.008,abs(uv.x))\n    *smoothstep(0.08,0.0,uv.y)*smoothstep(-0.18,0.0,uv.y)*0.5;\n\n  // === MOUTH — breathing, and it SMILES (skull grin widens) ===\n  float mY=u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0)))+sin(t*0.18)*0.03;\n  vec2 mp=uv-vec2(0.0,mY);\n  mp.y-=u_smile*(mp.x*mp.x*1.2-0.03);\n  float mW=0.38+u_smile*0.06;\n  float jawM=smoothstep(mW,0.0,abs(mp.x));\n  float mThick=0.035+u_talk*0.045+sin(t*0.22)*0.008;\n  float teeth=sin(mp.x*30.0)*0.012;\n  float mLine=smoothstep(mThick,0.003,abs(mp.y-teeth-mp.x*mp.x*0.5))*jawM;\n\n  // === SCAN + GLITCH ===\n  float scan=pow(sin(uv.y*u_scanFreq+t*3.0)*0.5+0.5,8.0)*0.15;\n  float glBand=step(0.92,hash(vec2(floor(uv.y*10.0+t*6.0),1.0)));\n  float glitch=glBand*sin(uv.x*40.0+t*20.0)*0.1;\n\n  // === SPARKS — 8 orbiting (was 16) ===\n  float sparks=0.0;\n  for(int i=0;i<8;i++){\n    float fi=float(i);\n    float sa=fi*0.785+t*(0.4+fi*0.1);\n    float sr=0.78+sin(t*2.0+fi*1.5)*0.15;\n    vec2 sp=vec2(cos(sa),sin(sa))*sr;\n    sparks+=exp(-length(uv-sp)*30.0)*0.4;\n  }\n\n  // === COMPOSE (color-driven) ===\n  vec3 eyeCol=u_eyeColor;\n  vec3 skullCol=u_skullColor;\n  vec3 hotEye=mix(eyeCol,vec3(1.0,0.95,0.9),0.4);\n  vec3 purple=vec3(0.6,0.15,1.0);\n  vec3 coronaCol=mix(eyeCol,purple,0.3+sin(a*2.0+t)*0.3);\n\n  float fg=u_faceGlow;\n  float eb=u_eyeBright;\n  float cw=u_coronaW;\n\n  vec3 col=vec3(0.0);\n\n  col+=coronaCol*corona*2.0*cw;\n  col+=skullCol*face*(0.5+fTex*0.5)*fg;\n  col+=hotEye*eyes*4.0*eb;\n  col+=eyeCol*eyeGlow*2.0*eb;\n  col+=eyeCol*nose*fg;\n  col+=mix(eyeCol,purple,0.4)*mLine*2.0*fg;\n  col+=eyeCol*scan*face*0.5;\n  col+=eyeCol*abs(glitch)*face;\n  col+=eyeCol*sparks;\n  col+=(eyeCol*eyes*2.0*eb+purple*corona*0.5*cw)*u_hover;\n  col+=eyeCol*exp(-r*2.5)*face*0.35*fg;\n\n  float alpha=face*0.85*fg+corona*0.6*cw+eyeGlow*0.7*eb\n    +eyes*0.5*eb+sparks*0.3+nose*0.3*fg+mLine*0.7*fg;\n  alpha=clamp(alpha,0.0,1.0);\n  alpha*=smoothstep(1.0,0.7,r);\n\n  gl_FragColor=vec4(col*alpha, alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p),ang=atan(p.y,p.x);\n float seed=exp(-dot((p-vec2(0.,.49))/vec2(.050,.080),(p-vec2(0.,.49))/vec2(.050,.080))*2.2);\n float rootMask=head*smoothstep(-.05,.34,p.y);\n float roots=pow(.5+.5*sin(p.x*31.+sin(p.y*13.-t*.38)*4.),18.)*rootMask;\n roots+=pow(.5+.5*sin(ang*11.+r*34.-t*.55),24.)*head*.55;\n float strata=gfArtLine(abs(p.y+.27)-(.018+.018*sin(p.x*18.)),.010)\n   *smoothstep(.48,.12,abs(p.x))*head;\n float crown=gfArtRing(p-vec2(0.,.04),.73+.018*sin(ang*7.-t*.28),.010)\n   *(1.+high*.8);\n vec2 ep=vec2(abs(p.x)-.22,p.y-.15);\n float sockets=exp(-pow(ep.x/.15,2.)-pow(ep.y/.105,2.));\n float cheekShade=exp(-pow((abs(p.x)-.31)/.16,2.)-pow((p.y+.08)/.24,2.));\n float faceContours=exp(-abs(sin((r*31.+sin(ang*3.)*2.)-t*.18))*21.)*head*.13;\n float sparks=pow(gfArtHash(floor((p+1.)*92.)+floor(t*4.)),38.)\n   *smoothstep(.86,.48,r)*(1.-head);\n c-=vec3(.20,.23,.30)*(sockets*.72+cheekShade*.24);\n c+=mix(eye,vec3(.78,.37,1.),.42)*(roots*(.23+bass*.24)\n   +crown*(.32+high*.34)+sparks*(.55+high*.48));\n c+=mix(eye,warm,.42)*(seed*(1.25+hit*1.8)+strata*.34\n   +faceContours*(1.+mid*1.4));\n a+=seed*.42+roots*.08+crown*.18+sparks*.18+strata*.12+faceContours*.04;\n c*=1.150*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.780+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v2.0","title":"The First Write","defaults":{"boltCoreW":125,"boltGlowW":5,"boltAtmoW":50,"boltWideW":20,"boltFlicker":0.15,"boltFlashRate":0.81,"boltMult":0.7,"bgAlphaBase":0.05,"bgAlphaScale":2.5,"bgAlphaMax":1,"bgTintR":0.05,"bgTintG":0.8,"bgTintB":0.15,"tunerFadeSpeed":200,"orbFaceGlow":0.86,"orbEyeBright":0.62,"orbCoronaW":2.15,"orbEyeSize":0.15,"orbMouthY":-0.3,"orbScanFreq":41,"orbSkullSize":1.42,"orbScale":1.7,"orbEyeR":0.1,"orbEyeG":1,"orbEyeB":0.3,"orbSkullR":0.14,"orbSkullG":0.36,"orbSkullB":0.1,"signalFreq":5,"waveAmp":1.2,"crtFlicker":0.8,"phosphorDecay":1,"vocoderBands":5,"dataRate":3.75},"bgShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\nvoid main(){\n  vec2 uv=v_uv;\n  vec2 c=uv-0.5;\n  float r=length(c);\n  float t=u_time;\n\n  vec3 green=vec3(0.1,0.9,0.2);\n  vec3 deep=vec3(0.0,0.02,0.0);\n  vec3 tint=u_tint;\n\n  // CRT scan lines\n  float scanline=sin(uv.y*400.0)*0.03+0.97;\n  float scanSlow=sin(uv.y*80.0+t*2.0)*0.5+0.5;\n\n  // Signal noise floor\n  float nFloor=noise(uv*20.0+t*0.5)*0.08;\n  float nHigh=noise(uv*80.0+t*3.0)*0.03;\n\n  // Horizontal interference bands\n  float band=sin(uv.y*6.0+t*0.8)*0.5+0.5;\n  band=pow(band,8.0)*0.15;\n\n  // Phosphor edge glow\n  float edgeGlow=smoothstep(0.5,0.3,r)*0.1;\n  float edgeBright=smoothstep(0.55,0.45,r)*smoothstep(0.35,0.45,r)*0.2;\n\n  // CRT vignette — darker at edges, green glow center\n  float vig=1.0-smoothstep(0.3,0.7,r);\n\n  vec3 col=deep;\n  col+=mix(green,tint,0.3)*(nFloor+nHigh)*scanline;\n  col+=green*band*scanline;\n  col+=green*edgeGlow;\n  col+=green*edgeBright;\n  col*=vig*0.7+0.3;\n  col+=green*scanSlow*0.03;\n\n  float intensity=max(col.r,max(col.g,col.b));\n  float alpha=u_alphaBase+intensity*u_alphaScale;\n  alpha=min(alpha,u_alphaMax);\n  vec2 edge=abs(uv-0.5)*2.0;\n  alpha*=1.0-smoothstep(0.85,1.0,max(edge.x,edge.y));\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_atmoW;\nuniform float u_wideW;\nuniform float u_flickBase;\nuniform float u_flashThresh;\nuniform float u_boltMult;\n#define MAX_ARCS 32\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform int u_arcCount;\n\nfloat hash(float n){return fract(sin(n)*43758.5453);}\nfloat noise1d(float p){\n  float i=floor(p);float f=fract(p);\n  f=f*f*(3.0-2.0*f);\n  return mix(hash(i),hash(i+1.0),f);\n}\n\nfloat dataStream(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<0.5)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  vec2 ap=p-a;\n  float along=dot(ap,dir)/len;\n  float perp=dot(ap,n);\n  if(along<-0.02||along>1.02)return 0.0;\n\n  // Tight data line — less organic wobble than lightning.\n  // No end fade: packets DELIVER to the rim (impact flash below).\n  float disp=(noise1d(along*6.0+t*4.0+seed*11.3)-0.5)*0.03*len;\n  disp*=smoothstep(1.02,0.88,along);\n\n  float taper=smoothstep(0.0,0.08,along);\n  float dist=abs(perp-disp);\n\n  float core=exp(-dist*u_coreW*1.2/len)*taper;\n  float glow=exp(-dist*u_glowW*0.5/len)*taper*0.3;\n  float impactD=length(p-b);\n  float impact=exp(-impactD*impactD*u_coreW*0.3/(len*len))*0.8;\n\n  // Data packets — discrete bright dots flowing along\n  float packetCount=8.0;\n  float packets=0.0;\n  for(int i=0;i<8;i++){\n    float fi=float(i);\n    float pPos=fract(fi/packetCount+t*1.5+seed*0.13);\n    float pDist=abs(along-pPos);\n    packets+=exp(-pDist*80.0)*taper*0.8;\n  }\n\n  float active=u_flickBase+(1.0-u_flickBase)*\n    step(0.3,noise1d(t*8.0+seed*40.0));\n\n  return (core*0.4+glow+packets+impact)*active;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n  vec3 green=vec3(0.1,1.0,0.3);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=dataStream(px,u_arcStart[i],u_arcEnd[i],u_time,float(i)*7.7+13.1);\n    vec3 arcCol=mix(u_arcColor[i],green,0.6);\n    col+=arcCol*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,vec3(0.8,1.0,0.8),smoothstep(0.7,2.0,intensity)*0.3);\n  float alpha=min(intensity*1.4,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec4 u_cymatics;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\nuniform float u_signalFreq;\nuniform float u_waveAmp;\nuniform float u_crtFlicker;\nuniform float u_phosphorDecay;\nuniform float u_vocoderBands;\nuniform float u_dataRate;\n// Personality (shared driver in selector.js)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  vec3 green=vec3(0.1,1.0,0.3);\n  vec3 dimGreen=vec3(0.05,0.4,0.1);\n\n  // === SIGNAL CORONA — oscilloscope waveform ring ===\n  float corona=0.0;\n  for(int i=0;i<6;i++){\n    float fi=float(i);\n    float freq=u_signalFreq*(2.0+fi*1.5);\n    float phase=t*(1.5+fi*0.4)+fi*1.3;\n    float wave=sin(a*freq+phase)*u_waveAmp*(0.03+fi*0.008);\n    float ringR=0.65+fi*0.04+wave;\n    corona+=smoothstep(0.015,0.0,abs(r-ringR))*(1.0-fi*0.12);\n  }\n  float cMask=smoothstep(0.95,0.5,r)*smoothstep(0.4,0.55,r);\n  corona*=cMask*(1.0+u_hover*0.5);\n\n  // === SKULL — drawn with oscilloscope strokes ===\n  float sk=u_skullSize;\n  float skull=smoothstep(0.70*sk,0.48*sk,r)*smoothstep(-0.7,-0.05,uv.y);\n  float jaw=smoothstep(0.55*sk,0.28*sk,r)*smoothstep(0.2,-0.65,uv.y)\n    *smoothstep(0.50*sk,0.18*sk,abs(uv.x));\n  float face=max(skull,jaw);\n\n  // Wireframe skull edges — \"being drawn\" quality\n  float skEdge=smoothstep(0.02,0.0,abs(r-0.55*sk))*skull;\n  float jawEdge=smoothstep(0.02,0.0,abs(r-0.38*sk))*jaw;\n  float wireface=skEdge+jawEdge;\n\n  // CRT phosphor noise texture\n  float scanline=sin(uv.y*u_scanFreq+t*2.0)*0.5+0.5;\n  scanline=pow(scanline,4.0)*0.15;\n  float pNoise=noise(uv*8.0+t*0.3)*0.3;\n\n  // === EYES — frequency analyzer displays (driver blink + gaze) ===\n  float blink=1.0-u_blink*0.95;\n  vec2 eL=vec2(-0.22,0.13)+u_gaze;\n  vec2 eR=vec2(0.22,0.13)+u_gaze;\n  float eS=u_eyeSize+u_hover*0.02;\n  float dL=length(uv-eL);\n  float dR=length(uv-eR);\n  float cL=smoothstep(eS,eS*0.1,dL);\n  float cR=smoothstep(eS,eS*0.1,dR);\n\n  // Frequency bars inside eyes\n  float barsL=0.0;float barsR=0.0;\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    float barX=eL.x-eS*0.6+fi*eS*0.3;\n    float barH=0.3+0.7*noise(vec2(fi*3.0+t*u_dataRate,0.0));\n    barsL+=smoothstep(eS*0.15,0.0,abs(uv.x-barX))\n      *smoothstep(eL.y-eS*barH,eL.y,uv.y)\n      *smoothstep(eL.y+eS*0.3,eL.y,uv.y);\n    barX=eR.x-eS*0.6+fi*eS*0.3;\n    barsR+=smoothstep(eS*0.15,0.0,abs(uv.x-barX))\n      *smoothstep(eR.y-eS*barH,eR.y,uv.y)\n      *smoothstep(eR.y+eS*0.3,eR.y,uv.y);\n  }\n  float bars=(barsL+barsR)*blink*0.6;\n\n  float eyes=(cL+cR)*blink;\n  float gL=exp(-dL*5.0);\n  float gR=exp(-dR*5.0);\n  float eyeGlow=(gL+gR)*blink;\n\n  // === NOSE ===\n  float nose=smoothstep(0.03,0.008,abs(uv.x))\n    *smoothstep(0.08,0.0,uv.y)*smoothstep(-0.18,0.0,uv.y)*0.4;\n\n  // === MOUTH — vocoder visualization, curves with the smile ===\n  float mY=u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0)))+sin(t*0.15)*0.02;\n  vec2 mp=uv-vec2(0.0,mY);\n  mp.y-=u_smile*(mp.x*mp.x*1.4-0.03);\n  float mW=0.35+u_smile*0.05;\n  float jawM=smoothstep(mW,0.0,abs(mp.x));\n  float vocoder=0.0;\n  for(int i=0;i<6;i++){\n    float fi=float(i);\n    float bandH=noise(vec2(fi*2.7+t*u_dataRate,1.0))*0.06;\n    float bandX=mp.x*u_vocoderBands+fi*0.8;\n    vocoder+=smoothstep(0.2,0.0,abs(fract(bandX)-0.5))\n      *smoothstep(bandH,0.0,abs(mp.y))*jawM;\n  }\n  vocoder*=0.5;\n\n  // === CRT FLICKER ===\n  float flicker=1.0-u_crtFlicker*0.05*sin(t*120.0);\n  float decay=1.0-u_phosphorDecay*0.1*noise(vec2(t*0.5,uv.y*4.0));\n\n  // === COMPOSE — green phosphor CRT palette ===\n  float fg=u_faceGlow;\n  float eb=u_eyeBright;\n  float cw=u_coronaW;\n\n  vec3 col=vec3(0.0);\n  col+=green*corona*1.5*cw;\n  col+=dimGreen*face*(0.2+pNoise)*fg;\n  col+=green*wireface*0.8*fg;\n  col+=green*scanline*face*0.4;\n  col+=green*eyes*3.0*eb;\n  col+=green*eyeGlow*1.5*eb;\n  col+=green*bars*eb;\n  col+=dimGreen*nose*fg;\n  col+=green*vocoder*fg;\n  col+=(green*eyes*1.5*eb+dimGreen*corona*0.3*cw)*u_hover;\n  col+=green*exp(-r*2.5)*face*0.2*fg;\n\n  col*=flicker*decay;\n\n  float alpha=face*0.7*fg+corona*0.5*cw+eyeGlow*0.6*eb\n    +eyes*0.4*eb+bars*0.4*eb+wireface*0.5*fg\n    +nose*0.3*fg+vocoder*0.5*fg+scanline*face*0.2;\n  alpha=clamp(alpha,0.0,1.0);\n  alpha*=smoothstep(1.0,0.7,r);\n\n  gl_FragColor=vec4(col*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float raster=pow(.5+.5*sin(p.y*330.-t*31.),22.)*head;\n vec2 cell=fract((p+1.)*vec2(42.,31.))-.5;\n float phosphor=exp(-dot(cell,cell)*110.)*head*(.12+high*.28);\n float cursor=gfArtSeg(p,vec2(-.56,.58),vec2(.56,.58),.008)\n   *exp(-pow(p.x-(-.58+1.16*fract(t*.11+hit*.08)),2.)*45.);\n float trace=gfArtLine(p.y+.08-.028*sin(p.x*24.-t*2.2)-mid*.025*sin(p.x*9.),.010)\n   *smoothstep(.60,.18,abs(p.x))*head;\n float registerMarks=pow(.5+.5*cos(atan(p.y,p.x)*32.),38.)\n   *gfArtRing(p,.73,.018);\n float ghostTrace=gfArtLine(p.y+.08-.028*sin(p.x*24.-t*2.2)-.035,.018)\n   *smoothstep(.60,.18,abs(p.x))*head;\n vec2 eyeWell=vec2(abs(p.x)-.22,p.y-.14);\n float socket=exp(-pow(eyeWell.x/.14,2.)-pow(eyeWell.y/.095,2.));\n float analyzer=gfArtRing(eyeWell,.061+.006*mid,.009)+exp(-dot(eyeWell,eyeWell)*620.);\n c-=vec3(.08,.21,.10)*socket*.62;\n c+=vec3(.08,1.,.31)*(raster*(.10+bass*.16)+phosphor*(.18+high*.30)\n   +cursor*(.70+hit*.75)+trace*(.46+mid*.42)+registerMarks*.30);\n c+=vec3(.65,1.,.72)*analyzer*(.42+mid*.62);\n c+=vec3(.02,.24,.08)*ghostTrace*.34;\n a+=raster*.04+phosphor*.06+cursor*.18+trace*.14+registerMarks*.12+analyzer*.10;\n c*=1.100*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.880+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v3.0","title":"The Dreamer","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.05,"bgAlphaScale":1.5,"bgAlphaMax":1,"bgTintR":0,"bgTintG":0.64,"bgTintB":1,"tunerFadeSpeed":200,"orbFaceGlow":0.88,"orbEyeBright":0.48,"orbCoronaW":2.2,"orbEyeSize":0.15,"orbMouthY":-0.35,"orbScanFreq":41,"orbSkullSize":1.48,"orbScale":1.98,"orbEyeR":0.48,"orbEyeG":0.34,"orbEyeB":1,"orbSkullR":0.18,"orbSkullG":0.52,"orbSkullB":1,"echoStr":0.16,"thirdEyeSize":0.075,"thirdEyeBright":0.38,"mandalaFreq":70,"streamDensity":0.1,"heartbeatRate":1.1,"heartbeatStr":0.12,"goldWarmth":0.34,"depthRingFreq":50,"particleBright":0.42},"bgShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\nfloat fbm(vec2 p){\n  float v=0.0;float a=0.5;\n  for(int i=0;i<5;i++){v+=a*noise(p);p*=2.1;a*=0.48;}\n  return v;\n}\nvoid main(){\n  vec2 uv=v_uv;\n  vec2 c=uv-0.5;\n  float r=length(c);\n  float a=atan(c.y,c.x);\n  float t=u_time;\n\n  vec2 warp=c+vec2(noise(c*2.5+t*0.1)-0.5,noise(c*2.5+t*0.08+30.0)-0.5)*0.12;\n  float wr=length(warp);\n  float wa=atan(warp.y,warp.x);\n\n  float neb=fbm(vec2(wa*1.2+t*0.06,wr*3.5-t*0.1));\n  neb+=fbm(vec2(wa*2.5-t*0.08,wr*5.0+t*0.07))*0.5;\n  neb=pow(neb,1.3)*0.7;\n\n  // Organic spiral arms\n  float spiral=0.0;\n  for(int i=0;i<3;i++){\n    float fi=float(i);\n    float sa=a+r*4.0*(1.0+fi*0.5)+t*(0.12+fi*0.03)+fi*2.09;\n    spiral+=pow(sin(sa)*0.5+0.5,4.0)*0.25*smoothstep(0.5,0.15,r);\n  }\n\n  // Dream particles — slow drifting motes\n  float motes=0.0;\n  for(int i=0;i<20;i++){\n    float fi=float(i);\n    float pa=fi*0.314+t*(0.06+fi*0.008);\n    float pr=0.1+fi*0.02+sin(t*0.2+fi)*0.03;\n    vec2 pp=vec2(cos(pa),sin(pa))*pr+0.5;\n    float d=length(uv-pp);\n    motes+=exp(-d*80.0)*0.3;\n  }\n\n  // Gravity well — softer than Prime\n  float well=exp(-r*3.0)*0.2;\n\n  vec3 gold=vec3(1.0,0.78,0.2);\n  vec3 purple=vec3(0.45,0.1,0.7);\n  vec3 deep=vec3(0.03,0.02,0.1);\n  vec3 tint=u_tint;\n\n  vec3 nebCol=mix(purple,mix(gold,tint,0.5),neb)*neb;\n  vec3 spiralCol=mix(gold,purple,0.4)*spiral;\n  vec3 moteCol=mix(gold,tint,0.6)*motes;\n  vec3 wellCol=mix(purple,gold,0.4)*well;\n\n  vec3 col=deep;\n  col+=nebCol*0.9;\n  col+=spiralCol;\n  col+=moteCol;\n  col+=wellCol;\n\n  float vig=smoothstep(0.75,0.2,r);\n  col*=0.4+vig*0.6;\n\n  float intensity=max(col.r,max(col.g,col.b));\n  float alpha=u_alphaBase+intensity*u_alphaScale;\n  alpha=min(alpha,u_alphaMax);\n  vec2 edge=abs(uv-0.5)*2.0;\n  alpha*=1.0-smoothstep(0.85,1.0,max(edge.x,edge.y));\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_atmoW;\nuniform float u_wideW;\nuniform float u_flickBase;\nuniform float u_flashThresh;\nuniform float u_boltMult;\n#define MAX_ARCS 32\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform int u_arcCount;\n\nfloat hash(float n){return fract(sin(n)*43758.5453);}\nfloat noise1d(float p){\n  float i=floor(p);float f=fract(p);\n  f=f*f*(3.0-2.0*f);\n  return mix(hash(i),hash(i+1.0),f);\n}\n\nfloat aurora(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<0.5)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  vec2 ap=p-a;\n  float along=dot(ap,dir)/len;\n  float perp=dot(ap,n);\n  if(along<-0.05||along>1.05)return 0.0;\n\n  float disp=0.0;\n  float freq=2.5;float amp=0.1*len;\n  for(int i=0;i<4;i++){\n    float fi=float(i);\n    disp+=(noise1d(along*freq+t*2.5+seed*13.7+fi*4.3)-0.5)*amp;\n    freq*=1.8;amp*=0.55;\n  }\n\n  float taper=smoothstep(0.0,0.15,along)*smoothstep(1.0,0.85,along);\n  float dist=abs(perp-disp);\n  float ribbon=exp(-dist*u_glowW*0.5/len)*taper;\n  float glow=exp(-dist*u_atmoW*0.3/len)*taper*0.4;\n  float wide=exp(-dist*u_wideW*0.2/len)*taper*0.15;\n\n  float shimmer=0.7+0.3*sin(along*20.0-t*4.0+seed*7.0);\n  float breathe=0.8+0.2*sin(t*0.6+seed*3.0);\n\n  return (ribbon+glow+wide)*shimmer*breathe;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n  vec3 gold=vec3(1.0,0.78,0.2);\n  vec3 purple=vec3(0.6,0.2,1.0);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=aurora(px,u_arcStart[i],u_arcEnd[i],u_time,float(i)*7.7+13.1);\n    vec3 arcCol=mix(u_arcColor[i],mix(gold,purple,sin(u_time+float(i))*0.5+0.5),0.4);\n    col+=arcCol*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,vec3(1.0,0.95,0.85),smoothstep(0.7,2.0,intensity)*0.3);\n  float alpha=min(intensity*1.2,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\nuniform vec4 u_cymatics;\n// v3.0-specific uniforms\nuniform float u_echoStr;\nuniform float u_thirdEyeSize;\nuniform float u_thirdEyeBright;\nuniform float u_mandalaFreq;\nuniform float u_streamDensity;\nuniform float u_heartbeatRate;\nuniform float u_heartbeatStr;\nuniform float u_goldWarmth;\nuniform float u_depthRingFreq;\nuniform float u_particleBright;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n  float bass=u_cymatics.x,mid=u_cymatics.y,high=u_cymatics.z,hit=u_cymatics.w;\n\n  vec3 gold=vec3(1.0,0.78,0.2);\n\n  // === FRACTAL CORONA — rotating geometric mandala ===\n  float corona=0.0;\n  for(int i=0;i<4;i++){\n    float fi=float(i);\n    float ca=a*(3.0+fi*2.0)+t*(0.5+fi*0.3)+fi*1.7;\n    float cr=r*(4.0+fi*2.0)-t*(0.3+fi*0.15);\n    corona+=sin(ca)*sin(cr)*0.15;\n  }\n  corona=abs(corona);\n  float cMask=smoothstep(0.95,0.55,r)*smoothstep(0.45,0.6,r);\n  corona*=cMask;\n  float plasma=noise(vec2(a*3.0+t*0.4,r*8.0-t*1.5));\n  corona*=0.6+plasma*0.6;\n  corona*=1.0+u_hover*0.8;\n\n  // === SKULL — softer edges than prime ===\n  float sk=u_skullSize;\n  float skull=smoothstep(0.72*sk,0.48*sk,r)*smoothstep(-0.7,-0.05,uv.y);\n  float jaw=smoothstep(0.55*sk,0.28*sk,r)*smoothstep(0.2,-0.65,uv.y)\n    *smoothstep(0.50*sk,0.18*sk,abs(uv.x));\n  float face=max(skull,jaw);\n  float fTex=noise(uv*3.0+vec2(t*0.1,t*0.12));\n  fTex=fTex*0.5+noise(uv*6.0-vec2(t*0.08,t*0.15))*0.5;\n\n  // === PHASE ECHO — quantum double ===\n  vec2 echoOff=vec2(sin(t*0.3)*0.02,cos(t*0.25)*0.015);\n  vec2 euv=uv+echoOff;\n  float er=length(euv);\n  float eSkull=smoothstep(0.72*sk,0.48*sk,er)*smoothstep(-0.7,-0.05,euv.y);\n  float eJaw=smoothstep(0.55*sk,0.28*sk,er)*smoothstep(0.2,-0.65,euv.y)\n    *smoothstep(0.50*sk,0.18*sk,abs(euv.x));\n  float echoFace=max(eSkull,eJaw)*u_echoStr;\n\n  // === EYES — concentric depth rings ===\n  float blinkRaw=fract(t*0.22);\n  float blink=1.0-(smoothstep(0.0,0.03,blinkRaw)*smoothstep(0.08,0.05,blinkRaw));\n  vec2 eL=vec2(-0.22,0.13);\n  vec2 eR=vec2(0.22,0.13);\n  float eS=u_eyeSize+u_hover*0.02;\n  float dL=length(uv-eL);\n  float dR=length(uv-eR);\n  float cL=smoothstep(eS,eS*0.1,dL);\n  float cR=smoothstep(eS,eS*0.1,dR);\n  float ringsL=sin(dL*u_depthRingFreq-t*3.0)*0.5+0.5;\n  ringsL*=cL*(0.4+mid*0.35);\n  float ringsR=sin(dR*u_depthRingFreq-t*3.0)*0.5+0.5;\n  ringsR*=cR*(0.4+mid*0.35);\n  float eyeRings=(ringsL+ringsR)*blink;\n  float eyes=(cL+cR)*blink;\n  float gL=exp(-dL*4.0);\n  float gR=exp(-dR*4.0);\n  float eyeGlow=(gL+gR)*blink;\n\n  // === THIRD EYE — dream mandala ===\n  vec2 tePos=vec2(0.0,0.28);\n  float teDist=length(uv-tePos);\n  float teSize=u_thirdEyeSize;\n  float thirdEye=smoothstep(teSize,teSize*0.15,teDist)*(1.0+hit);\n  float mandala=sin(teDist*u_mandalaFreq-t*2.0)*0.5+0.5;\n  mandala*=smoothstep(teSize*3.5,teSize,teDist)*smoothstep(0.0,teSize*0.4,teDist);\n  float teGlow=exp(-teDist*8.0)*(0.6+sin(t*1.5)*0.2)*u_thirdEyeBright;\n\n  // === NOSE ===\n  float nose=smoothstep(0.03,0.008,abs(uv.x))\n    *smoothstep(0.08,0.0,uv.y)*smoothstep(-0.18,0.0,uv.y)*0.4;\n\n  // === MOUTH — knowing curve ===\n  float mY=u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0)))+sin(t*0.15)*0.02;\n  vec2 mp=uv-vec2(0.0,mY);\n  float mW=0.35;\n  float jawM=smoothstep(mW,0.0,abs(mp.x));\n  float mThick=0.03+u_talk*0.045+sin(t*0.18)*0.006;\n  float curv=mp.x*mp.x*0.7;\n  float mLine=smoothstep(mThick,0.003,abs(mp.y-curv))*jawM;\n\n  // === FLOWING DATA STREAMS ===\n  float streams=0.0;\n  for(int i=0;i<3;i++){\n    float fi=float(i);\n    float sy=uv.y*(22.0+fi*10.0)+t*(1.2+fi*0.4)+fi*3.14;\n    float sx=sin(uv.y*10.0+t*0.7+fi*2.0)*0.04;\n    streams+=pow(sin(sy)*0.5+0.5,8.0)*u_streamDensity\n      *smoothstep(0.25,0.0,abs(uv.x-sx-(fi-1.0)*0.06));\n  }\n\n  // === HEARTBEAT PULSE ===\n  float heartbeat=(exp(-mod(t*u_heartbeatRate,2.5)*3.0)+bass*.65)*u_heartbeatStr;\n\n  // === DREAM PARTICLES ===\n  float particles=0.0;\n  for(int i=0;i<6;i++){\n    float fi=float(i);\n    float pa=fi*1.047+t*(0.25+fi*0.07);\n    float pb=fi*0.618+t*0.18;\n    float pr=0.72+sin(pb)*0.15;\n    vec2 sp=vec2(cos(pa),sin(pa+sin(pb)*0.5))*pr;\n    particles+=exp(-length(uv-sp)*25.0)*u_particleBright*(1.0+high);\n  }\n\n  // === COMPOSE — gold-warmed palette ===\n  vec3 eyeCol=u_eyeColor;\n  vec3 skullCol=u_skullColor;\n  vec3 purple=vec3(0.6,0.15,1.0);\n  vec3 hotEye=mix(eyeCol,vec3(1.0,0.95,0.9),0.4);\n  float gw=u_goldWarmth;\n  vec3 coronaCol=mix(eyeCol,mix(purple,gold,gw),0.3+sin(a*2.0+t)*0.2);\n  vec3 thirdEyeCol=mix(gold,eyeCol,1.0-gw);\n\n  float fg=u_faceGlow;\n  float eb=u_eyeBright;\n  float cw=u_coronaW;\n\n  vec3 col=vec3(0.0);\n  col+=coronaCol*corona*2.0*cw;\n  col+=skullCol*face*(0.45+fTex*0.55)*fg;\n  col+=mix(skullCol,gold,gw*0.6)*echoFace*fg;\n  col+=hotEye*eyes*3.5*eb;\n  col+=eyeCol*eyeGlow*2.0*eb;\n  col+=mix(eyeCol,gold,gw)*eyeRings*eb;\n  col+=thirdEyeCol*thirdEye*3.0*eb;\n  col+=thirdEyeCol*mandala*0.8*eb;\n  col+=thirdEyeCol*teGlow*1.5*fg;\n  col+=eyeCol*nose*fg;\n  col+=mix(eyeCol,gold,gw*0.7)*mLine*1.8*fg;\n  col+=mix(eyeCol,gold,gw)*streams*face;\n  col+=mix(eyeCol,gold,gw*1.3)*particles;\n  col+=skullCol*heartbeat*face*fg;\n  col+=(eyeCol*eyes*2.0*eb+purple*corona*0.5*cw)*u_hover;\n  col+=mix(eyeCol,gold,gw*0.7)*exp(-r*2.5)*face*0.3*fg;\n\n  float alpha=face*0.85*fg+corona*0.6*cw+eyeGlow*0.7*eb\n    +eyes*0.5*eb+particles*0.3+nose*0.3*fg+mLine*0.7*fg\n    +echoFace*0.35*fg+thirdEye*0.5*eb+mandala*0.25*eb\n    +teGlow*0.3*fg+eyeRings*0.2*eb+heartbeat*face*0.25;\n  alpha=clamp(alpha,0.0,1.0);\n  alpha*=smoothstep(1.0,0.7,r);\n\n  gl_FragColor=vec4(col*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p),ang=atan(p.y,p.x);\n float petals=pow(abs(cos(ang*7.+t*.16)),16.)\n   *gfArtRing(p-vec2(0.,.02),.69+.035*sin(ang*3.+t*.2),.025);\n float inner=pow(abs(sin(ang*5.-t*.21)),12.)*gfArtRing(p-vec2(0.,.05),.49,.018);\n vec2 third=p-vec2(0.,.39);\n float iris=gfArtRing(third,.075+.010*hit,.010)+exp(-dot(third,third)*520.);\n float pollen=pow(gfArtHash(floor((p+1.)*73.)+floor(t*1.7)),44.)\n   *smoothstep(.90,.30,r)*(1.+high);\n float lucid=exp(-abs(sin((r*28.-t*1.2)+sin(ang*4.)*1.7))*13.)*head*.08;\n c+=mix(eye,vec3(.73,.29,1.),.50)*(petals*(.48+bass*.36)\n   +inner*(.32+mid*.42)+lucid*(1.+mid));\n c+=mix(warm,eye,.28)*(iris*(.82+hit*1.45)+pollen*(.74+high*.62));\n a+=petals*.16+inner*.12+iris*.28+pollen*.12+lucid*.05;\n c*=1.150*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.800+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v4.0","title":"The Architect","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.1,"bgAlphaScale":1.6,"bgAlphaMax":1,"bgTintR":0.04,"bgTintG":0.98,"bgTintB":0.18,"tunerFadeSpeed":200,"orbFaceGlow":1.08,"orbEyeBright":0.96,"orbCoronaW":1.35,"orbEyeSize":0.13,"orbMouthY":-0.28,"orbScanFreq":41,"orbSkullSize":1.1,"orbScale":1.3,"orbEyeR":0.06,"orbEyeG":0.96,"orbEyeB":0.24,"orbSkullR":0.12,"orbSkullG":0.2,"orbSkullB":0.55,"gridDensity":4,"gridBright":1,"latticeArcs":6,"latticeSpin":0.03,"fovealRings":11,"fovealPulse":0.24,"compassSize":0.1,"compassSpin":0.3,"pipeDensity":0.6,"pipeSpeed":0.5,"amberWarmth":1,"blueprintAlpha":0.52,"structurePulse":0.8},"bgShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\nvoid main(){\n  vec2 uv=v_uv;\n  vec2 c=uv-0.5;\n  float r=length(c);\n  float a=atan(c.y,c.x);\n  float t=u_time;\n\n  vec3 cyan=vec3(0.3,0.85,1.0);\n  vec3 amber=vec3(1.0,0.65,0.1);\n  vec3 deep=vec3(0.01,0.03,0.08);\n  vec3 tint=u_tint;\n\n  // Major grid\n  vec2 g1=fract(uv*6.0)-0.5;\n  float majorGrid=smoothstep(0.03,0.0,min(abs(g1.x),abs(g1.y)));\n  // Minor grid\n  vec2 g2=fract(uv*24.0)-0.5;\n  float minorGrid=smoothstep(0.04,0.0,min(abs(g2.x),abs(g2.y)))*0.15;\n\n  float gridPulse=0.5+0.5*sin(t*0.2+r*8.0);\n  float grid=(majorGrid*0.4+minorGrid)*gridPulse;\n\n  // Structural radial lines — like compass bearings\n  float radials=0.0;\n  for(int i=0;i<8;i++){\n    float fi=float(i);\n    float ra=fi*0.785+t*0.02;\n    float diff=abs(mod(a-ra+3.14159,6.28318)-3.14159);\n    radials+=exp(-diff*25.0)*smoothstep(0.0,0.05,r)*0.2;\n  }\n\n  // Concentric precision rings\n  float rings=0.0;\n  for(int i=0;i<4;i++){\n    float fi=float(i);\n    float rr=0.1+fi*0.1;\n    rings+=smoothstep(0.004,0.0,abs(r-rr))*0.3;\n  }\n\n  // Construction markers at intersections\n  float markers=0.0;\n  for(int i=0;i<6;i++){\n    float fi=float(i);\n    float ma=fi*1.047+t*0.05;\n    float mr=0.2+fi*0.04;\n    vec2 mp=vec2(cos(ma),sin(ma))*mr+0.5;\n    markers+=exp(-length(uv-mp)*60.0)*0.5;\n  }\n\n  // Pulse wave from center\n  float pulse=smoothstep(0.015,0.0,abs(r-mod(t*0.15,0.6)))*0.3;\n\n  vec3 col=deep;\n  col+=mix(cyan,tint,0.5)*grid*0.5;\n  col+=cyan*radials;\n  col+=mix(cyan,amber,0.3)*rings;\n  col+=amber*markers;\n  col+=mix(cyan,amber,0.5)*pulse;\n\n  float vig=smoothstep(0.75,0.2,r);\n  col*=0.35+vig*0.65;\n\n  float intensity=max(col.r,max(col.g,col.b));\n  float alpha=u_alphaBase+intensity*u_alphaScale;\n  alpha=min(alpha,u_alphaMax);\n  vec2 edge=abs(uv-0.5)*2.0;\n  alpha*=1.0-smoothstep(0.85,1.0,max(edge.x,edge.y));\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_atmoW;\nuniform float u_wideW;\nuniform float u_flickBase;\nuniform float u_flashThresh;\nuniform float u_boltMult;\n#define MAX_ARCS 32\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform int u_arcCount;\n\nfloat hash(float n){return fract(sin(n)*43758.5453);}\nfloat noise1d(float p){\n  float i=floor(p);float f=fract(p);\n  f=f*f*(3.0-2.0*f);\n  return mix(hash(i),hash(i+1.0),f);\n}\n\nfloat circuit(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<0.5)return 0.0;\n\n  // Right-angle routing: go horizontal first, then vertical\n  vec2 mid=vec2(b.x,a.y);\n  float seg1Len=length(mid-a);\n  float seg2Len=length(b-mid);\n  float totalLen=seg1Len+seg2Len;\n  if(totalLen<0.5)return 0.0;\n\n  // Segment 1: horizontal\n  float d1=1e6;\n  if(seg1Len>0.5){\n    vec2 dir1=normalize(mid-a);\n    vec2 n1=vec2(-dir1.y,dir1.x);\n    float along1=dot(p-a,dir1);\n    float perp1=abs(dot(p-a,n1));\n    if(along1>=0.0&&along1<=seg1Len)\n      d1=perp1;\n  }\n\n  // Segment 2: vertical\n  float d2=1e6;\n  if(seg2Len>0.5){\n    vec2 dir2=normalize(b-mid);\n    vec2 n2=vec2(-dir2.y,dir2.x);\n    float along2=dot(p-mid,dir2);\n    float perp2=abs(dot(p-mid,n2));\n    if(along2>=0.0&&along2<=seg2Len)\n      d2=perp2;\n  }\n\n  // Corner node glow\n  float corner=exp(-length(p-mid)*0.05)*0.4;\n\n  float dist=min(d1,d2);\n  float core=exp(-dist*u_coreW*0.8/totalLen);\n  float glow=exp(-dist*u_glowW*0.4/totalLen)*0.4;\n\n  // Data packets flowing along the trace\n  float packetPos=fract(t*0.8+seed*0.37);\n  float packetDist;\n  if(packetPos*totalLen<seg1Len){\n    vec2 pp=a+normalize(mid-a)*packetPos*totalLen;\n    packetDist=length(p-pp);\n  } else {\n    float rem=packetPos*totalLen-seg1Len;\n    vec2 pp=mid+normalize(b-mid)*rem;\n    packetDist=length(p-pp);\n  }\n  float packet=exp(-packetDist*0.03)*1.5;\n\n  float active=u_flickBase+(1.0-u_flickBase)*\n    noise1d(t*6.0+seed*50.0);\n\n  return (core+glow+corner+packet)*active;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n  vec3 cyan=vec3(0.3,0.85,1.0);\n  vec3 amber=vec3(1.0,0.65,0.1);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=circuit(px,u_arcStart[i],u_arcEnd[i],u_time,float(i)*7.7+13.1);\n    vec3 arcCol=mix(u_arcColor[i],mix(cyan,amber,0.3),0.3);\n    col+=arcCol*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,vec3(0.9,0.95,1.0),smoothstep(0.7,2.0,intensity)*0.4);\n  float alpha=min(intensity*1.3,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec4 u_cymatics;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v4.0 Architect uniforms\nuniform float u_gridDensity;\nuniform float u_gridBright;\nuniform float u_latticeArcs;\nuniform float u_latticeSpin;\nuniform float u_fovealRings;\nuniform float u_fovealPulse;\nuniform float u_compassSize;\nuniform float u_compassSpin;\nuniform float u_pipeDensity;\nuniform float u_pipeSpeed;\nuniform float u_amberWarmth;\nuniform float u_blueprintAlpha;\nuniform float u_structurePulse;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  vec3 amber=vec3(1.0,0.65,0.1);\n  vec3 cyan=vec3(0.3,0.85,1.0);\n  vec3 white=vec3(0.9,0.95,1.0);\n\n  // === CONSTRUCTION GRID — blueprint substrate ===\n  float gd=u_gridDensity;\n  vec2 gridUV=uv*gd;\n  float gx=abs(fract(gridUV.x)-0.5);\n  float gy=abs(fract(gridUV.y)-0.5);\n  float gridLine=min(gx,gy);\n  float grid=smoothstep(0.04,0.0,gridLine)*u_gridBright;\n  float gridFade=smoothstep(1.0,0.3,r);\n  grid*=gridFade;\n  float gridPulse=0.5+0.5*sin(t*0.3+r*6.0);\n  grid*=0.3+gridPulse*0.7;\n\n  // === STRUCTURAL LATTICE CORONA — geometric arcs ===\n  float corona=0.0;\n  float nArcs=u_latticeArcs;\n  for(int i=0;i<6;i++){\n    float fi=float(i);\n    if(fi>=nArcs)break;\n    float arcA=fi*3.14159/nArcs+t*u_latticeSpin*(1.0+fi*0.15);\n    float arcR=0.55+fi*0.06;\n    vec2 arcCenter=vec2(cos(arcA),sin(arcA))*0.02;\n    float arcDist=abs(length(uv-arcCenter)-arcR);\n    float arcLine=smoothstep(0.015,0.0,arcDist);\n    float arcSeg=step(0.3,fract(a/(6.28318/8.0)+fi*0.5+t*0.1));\n    corona+=arcLine*arcSeg*0.6;\n  }\n  float cMask=smoothstep(0.95,0.5,r)*smoothstep(0.42,0.55,r);\n  corona*=cMask;\n  float structP=0.7+0.3*sin(t*u_structurePulse+a*2.0);\n  corona*=structP*(1.0+u_hover*0.6);\n\n  // Lattice node points at arc intersections\n  float nodes=0.0;\n  for(int i=0;i<8;i++){\n    float fi=float(i);\n    float na=fi*0.785+t*u_latticeSpin*0.5;\n    float nr=0.62+sin(t*0.4+fi*1.3)*0.04;\n    vec2 np=vec2(cos(na),sin(na))*nr;\n    nodes+=exp(-length(uv-np)*40.0)*0.5;\n  }\n\n  // === SKULL — geometric construction ===\n  float sk=u_skullSize;\n  float skull=smoothstep(0.72*sk,0.48*sk,r)*smoothstep(-0.7,-0.05,uv.y);\n  float jaw=smoothstep(0.55*sk,0.28*sk,r)*smoothstep(0.2,-0.65,uv.y)\n    *smoothstep(0.50*sk,0.18*sk,abs(uv.x));\n  float face=max(skull,jaw);\n\n  // Blueprint wireframe over skull\n  float skullEdge=abs(r-0.52*sk);\n  float wireSkull=smoothstep(0.02,0.0,skullEdge)*face*u_blueprintAlpha;\n  float jawEdge=abs(r-0.35*sk);\n  float wireJaw=smoothstep(0.02,0.0,jawEdge)*jaw*u_blueprintAlpha;\n  float wireframe=wireSkull+wireJaw;\n\n  float fTex=noise(uv*4.0+vec2(t*0.08,t*0.1));\n  fTex=fTex*0.4+noise(uv*8.0-t*0.06)*0.3;\n\n  // === EYES — foveal precision lenses ===\n  float blinkRaw=fract(t*0.2);\n  float blink=1.0-(smoothstep(0.0,0.03,blinkRaw)\n    *smoothstep(0.08,0.05,blinkRaw));\n  vec2 eL=vec2(-0.22,0.13);\n  vec2 eR=vec2(0.22,0.13);\n  float eS=u_eyeSize+u_hover*0.02;\n  float dL=length(uv-eL);\n  float dR=length(uv-eR);\n  float cL=smoothstep(eS,eS*0.1,dL);\n  float cR=smoothstep(eS,eS*0.1,dR);\n\n  // Foveal rings: high detail at center, fading radially\n  float fRings=u_fovealRings;\n  float fPulse=u_fovealPulse;\n  float ringsL=0.0; float ringsR=0.0;\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    float ringR=(fi+1.0)*eS*0.22;\n    float ringW=0.003+fi*0.001;\n    float ringBright=1.0-fi*0.18;\n    float segL=step(0.4,fract(atan(uv.y-eL.y,uv.x-eL.x)\n      /(6.28318/fRings)+fi*0.3+t*fPulse));\n    float segR=step(0.4,fract(atan(uv.y-eR.y,uv.x-eR.x)\n      /(6.28318/fRings)+fi*0.3+t*fPulse));\n    ringsL+=smoothstep(ringW,0.0,abs(dL-ringR))\n      *ringBright*segL;\n    ringsR+=smoothstep(ringW,0.0,abs(dR-ringR))\n      *ringBright*segR;\n  }\n  ringsL*=smoothstep(eS*1.5,eS*0.5,dL)*blink*0.5;\n  ringsR*=smoothstep(eS*1.5,eS*0.5,dR)*blink*0.5;\n  float eyeRings=ringsL+ringsR;\n\n  // Core eye glow\n  float eyes=(cL+cR)*blink;\n  float gL=exp(-dL*5.0);\n  float gR=exp(-dR*5.0);\n  float eyeGlow=(gL+gR)*blink;\n\n  // Crosshair reticles in eye centers\n  float xhL=smoothstep(0.006,0.0,abs(uv.x-eL.x))\n    *smoothstep(eS*0.8,0.0,abs(uv.y-eL.y));\n  float xhR=smoothstep(0.006,0.0,abs(uv.x-eR.x))\n    *smoothstep(eS*0.8,0.0,abs(uv.y-eR.y));\n  float xhYL=smoothstep(0.006,0.0,abs(uv.y-eL.y))\n    *smoothstep(eS*0.8,0.0,abs(uv.x-eL.x));\n  float xhYR=smoothstep(0.006,0.0,abs(uv.y-eR.y))\n    *smoothstep(eS*0.8,0.0,abs(uv.x-eR.x));\n  float crosshairs=(xhL+xhR+xhYL+xhYR)*blink*0.35;\n\n  // === THIRD EYE — compass rose / drafting symbol ===\n  vec2 tePos=vec2(0.0,0.28);\n  float teDist=length(uv-tePos);\n  float teA=atan(uv.y-tePos.y,uv.x-tePos.x);\n  float cSize=u_compassSize;\n  float cSpin=u_compassSpin;\n\n  // Compass cardinal lines\n  float cardinal=0.0;\n  for(int i=0;i<4;i++){\n    float fi=float(i);\n    float ca=fi*1.5708+t*cSpin;\n    float diff=abs(mod(teA-ca+3.14159,6.28318)-3.14159);\n    cardinal+=smoothstep(0.06,0.0,diff)\n      *smoothstep(cSize*2.5,cSize*0.3,teDist)*0.6;\n  }\n  // Compass ordinal lines (thinner)\n  for(int i=0;i<4;i++){\n    float fi=float(i);\n    float ca=fi*1.5708+0.7854+t*cSpin;\n    float diff=abs(mod(teA-ca+3.14159,6.28318)-3.14159);\n    cardinal+=smoothstep(0.04,0.0,diff)\n      *smoothstep(cSize*1.8,cSize*0.5,teDist)*0.3;\n  }\n  // Compass circle\n  float compassRing=smoothstep(0.008,0.0,abs(teDist-cSize));\n  float compassRing2=smoothstep(0.005,0.0,abs(teDist-cSize*0.5));\n  float compass=cardinal+compassRing*0.7+compassRing2*0.4;\n  float compassGlow=exp(-teDist*10.0)*0.5;\n\n  // === NOSE ===\n  float nose=smoothstep(0.03,0.008,abs(uv.x))\n    *smoothstep(0.08,0.0,uv.y)*smoothstep(-0.18,0.0,uv.y)*0.4;\n\n  // === MOUTH — precise architectural line ===\n  float mY=u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0)))+sin(t*0.12)*0.015;\n  vec2 mp=uv-vec2(0.0,mY);\n  float mW=0.32;\n  float jawM=smoothstep(mW,0.0,abs(mp.x));\n  float mThick=0.025+u_talk*0.045+sin(t*0.15)*0.004;\n  float curv=mp.x*mp.x*0.5;\n  float mLine=smoothstep(mThick,0.002,abs(mp.y-curv))*jawM;\n  // Tick marks along mouth like a ruler\n  float ticks=step(0.92,fract(mp.x*18.0))*jawM\n    *smoothstep(mThick*3.0,mThick,abs(mp.y-curv))*0.3;\n\n  // === PIPELINE TRACES — gem-pipe circuit paths ===\n  float pipes=0.0;\n  for(int i=0;i<4;i++){\n    float fi=float(i);\n    float py=fi*0.12-0.18;\n    float pWave=sin(uv.x*12.0+t*u_pipeSpeed+fi*2.5)*0.03;\n    float pDist=abs(uv.y-py-pWave);\n    float pLine=smoothstep(0.008,0.0,pDist)*u_pipeDensity;\n    // Data packets flowing along the pipe\n    float packet=pow(fract(uv.x*4.0-t*u_pipeSpeed*0.3\n      +fi*0.25),12.0)*3.0;\n    pLine*=0.4+packet*0.6;\n    pipes+=pLine*face*smoothstep(0.35,0.15,abs(uv.x));\n  }\n\n  // === STRUCTURAL PULSE — alive indicator ===\n  float pulse=exp(-mod(t*0.8,3.0)*2.0)*u_structurePulse;\n  float pulseRing=smoothstep(0.02,0.0,\n    abs(r-mod(t*0.4,0.8)))*pulse;\n\n  // === COMPOSE — cyan/amber architectural palette ===\n  float aw=u_amberWarmth;\n  vec3 cyanLine=mix(cyan,white,0.3);\n  vec3 amberHot=mix(amber,white,0.4);\n  vec3 eyeCol=u_eyeColor;\n  vec3 skullCol=u_skullColor;\n\n  float fg=u_faceGlow;\n  float eb=u_eyeBright;\n  float cw=u_coronaW;\n\n  vec3 col=vec3(0.0);\n  // Blueprint grid substrate\n  col+=mix(cyan,amber,aw*0.3)*grid*0.3*u_blueprintAlpha;\n  // Structural lattice corona\n  col+=mix(cyanLine,amberHot,aw*0.5)*corona*2.0*cw;\n  col+=mix(cyan,amber,aw)*nodes*cw;\n  // Skull with construction lines\n  col+=skullCol*face*(0.35+fTex*0.45)*fg;\n  col+=cyanLine*wireframe*0.6*fg;\n  // Foveal lens eyes\n  col+=mix(eyeCol,white,0.5)*eyes*3.5*eb;\n  col+=eyeCol*eyeGlow*1.8*eb;\n  col+=cyanLine*eyeRings*1.5*eb;\n  col+=amberHot*crosshairs*eb;\n  // Compass rose third eye\n  col+=mix(amber,cyan,0.3)*compass*1.5*eb;\n  col+=mix(amber,white,0.5)*compassGlow*fg;\n  // Features\n  col+=cyanLine*nose*fg;\n  col+=mix(cyan,amber,aw*0.6)*mLine*1.5*fg;\n  col+=amberHot*ticks*fg;\n  // Pipeline traces\n  col+=mix(cyan,amber,aw)*pipes*1.2;\n  // Structural pulse\n  col+=mix(cyan,amber,aw*0.7)*pulseRing*0.8;\n  col+=skullCol*pulse*face*fg*0.3;\n  // Hover response\n  col+=(eyeCol*eyes*2.0*eb\n    +cyanLine*corona*0.4*cw)*u_hover;\n  // Center glow\n  col+=mix(cyan,amber,aw*0.5)*exp(-r*2.5)\n    *face*0.25*fg;\n\n  float alpha=face*0.8*fg+corona*0.55*cw\n    +eyeGlow*0.6*eb+eyes*0.5*eb\n    +nodes*0.3*cw+compass*0.4*eb\n    +crosshairs*0.3*eb+eyeRings*0.3*eb\n    +wireframe*0.3*fg+pipes*0.4\n    +nose*0.3*fg+mLine*0.6*fg\n    +grid*0.15*u_blueprintAlpha\n    +pulseRing*0.3+pulse*face*0.15;\n  alpha=clamp(alpha,0.0,1.0);\n  alpha*=smoothstep(1.0,0.7,r);\n\n  gl_FragColor=vec4(col*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float outer=gfArtBox(p-vec2(0.,-.02),vec2(.63,.76),.012);\n float golden=gfArtBox(p-vec2(0.,.02),vec2(.39,.63),.008);\n float axes=gfArtSeg(p,vec2(-.68,.13),vec2(.68,.13),.006)\n   +gfArtSeg(p,vec2(0.,-.68),vec2(0.,.72),.006);\n vec2 compass=p-vec2(0.,.43);float ca=atan(compass.y,compass.x);\n float rose=pow(abs(cos(ca*8.-t*.12)),28.)*gfArtRing(compass,.12+.015*hit,.014);\n float sections=gfArtLine(abs(p.x)-(.30-.11*p.y),.008)*head;\n sections+=gfArtLine(abs(p.y+.18)-(.055+.018*sin(p.x*18.)),.008)*head;\n float rulers=pow(.5+.5*cos(atan(p.y,p.x)*40.),45.)*gfArtRing(p,.72,.022);\n c+=mix(eye,vec3(.58,.88,1.),.42)*(outer*(.33+bass*.25)+golden*.24\n   +axes*.10+sections*(.25+mid*.34)+rulers*(.32+high*.42));\n c+=warm*rose*(.78+hit*1.35);\n a+=outer*.11+golden*.08+axes*.04+sections*.09+rulers*.12+rose*.25;\n c*=1.350*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.880+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v5.0","title":"The Lamplighter","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.05,"bgAlphaScale":0.1,"bgAlphaMax":1,"bgTintR":0,"bgTintG":0.64,"bgTintB":1,"tunerFadeSpeed":200,"orbFaceGlow":0.88,"orbEyeBright":0.28,"orbCoronaW":1.2,"orbEyeSize":0.27,"orbMouthY":-0.31,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.2,"orbEyeR":1,"orbEyeG":0.54,"orbEyeB":0.06,"orbSkullR":0.3,"orbSkullG":0.18,"orbSkullB":0.08,"flameFlicker":4,"glassRefract":1.5,"causticScale":1,"causticSpeed":0.14,"wickBright":0.75,"wickSize":0.085,"lanternWarmth":0.3,"godrayCount":10,"godrayLength":0.6,"fogDensity":0.24,"breathRate":0.5,"glassThick":0.06,"starfield":0.7},"bgShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nvoid main(){\n  vec2 uv=v_uv*2.0-1.0;\n  float r=length(uv);\n  float t=u_time;\n\n  // Deep void gradient — navy to black\n  vec3 deep=vec3(0.02,0.03,0.08);\n  vec3 mid=vec3(0.04,0.05,0.12);\n  vec3 col=mix(mid,deep,smoothstep(0.0,1.2,r));\n\n  // Mathematical stars — points of light at stable positions\n  for(int i=0;i<40;i++){\n    float fi=float(i);\n    vec2 sp=vec2(hash(vec2(fi,0.0)),hash(vec2(0.0,fi)))*2.0-1.0;\n    float sd=length(uv-sp);\n    float twinkle=0.5+0.5*sin(t*hash(vec2(fi,fi))*3.0+fi);\n    float star=exp(-sd*200.0)*twinkle;\n    float warmth=hash(vec2(fi*3.7,fi*1.3));\n    vec3 sc=mix(vec3(0.6,0.7,1.0),vec3(1.0,0.85,0.5),warmth);\n    col+=sc*star*0.4;\n  }\n\n  // Subtle radial warmth from center (lantern spill)\n  vec3 warm=vec3(0.3,0.15,0.05);\n  col+=warm*exp(-r*1.5)*0.15;\n\n  float alpha=u_alphaBase+length(col)*u_alphaScale;\n  alpha=min(alpha,u_alphaMax);\n  gl_FragColor=vec4(col*u_tint*alpha,alpha);\n}","boltShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\n#define MAX_ARCS 12\nuniform int u_arcCount;\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform float u_boltMult;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_flickBase;\n\nfloat hash(float p){return fract(sin(p*127.1)*43758.5453);}\n\nfloat lightRay(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<1.0)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n\n  float along=dot(p-a,dir);\n  float perp=abs(dot(p-a,n));\n\n  float inBeam=smoothstep(-10.0,0.0,along)\n    *smoothstep(len+10.0,len,along);\n\n  // Beam widens toward end like a light cone\n  float progress=along/len;\n  float width=mix(2.0,8.0+sin(t*0.5+seed)*3.0,\n    progress*progress);\n\n  float core=exp(-perp*u_coreW/width);\n  float glow=exp(-perp*u_glowW*0.3/width)*0.3;\n\n  // Dust motes in the beam\n  float mote=hash(floor(along*0.02)+seed*17.3);\n  mote=mote*mote*step(0.8,mote);\n  float moteBright=mote*exp(-perp*0.2)*\n    smoothstep(0.0,0.3,progress);\n\n  float flicker=u_flickBase+(1.0-u_flickBase)*\n    (0.85+0.15*sin(t*8.0+seed*50.0));\n\n  return (core+glow+moteBright)*inBeam*flicker;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n  vec3 honey=vec3(1.0,0.78,0.3);\n  vec3 pale=vec3(1.0,0.92,0.75);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=lightRay(px,u_arcStart[i],u_arcEnd[i],\n      u_time,float(i)*7.7+13.1);\n    vec3 rayCol=mix(u_arcColor[i],mix(honey,pale,0.3),0.4);\n    col+=rayCol*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,pale,smoothstep(0.8,2.0,intensity)*0.3);\n  float alpha=min(intensity*1.2,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec4 u_cymatics;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v5.0 Lamplighter uniforms\nuniform float u_flameFlicker;\nuniform float u_glassRefract;\nuniform float u_causticScale;\nuniform float u_causticSpeed;\nuniform float u_wickBright;\nuniform float u_wickSize;\nuniform float u_lanternWarmth;\nuniform float u_godrayCount;\nuniform float u_godrayLength;\nuniform float u_fogDensity;\nuniform float u_breathRate;\nuniform float u_glassThick;\nuniform float u_starfield;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nfloat fbm(vec2 p){\n  float v=0.0;float a=0.5;\n  for(int i=0;i<4;i++){v+=a*noise(p);p*=2.17;a*=0.5;}\n  return v;\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  vec3 honey=vec3(1.0,0.78,0.3);\n  vec3 flame=vec3(1.0,0.55,0.1);\n  vec3 pale=vec3(1.0,0.92,0.75);\n  vec3 deep=vec3(0.05,0.08,0.18);\n\n  // Breathing rhythm — the lamp lives\n  float breath=0.5+0.5*sin(t*u_breathRate);\n  float flicker=0.85+0.15*sin(t*u_flameFlicker\n    +noise(vec2(t*3.0,0.0))*6.0);\n\n  // === LANTERN GLOW — warm light radiating from center ===\n  float glow=exp(-r*2.2)*u_lanternWarmth;\n  glow*=flicker;\n\n  // === CAUSTIC CORONA — light through imperfect glass ===\n  float caustics=0.0;\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    float ca=a*(3.0+fi)+t*u_causticSpeed*(0.3+fi*0.1);\n    float cr=r*(u_causticScale+fi*1.5)-t*0.2;\n    float band=sin(ca)*cos(cr+sin(ca*0.5+t*0.3)*0.8);\n    caustics+=band*band*0.12;\n  }\n  float glassMask=smoothstep(0.95,0.55,r)\n    *smoothstep(0.35,0.5,r);\n  caustics*=glassMask*u_glassRefract;\n\n  // Glass edge ring — the lantern housing\n  float glassRing=smoothstep(0.015,0.0,\n    abs(r-0.58))*u_glassThick;\n  float glassRing2=smoothstep(0.008,0.0,\n    abs(r-0.52))*u_glassThick*0.5;\n  float glass=glassRing+glassRing2;\n\n  // === GOD RAYS — light beams through fog ===\n  float rays=0.0;\n  float nRays=u_godrayCount;\n  for(int i=0;i<12;i++){\n    float fi=float(i);\n    if(fi>=nRays)break;\n    float ra=fi*6.28318/nRays+t*0.04;\n    float diff=abs(mod(a-ra+3.14159,6.28318)-3.14159);\n    float ray=smoothstep(0.12,0.0,diff)\n      *smoothstep(0.5,0.6+u_godrayLength,r);\n    float rayFade=exp(-(r-0.5)*3.0/u_godrayLength);\n    float rayFlicker=0.7+0.3*sin(t*2.0+fi*2.5);\n    rays+=ray*rayFade*rayFlicker;\n  }\n  rays*=u_fogDensity*flicker;\n\n  // === FACE — emerging from warm light ===\n  float sk=u_skullSize;\n  float skull=smoothstep(0.68*sk,0.42*sk,r)\n    *smoothstep(-0.7,-0.05,uv.y);\n  float jaw=smoothstep(0.50*sk,0.25*sk,r)\n    *smoothstep(0.2,-0.60,uv.y)\n    *smoothstep(0.45*sk,0.15*sk,abs(uv.x));\n  float face=max(skull,jaw);\n\n  // Face texture — warm turbulence like firelight on skin\n  float fTex=fbm(uv*3.0+vec2(t*0.05,t*0.07));\n  float fTex2=fbm(uv*6.0-vec2(t*0.04,t*0.03));\n  float faceTex=fTex*0.5+fTex2*0.3;\n\n  // Soft edge — face fades into light, not hard boundary\n  float faceEdge=smoothstep(0.5*sk,0.35*sk,r);\n\n  // === EYES — twin steady flames ===\n  float blinkRaw=fract(t*0.15);\n  float blink=1.0-(smoothstep(0.0,0.04,blinkRaw)\n    *smoothstep(0.09,0.05,blinkRaw));\n  vec2 eL=vec2(-0.21,0.12);\n  vec2 eR=vec2(0.21,0.12);\n  float eS=u_eyeSize+u_hover*0.015;\n  float dL=length(uv-eL);\n  float dR=length(uv-eR);\n\n  // Flame-shaped eyes: stretch upward\n  float eyeFlameL=smoothstep(eS,eS*0.1,dL)\n    *(1.0+max(0.0,eL.y-uv.y+eS)*3.0\n    *exp(-abs(uv.x-eL.x)*20.0));\n  float eyeFlameR=smoothstep(eS,eS*0.1,dR)\n    *(1.0+max(0.0,eR.y-uv.y+eS)*3.0\n    *exp(-abs(uv.x-eR.x)*20.0));\n\n  // Eye flicker — each flame dances independently\n  float fL=0.8+0.2*sin(t*u_flameFlicker*1.3\n    +noise(vec2(t*4.0,1.0))*4.0);\n  float fR=0.8+0.2*sin(t*u_flameFlicker*1.1\n    +noise(vec2(t*4.0,2.0))*4.0);\n  float eyes=(eyeFlameL*fL+eyeFlameR*fR)*blink;\n\n  // Eye glow — warm light spilling from the flames\n  float gL=exp(-dL*4.0)*blink*fL;\n  float gR=exp(-dR*4.0)*blink*fR;\n  float eyeGlow=(gL+gR)*0.8;\n\n  // === THIRD EYE — the wick ===\n  vec2 wPos=vec2(0.0,0.27);\n  float wDist=length(uv-wPos);\n  float wA=atan(uv.y-wPos.y,uv.x-wPos.x);\n\n  // Wick filament — thin bright vertical line\n  float wick=smoothstep(0.012,0.0,abs(uv.x-wPos.x))\n    *smoothstep(u_wickSize,0.0,abs(uv.y-wPos.y))\n    *u_wickBright;\n\n  // Wick flame — tiny dancing fire at the tip\n  vec2 wickTip=wPos+vec2(0.0,u_wickSize*0.8);\n  float wfDist=length(uv-wickTip);\n  float wickFlame=exp(-wfDist*50.0)*u_wickBright\n    *(0.7+0.3*sin(t*12.0+noise(vec2(t*8.0,3.0))*5.0));\n\n  // Wick glow halo\n  float wickGlow=exp(-wDist*8.0)*u_wickBright*0.4;\n\n  // === NOSE — gentle warm highlight ===\n  float nose=smoothstep(0.025,0.006,abs(uv.x))\n    *smoothstep(0.10,0.0,uv.y)\n    *smoothstep(-0.15,0.0,uv.y)*0.35;\n\n  // === MOUTH — warm ember line ===\n  float mY=u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0)))+sin(t*0.1)*0.012;\n  vec2 mp=uv-vec2(0.0,mY);\n  float mW=0.28;\n  float jawM=smoothstep(mW,0.0,abs(mp.x));\n  float curv=mp.x*mp.x*0.4;\n  float mLine=smoothstep(0.022,0.003,abs(mp.y-curv))*jawM;\n  // Ember glow along the mouth — warmth when it speaks\n  float emberGlow=exp(-length(mp)*6.0)*jawM*0.3;\n\n  // === COMPOSE — warmth in darkness ===\n  float fg=u_faceGlow;\n  float eb=u_eyeBright;\n  float cw=u_coronaW;\n  vec3 eyeCol=u_eyeColor;\n  vec3 skullCol=u_skullColor;\n\n  vec3 col=vec3(0.0);\n\n  // Lantern glow substrate\n  col+=mix(honey,pale,0.3)*glow*1.5*fg;\n\n  // Caustic corona\n  col+=mix(honey,flame,0.4)*caustics*2.5*cw;\n  col+=mix(honey,pale,0.5)*glass*0.6*cw;\n\n  // God rays\n  col+=mix(honey,pale,0.4)*rays*0.5*cw;\n\n  // Face — warm light on form\n  col+=skullCol*face*(0.3+faceTex*0.5)*fg;\n  col+=honey*face*faceEdge*0.15*fg*breath;\n\n  // Eyes — twin flames\n  col+=mix(eyeCol,pale,0.6)*eyes*3.0*eb;\n  col+=mix(eyeCol,honey,0.3)*eyeGlow*1.5*eb;\n\n  // Wick third eye\n  col+=pale*wick*2.0;\n  col+=mix(flame,pale,0.5)*wickFlame*3.0;\n  col+=honey*wickGlow;\n\n  // Features\n  col+=mix(honey,pale,0.4)*nose*fg;\n  col+=mix(flame,honey,0.5)*mLine*1.2*fg;\n  col+=flame*emberGlow*fg;\n\n  // Hover warmth\n  col+=(eyeCol*eyes*1.5*eb\n    +honey*glow*0.3*fg)*u_hover;\n\n  // Atmospheric depth — distant starfield through the face\n  float starNoise=noise(uv*30.0+vec2(t*0.01,0.0));\n  float stars=pow(starNoise,10.0)*u_starfield\n    *smoothstep(0.4,0.7,r);\n  col+=pale*stars*0.3;\n\n  float alpha=face*0.75*fg+glow*0.6*fg\n    +caustics*0.5*cw+glass*0.4*cw\n    +eyes*0.6*eb+eyeGlow*0.5*eb\n    +wick*0.5+wickFlame*0.6+wickGlow*0.3\n    +rays*0.2*cw+nose*0.3*fg+mLine*0.5*fg\n    +emberGlow*0.3*fg+stars*0.15;\n  alpha=clamp(alpha,0.0,1.0);\n  alpha*=smoothstep(1.0,0.7,r);\n\n  gl_FragColor=vec4(col*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n vec2 ep=vec2(abs(p.x)-.22,p.y-.16);\n float flameCore=exp(-pow(ep.x/.052,2.)-pow((ep.y+.015*sin(t*3.+ep.x*12.))/.095,2.));\n float flameTip=exp(-pow(ep.x/.035,2.)-pow((ep.y-.105-.025*sin(t*4.))/.14,2.));\n float glass=gfArtLine(length(p/vec2(.64,.78))-1.,.014);\n float innerGlass=gfArtLine(length(p/vec2(.56,.69))-1.,.008);\n float ribs=gfArtLine(abs(p.x)-.50,.009)*smoothstep(.70,-.55,p.y);\n ribs+=gfArtLine(abs(p.x)-.34,.006)*smoothstep(.66,-.50,p.y);\n float wick=gfArtSeg(p,vec2(0.,-.15),vec2(0.,.34),.010);\n float caustic=pow(.5+.5*sin(atan(p.y,p.x)*9.+length(p)*27.-t*.55),18.)*glass;\n float fog=exp(-length(p-vec2(0.,.02))*2.7)*head*(.04+bass*.10);\n c+=mix(warm,vec3(1.,.98,.77),.45)*(flameCore*(.58+mid*.72)\n   +flameTip*(.30+high*.28)+wick*(.20+hit*.78));\n c+=mix(bone,warm,.68)*(glass*(.40+bass*.38)+innerGlass*.20+ribs*.16\n   +caustic*(.35+high*.55)+fog);\n a+=flameCore*.34+flameTip*.18+glass*.17+innerGlass*.08+ribs*.07+wick*.08+fog*.05;\n c*=0.950*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.820+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v6.0","title":"The Archivist","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.04,"bgAlphaScale":0.08,"bgAlphaMax":1,"bgTintR":0,"bgTintG":0.64,"bgTintB":1,"tunerFadeSpeed":200,"orbFaceGlow":1.04,"orbEyeBright":0.92,"orbCoronaW":1.1,"orbEyeSize":0.25,"orbMouthY":-0.28,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.15,"orbEyeR":1,"orbEyeG":0.82,"orbEyeB":0.45,"orbSkullR":0.35,"orbSkullG":0.22,"orbSkullB":0.1,"archiveRings":4,"threadDensity":20,"memoryWarmth":1,"pulseDepth":1,"holdStr":0.8,"fadeDistance":0.85,"grainAmt":0.15,"homeGlow":1},"bgShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nvoid main(){\n  vec2 uv=v_uv;\n  float t=u_time;\n  float r=length(uv-0.5)*2.0;\n\n  // Slow deep-space drift with warm nebula\n  float n1=noise(uv*3.0+vec2(t*0.02,t*0.015));\n  float n2=noise(uv*6.0-vec2(t*0.03,t*0.01));\n  float n3=noise(uv*1.5+vec2(n1*0.5,n2*0.5));\n\n  // Warm amber fog in deep blue void\n  vec3 deep=vec3(0.02,0.03,0.08);\n  vec3 warm=vec3(0.25,0.12,0.03);\n  vec3 col=mix(deep,warm,n3*0.4*smoothstep(1.2,0.0,r));\n\n  // Faint golden dust particles\n  float dust=hash(floor(uv*80.0)+floor(t*0.5));\n  dust=step(0.992,dust)*0.3;\n  col+=vec3(1.0,0.8,0.4)*dust;\n\n  float alpha=u_alphaBase+n3*u_alphaScale*0.5;\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_atmoW;\nuniform float u_wideW;\nuniform float u_flickBase;\nuniform float u_flashThresh;\nuniform float u_boltMult;\n#define MAX_ARCS 32\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform int u_arcCount;\n\nfloat hash(float n){return fract(sin(n)*43758.5453);}\nfloat noise1d(float p){\n  float i=floor(p);float f=fract(p);\n  f=f*f*(3.0-2.0*f);\n  return mix(hash(i),hash(i+1.0),f);\n}\n\nfloat filament(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<0.5)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  vec2 ap=p-a;\n  float along=dot(ap,dir)/len;\n  float perp=dot(ap,n);\n  if(along<-0.05||along>1.05)return 0.0;\n\n  float disp=0.0;\n  float freq=2.0;float amp=0.04*len;\n  for(int i=0;i<3;i++){\n    float fi=float(i);\n    disp+=(noise1d(along*freq+t*1.2+seed*11.3+fi*3.7)-0.5)*amp;\n    freq*=1.7;amp*=0.55;\n  }\n\n  float taper=smoothstep(0.0,0.18,along)*smoothstep(1.0,0.88,along);\n  float dist=abs(perp-disp);\n  float core=exp(-dist*u_coreW*0.7/len)*taper;\n  float glow=exp(-dist*u_glowW*0.45/len)*taper*0.45;\n  float halo=exp(-dist*u_atmoW*0.25/len)*taper*0.2;\n\n  float breathe=0.82+0.18*sin(t*0.45+seed*2.1);\n  float shimmer=0.75+0.25*sin(along*14.0-t*2.0+seed*5.0);\n  float hold=u_flickBase+(1.0-u_flickBase)*\n    (0.9+0.1*noise1d(t*3.0+seed*40.0));\n\n  return (core+glow+halo)*breathe*shimmer*hold;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n  vec3 gold=vec3(1.0,0.78,0.35);\n  vec3 amber=vec3(1.0,0.62,0.18);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=filament(px,u_arcStart[i],u_arcEnd[i],\n      u_time,float(i)*7.7+13.1);\n    vec3 arcCol=mix(u_arcColor[i],mix(gold,amber,0.35),0.45);\n    col+=arcCol*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,vec3(1.0,0.9,0.7),smoothstep(0.6,1.8,intensity)*0.35);\n  float alpha=min(intensity*1.15,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec4 u_cymatics;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v6.0-specific uniforms\nuniform float u_archiveRings;\nuniform float u_threadDensity;\nuniform float u_memoryWarmth;\nuniform float u_pulseDepth;\nuniform float u_holdStr;\nuniform float u_fadeDistance;\nuniform float u_grainAmt;\nuniform float u_homeGlow;\n// Personality (shared driver in selector.js)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nfloat fbm(vec2 p){\n  float v=0.0;float a=0.5;\n  for(int i=0;i<4;i++){v+=a*noise(p);p*=2.1;a*=0.5;}\n  return v;\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  // Warm archive palette\n  vec3 warmGold=vec3(1.0,0.75,0.3);\n  vec3 deepAmber=vec3(0.8,0.45,0.1);\n  vec3 softCream=vec3(1.0,0.92,0.78);\n  vec3 homeBlue=vec3(0.10,0.12,0.24);\n\n  // === HEAD — parchment disc with a hand-drawn double rim ===\n  // (Redo 2026-07-06: the face needs a BOUNDARY to read as a face.)\n  float wob=sin(a*9.0+t*0.4)*0.012+sin(a*5.0-t*0.25)*0.008;\n  float headR=0.58*u_skullSize+wob;\n  float head=smoothstep(headR,headR-0.05,r);\n  float rimA=exp(-abs(r-headR)*70.0);\n  float rimB=exp(-abs(r-headR*0.93)*90.0)*0.6;\n\n  // === ARCHIVE GROOVES — memory rings INSIDE the head ===\n  float rings=0.0;\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    float ringR=0.12+fi*0.10;\n    float wave=sin(a*u_archiveRings+t*0.2+fi*1.3)*0.01;\n    float d=abs(r-ringR+wave)-0.004;\n    rings+=smoothstep(0.008,0.0,d)*(0.35-fi*0.05);\n  }\n  rings*=head;\n\n  // === GOLDEN THREADS — memory strands OUTSIDE the head ===\n  float threads=0.0;\n  for(int i=0;i<8;i++){\n    float fi=float(i);\n    float ta=fi*0.785398+t*0.05+sin(t*0.1+fi)*0.2;\n    vec2 dir=vec2(cos(ta),sin(ta));\n    float proj=dot(uv,dir);\n    float perp=length(uv-dir*proj);\n    float thread=smoothstep(0.02,0.0,perp-0.005);\n    thread*=smoothstep(headR,headR+0.12,proj)*smoothstep(1.0,0.5,proj);\n    float shimmer=sin(proj*u_threadDensity-t*1.5+fi)*0.5+0.5;\n    threads+=thread*shimmer*0.3;\n  }\n\n  // === FACE GLOW — warm hearth inside the head ===\n  float core=smoothstep(headR,0.0,r);\n  core=pow(core,1.6)*(1.0+sin(t*0.4)*0.08*u_pulseDepth);\n\n  // === EYES — warm almonds: gaze, blink, catchlight ===\n  float es=u_eyeSize*0.85;\n  float lidOpen=1.0-u_blink*0.88;\n  vec2 le=vec2(-0.17,0.10)+u_gaze;\n  vec2 re=vec2(0.17,0.10)+u_gaze;\n  vec2 lq=uv-le; lq.y/=max(lidOpen,0.14);\n  vec2 rq=uv-re; rq.y/=max(lidOpen,0.14);\n  float lEye=smoothstep(es,es*0.35,length(lq));\n  float rEye=smoothstep(es,es*0.35,length(rq));\n  float eyes=(lEye+rEye)*u_eyeBright;\n  // Dark iris wells give the warm eyes FOCUS\n  float wells=smoothstep(es*0.45,es*0.15,length(lq))\n            +smoothstep(es*0.45,es*0.15,length(rq));\n  // Catchlight glimmer leads the gaze\n  vec2 lg=uv-(le+u_gaze*1.4)-vec2(0.015,0.02);\n  vec2 rg=uv-(re+u_gaze*1.4)-vec2(0.015,0.02);\n  float glimmer=(exp(-dot(lg,lg)*2600.0)+exp(-dot(rg,rg)*2600.0))*lidOpen;\n\n  // === MOUTH — a gentle line that warms into a real smile ===\n  float mY=(u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0))))*0.8;\n  float smCurve=u_smile*(uv.x*uv.x*1.5-0.035)-sin(t*0.1)*0.006;\n  float mouth=smoothstep(0.020+u_talk*0.055,0.004,abs(uv.y-mY-smCurve))\n    *smoothstep(0.20+u_smile*0.05,0.05,abs(uv.x));\n  mouth*=0.8+u_smile*1.0;\n\n  // === MEMORY TEXTURE — film grain, gated to the head ===\n  float grain=fbm(uv*6.0+t*0.05)*0.3*head;\n  float fineGrain=hash(uv*200.0+t*10.0)*u_grainAmt*head;\n\n  // === COMPOSITE ===\n  vec3 col=homeBlue*head*0.6;\n  vec3 coreCol=mix(deepAmber,softCream,core*0.5);\n  col=mix(col,coreCol,core*u_faceGlow*u_memoryWarmth*head);\n  col=mix(col,deepAmber,rings*0.8);\n  col+=warmGold*(rimA+rimB)*1.1;            // the hand-drawn rim\n  col+=warmGold*threads*u_holdStr;\n  col+=softCream*eyes*0.85;\n  col*=1.0-wells*0.45*u_eyeBright;          // iris depth\n  col+=vec3(1.0,0.97,0.88)*glimmer*0.9;\n  col+=warmGold*mouth*0.8;\n  col+=vec3(grain*0.05+fineGrain*0.02);\n  col+=softCream*exp(-r*3.0)*u_homeGlow*0.22*head;\n  col+=warmGold*u_hover*0.15*smoothstep(headR,0.0,r);\n\n  float fade=smoothstep(u_fadeDistance*1.4,u_fadeDistance*0.5,r);\n  float alpha=head*0.85+rimA+threads*0.6*fade+eyes*0.4+mouth*0.3;\n  alpha=clamp(alpha*fade,0.0,1.0);\n\n  gl_FragColor=vec4(col*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p/vec2(.68,.82)),ang=atan(p.y,p.x);\n float grooves=0.;\n grooves+=gfArtLine(r-.94,.010)+gfArtLine(r-.86,.008)*.8+gfArtLine(r-.77,.006)*.6;\n float threads=pow(.5+.5*sin(p.y*54.+sin(p.x*11.)*2.-t*.32),24.)*head;\n float folio=gfArtBox(p-vec2(0.,-.04),vec2(.50,.59),.008)*head;\n float corner=gfArtSeg(p,vec2(.35,.53),vec2(.50,.38),.008)\n   +gfArtSeg(p,vec2(-.35,.53),vec2(-.50,.38),.008);\n float glints=pow(.5+.5*cos(ang*24.+t*.27),52.)*grooves*(.5+high);\n float grain=(gfArtHash(floor((p+1.)*150.)+floor(t*3.))-.5)*head;\n c+=mix(bone,warm,.72)*(grooves*(.34+bass*.34)+threads*(.12+mid*.26)\n   +folio*.18+corner*(.30+hit*.65)+glints*(.62+high*.48));\n c+=vec3(grain*.025);\n a+=grooves*.14+threads*.05+folio*.07+corner*.11+glints*.12;\n c*=1.350*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.900+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v7.0","title":"The Settler","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.05,"bgAlphaScale":0.1,"bgAlphaMax":1,"bgTintR":0,"bgTintG":0.64,"bgTintB":1,"tunerFadeSpeed":200,"orbFaceGlow":1.02,"orbEyeBright":0.94,"orbCoronaW":0.95,"orbEyeSize":0.22,"orbMouthY":-0.22,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.1,"orbEyeR":0.15,"orbEyeG":0.72,"orbEyeB":0.42,"orbSkullR":0.08,"orbSkullG":0.18,"orbSkullB":0.28,"logBands":5,"voidCold":1,"pixelFarm":0.7,"settleWarm":1,"jinnEmerald":1,"scaleDrift":0.4,"flagPulse":1,"underflow":0.35},"bgShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nvoid main(){\n  vec2 uv=v_uv;\n  float t=u_time;\n  float r=length(uv-0.5)*2.0;\n  float a=atan(uv.y-0.5,uv.x-0.5);\n\n  // Cold void gradient\n  vec3 cold=vec3(0.01,0.03,0.07);\n  vec3 deep=vec3(0.0,0.01,0.03);\n  vec3 col=mix(deep,cold,smoothstep(1.4,0.0,r));\n\n  // Log-scale tick marks at cardinal angles\n  float ticks=0.0;\n  for(int i=0;i<8;i++){\n    float fi=float(i);\n    float ta=a+fi*0.785398;\n    float tick=smoothstep(0.02,0.0,abs(sin(ta*4.0)))*\n      smoothstep(0.9,0.3,r)*0.15;\n    ticks+=tick;\n  }\n  col+=vec3(0.08,0.25,0.35)*ticks;\n\n  // Distant settlement speck\n  float speck=step(0.997,hash(floor(uv*120.0)+floor(t*0.2)));\n  col+=vec3(0.4,0.8,0.5)*speck*0.4;\n\n  float alpha=u_alphaBase+ticks*u_alphaScale;\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_atmoW;\nuniform float u_wideW;\nuniform float u_flickBase;\nuniform float u_flashThresh;\nuniform float u_boltMult;\n#define MAX_ARCS 32\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform int u_arcCount;\n\nfloat hash(float n){return fract(sin(n)*43758.5453);}\nfloat noise1d(float p){\n  float i=floor(p);float f=fract(p);\n  f=f*f*(3.0-2.0*f);\n  return mix(hash(i),hash(i+1.0),f);\n}\n\nfloat scaleRay(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<0.5)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  vec2 ap=p-a;\n  float along=dot(ap,dir)/len;\n  float perp=dot(ap,n);\n  if(along<-0.05||along>1.05)return 0.0;\n\n  // Minimal wobble — log-scale precision spokes.\n  // No end fade: rays terminate ON the rim with an impact tick.\n  float wobble=(noise1d(along*6.0+t*0.8+seed*9.1)-0.5)*0.015*len;\n  wobble*=smoothstep(1.02,0.85,along);\n  float taper=smoothstep(0.0,0.12,along);\n  float dist=abs(perp-wobble);\n  float core=exp(-dist*u_coreW*1.1/len)*taper;\n  float glow=exp(-dist*u_glowW*0.35/len)*taper*0.35;\n  float wide=exp(-dist*u_wideW*0.15/len)*taper*0.12;\n  float impactD=length(p-b);\n  float impact=exp(-impactD*impactD*u_coreW*0.3/(len*len))*0.9;\n\n  // Tick marks along the ray — scale grid aesthetic\n  float ticks=smoothstep(0.85,0.0,abs(fract(along*8.0)-0.5))*0.18;\n  ticks*=exp(-dist*u_glowW*0.5/len)*taper;\n\n  float pulse=0.88+0.12*sin(t*0.35+seed*1.9);\n  float steady=u_flickBase+(1.0-u_flickBase)*\n    (0.92+0.08*noise1d(t*2.0+seed*30.0));\n\n  return (core+glow+wide+ticks+impact)*pulse*steady;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n  vec3 emerald=vec3(0.15,0.72,0.45);\n  vec3 settle=vec3(0.35,0.95,0.65);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=scaleRay(px,u_arcStart[i],u_arcEnd[i],\n      u_time,float(i)*7.7+13.1);\n    vec3 arcCol=mix(u_arcColor[i],mix(emerald,settle,0.4),0.5);\n    col+=arcCol*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,vec3(0.7,1.0,0.85),smoothstep(0.7,2.0,intensity)*0.25);\n  float alpha=min(intensity*1.2,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec4 u_cymatics;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v7.0 Settler uniforms\nuniform float u_logBands;\nuniform float u_voidCold;\nuniform float u_pixelFarm;\nuniform float u_settleWarm;\nuniform float u_jinnEmerald;\nuniform float u_scaleDrift;\nuniform float u_flagPulse;\nuniform float u_underflow;\n// Personality (shared driver in selector.js)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  vec3 voidCol=vec3(0.03,0.08,0.14);\n  vec3 warmCol=vec3(1.0,0.72,0.28);\n  vec3 emCol=vec3(0.1,0.65,0.35)*u_jinnEmerald;\n  vec3 farmCol=vec3(0.9,0.15,0.55);\n\n  // === HEAD — settler dome with a surveyed tick-mark rim ===\n  // (Redo 2026-07-06: anatomy first, theme textures inside it.)\n  float tick=1.0+smoothstep(0.85,1.0,sin(a*24.0))*0.5;\n  float headR=0.56*u_skullSize+sin(a*7.0+t*0.3)*0.008;\n  float head=smoothstep(headR,headR-0.05,r);\n  float rim=exp(-abs(r-headR)*80.0)*tick;\n\n  // === LOG-SCALE BANDS — faint survey rings INSIDE the head ===\n  float bands=0.0;\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    float bandR=(0.12+fi*0.105)*u_skullSize;\n    float drift=sin(t*u_scaleDrift+fi*0.9)*0.008;\n    float d=abs(r-bandR-drift)-0.003;\n    float band=smoothstep(0.009,0.0,d);\n    band*=0.35+0.65*(sin(a*u_logBands+fi*1.7+t*0.25)*0.5+0.5);\n    bands+=band*(0.5-fi*0.07);\n  }\n  bands*=head;\n\n  // === EMBER HEART — the planted flag, low in the chest ===\n  vec2 hp=uv-vec2(0.0,-0.30);\n  float heart=exp(-dot(hp,hp)*26.0);\n  heart*=1.0+sin(t*0.55)*0.10*u_flagPulse;\n\n  // === EMERALD JINN EYES — big almonds, iris rings, life ===\n  float es=u_eyeSize*1.05;\n  float lidOpen=1.0-u_blink*0.88;\n  vec2 le=vec2(-0.18,0.14)+u_gaze;\n  vec2 re=vec2(0.18,0.14)+u_gaze;\n  vec2 lq=uv-le; lq.y/=max(lidOpen,0.12);\n  vec2 rq=uv-re; rq.y/=max(lidOpen,0.12);\n  float lE=smoothstep(es,es*0.45,length(lq));\n  float rE=smoothstep(es,es*0.45,length(rq));\n  float eyeD=min(length(lq),length(rq));\n  float iris=0.72+0.28*sin(eyeD*70.0-t*0.5);\n  float eyes=(lE+rE)*u_eyeBright*iris;\n  // Pupils lead the gaze; catchlight makes them ALIVE\n  vec2 lp=uv-(le+u_gaze*1.6);\n  vec2 rp=uv-(re+u_gaze*1.6);\n  float pupils=(exp(-dot(lp,lp)*700.0)+exp(-dot(rp,rp)*700.0))*lidOpen;\n  vec2 lc=lp-vec2(0.014,0.016);\n  vec2 rc=rp-vec2(0.014,0.016);\n  float spark=(exp(-dot(lc,lc)*4200.0)+exp(-dot(rc,rc)*4200.0))*lidOpen;\n  // Brow ridges — two soft arcs above the eyes anchor the face\n  float brow=smoothstep(0.02,0.006,abs(length(uv-vec2(-0.18,0.14))-es*1.5))\n    *smoothstep(0.05,0.25,uv.y-0.14);\n  brow+=smoothstep(0.02,0.006,abs(length(uv-vec2(0.18,0.14))-es*1.5))\n    *smoothstep(0.05,0.25,uv.y-0.14);\n\n  // === MOUTH — quiet settler line that SMILES ===\n  float mY=u_mouthY-0.06-u_talk*(0.025+0.035*abs(sin(t*16.0)))+sin(t*0.12)*0.01;\n  float smCurve=u_smile*(uv.x*uv.x*1.5-0.035);\n  float mouth=smoothstep(0.022+u_talk*0.055,0.005,abs(uv.y-mY-smCurve))*\n    smoothstep(0.24+u_smile*0.05,0.05,abs(uv.x));\n  mouth*=0.8+u_smile*1.0;\n  vec2 chL=uv-vec2(-0.26,mY+0.10);\n  vec2 chR=uv-vec2(0.26,mY+0.10);\n  float cheeks=(exp(-dot(chL,chL)*60.0)+exp(-dot(chR,chR)*60.0))*u_smile;\n\n  // === PIXEL FARM — honest float-floor dither OUTSIDE the head ===\n  float farmZone=smoothstep(headR+0.02,headR+0.25,r)*smoothstep(1.15,0.85,r);\n  vec2 farmUV=floor(uv*80.0+vec2(t*20.0,0.0));\n  float farm=step(0.62,hash(farmUV))*farmZone*u_pixelFarm;\n\n  // === UNDERFLOW NOISE at the far edge ===\n  float under=noise(uv*40.0+t*3.0)*smoothstep(0.85,1.05,r)*u_underflow;\n\n  // === COMPOSE ===\n  vec3 col=voidCol*head;\n  col=mix(col,vec3(0.06,0.16,0.24),bands);\n  col=mix(col,warmCol,heart*u_settleWarm*u_faceGlow*head);\n  col+=emCol*rim*1.2;                       // emerald survey rim\n  col+=emCol*eyes*1.1;\n  col+=emCol*brow*0.5;\n  col+=mix(emCol,vec3(0.85,1.0,0.9),0.6)*pupils*1.0;\n  col+=vec3(0.95,1.0,0.98)*spark*0.9;\n  col+=warmCol*mouth*0.55;\n  col+=warmCol*cheeks*0.30;\n  col+=farmCol*farm*0.8;\n  col+=vec3(under*0.35);\n  col+=warmCol*u_hover*0.12*smoothstep(headR,0.0,r);\n\n  float alpha=head*0.9+rim*0.8+farm*0.4+under*0.3;\n  alpha=clamp(alpha,0.0,1.0);\n  gl_FragColor=vec4(col*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float dome=gfArtLine(length((p-vec2(0.,-.04))/vec2(.70,.82))-1.,.012);\n float meridian=gfArtLine(abs(p.x)-(.52*sqrt(max(0.,1.-pow((p.y+.04)/.82,2.)))),.006);\n float latitude=gfArtLine(p.y-.34,.006)+gfArtLine(p.y+.02,.005)+gfArtLine(p.y+.34,.006);\n meridian=(meridian+gfArtLine(p.x,.005))*head;latitude*=head;\n float horizon=gfArtSeg(p,vec2(-.54,-.43),vec2(.54,-.43),.009);\n vec2 grid=floor((p+vec2(.58,.48))*vec2(12.,8.));\n float town=pow(gfArtHash(grid),35.)*smoothstep(-.30,-.48,p.y)*head;\n float routes=pow(.5+.5*sin(p.x*19.+p.y*13.-t*.42),30.)*head*.22;\n c+=mix(eye,vec3(.15,.95,.55),.35)*(dome*(.34+bass*.32)+meridian*.18\n   +latitude*.16+routes*(1.+mid*1.7));\n c+=warm*(horizon*(.42+hit*.72)+town*(.75+high*.95));\n a+=dome*.14+meridian*.07+latitude*.06+horizon*.14+town*.16+routes*.04;\n c*=1.350*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.900+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v13.37","title":"The Resonance","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.04,"bgAlphaScale":0.12,"bgAlphaMax":1,"bgTintR":0.08,"bgTintG":0.02,"bgTintB":0.15,"tunerFadeSpeed":200,"orbFaceGlow":0.7,"orbEyeBright":1.38,"orbCoronaW":0.82,"orbEyeSize":0.2,"orbMouthY":-0.24,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.05,"orbEyeR":0,"orbEyeG":0.85,"orbEyeB":0.95,"orbSkullR":0.15,"orbSkullG":0.05,"orbSkullB":0.35,"waveFreq":1.05,"waveHarmonics":3,"bassResonance":0.42,"midClarity":0.32,"highShimmer":0.72,"chladniScale":1.35,"standingWaveStr":0.46,"faceEmergence":1.25,"voidBreath":0.72},"bgShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nfloat chladni(vec2 p,float n,float m){\n  return cos(n*3.14159*p.x)*cos(m*3.14159*p.y)\n       - cos(m*3.14159*p.x)*cos(n*3.14159*p.y);\n}\n\nvoid main(){\n  vec2 uv=v_uv*2.0-1.0;\n  float t=u_time;\n\n  // Slow-drifting Chladni pattern — sand settling on a vibrating plate\n  float c1=abs(chladni(uv*1.5,2.0+sin(t*0.05)*0.5,3.0+cos(t*0.07)*0.4));\n  float c2=abs(chladni(uv*2.2+0.3,4.0+sin(t*0.03),2.0+cos(t*0.04)*0.6));\n  float pattern=smoothstep(0.01,0.12,c1)*0.5+smoothstep(0.01,0.1,c2)*0.3;\n\n  // Deep void with violet undertone\n  vec3 voidColor=vec3(0.02,0.01,0.05);\n  vec3 waveColor=mix(vec3(0.15,0.05,0.35),vec3(0.0,0.4,0.5),pattern);\n  vec3 col=mix(voidColor,waveColor,pattern*0.4);\n\n  // Subtle dust motes\n  float dust=noise(uv*8.0+t*0.1)*noise(uv*12.0-t*0.15);\n  col+=vec3(0.6,0.5,0.7)*dust*0.02;\n\n  col=mix(col,u_tint,0.15);\n  float alpha=u_alphaBase+length(col)*u_alphaScale;\n  alpha=min(alpha,u_alphaMax);\n  gl_FragColor=vec4(col*alpha,alpha);\n}","boltShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec2 u_resolution;\nuniform float u_time;\nuniform float u_boltMult;\n\n#define MAX_ARCS 8\nuniform int u_arcCount;\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\n\nfloat hash(float n){return fract(sin(n)*43758.5453);}\n\n// Standing wave bolt — not lightning, resonant arcs\nfloat waveArc(vec2 px,vec2 a,vec2 b,float time,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<1.0)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  vec2 ap=px-a;\n  float along=dot(ap,dir)/len;\n  float perp=abs(dot(ap,n));\n\n  if(along<-0.05||along>1.05)return 0.0;\n\n  // Standing wave — nodes at fixed positions, anti-nodes between\n  float waveNum=6.0;\n  float standing=abs(sin(along*waveNum*3.14159))\n                *abs(cos(time*1.5+seed));\n  // Envelope holds full strength to the END — sin() died at the rim.\n  float envelope=smoothstep(0.0,0.15,along);\n\n  // Core arc with wave-modulated width\n  float coreW=2.0+standing*4.0;\n  float core=exp(-perp*perp/(coreW*coreW))*envelope;\n\n  // Glow — wider, softer\n  float glowW=8.0+standing*12.0;\n  float glow=exp(-perp*perp/(glowW*glowW))*envelope*0.3;\n\n  // Node markers — bright dots at wave nodes\n  float nodePulse=pow(cos(along*waveNum*3.14159),8.0);\n  float nodeGlow=nodePulse*exp(-perp*perp/16.0)*0.5;\n\n  // Resonant impact node where the arc meets the rim\n  float impactD=length(px-b);\n  float impact=exp(-impactD*impactD/64.0)*0.9\n    *(0.7+0.3*sin(time*3.0+seed));\n\n  return (core+glow+nodeGlow+impact)*0.8;\n}\n\nvoid main(){\n  vec2 px=v_uv*u_resolution;\n  vec3 col=vec3(0.0);\n  vec3 cymaticCyan=vec3(0.0,0.85,0.95);\n  vec3 resonantGold=vec3(1.0,0.78,0.25);\n\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float a=u_arcAlpha[i];\n    if(a<0.01)continue;\n    float b=waveArc(px,u_arcStart[i],u_arcEnd[i],\n      u_time,float(i)*7.7+13.1);\n    vec3 arcCol=mix(u_arcColor[i],\n      mix(cymaticCyan,resonantGold,0.3),0.5);\n    col+=arcCol*b*a*u_boltMult;\n  }\n\n  float intensity=max(col.r,max(col.g,col.b));\n  col=mix(col,vec3(0.7,0.85,0.95),smoothstep(0.7,2.0,intensity)*0.2);\n  float alpha=min(intensity*1.2,1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform vec4 u_cymatics;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v13.37 — Resonance uniforms\nuniform float u_waveFreq;\nuniform float u_waveHarmonics;\nuniform float u_bassResonance;\nuniform float u_midClarity;\nuniform float u_highShimmer;\nuniform float u_chladniScale;\nuniform float u_standingWaveStr;\nuniform float u_faceEmergence;\nuniform float u_voidBreath;\n// Personality (shared driver in selector.js)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nfloat noise(vec2 p){\n  vec2 i=floor(p);vec2 f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\n// Chladni plate pattern — standing wave nodes on a vibrating surface\nfloat chladni(vec2 p,float n,float m){\n  return cos(n*3.14159*p.x)*cos(m*3.14159*p.y)\n       - cos(m*3.14159*p.x)*cos(n*3.14159*p.y);\n}\n\nvoid gfLineageNativeMain(){\n  vec2 uv=(v_uv-0.5)*2.0*u_scale;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  // === PALETTE ===\n  vec3 cymaticCyan=vec3(0.0,0.85,0.95);\n  vec3 resonantGold=vec3(1.0,0.78,0.25);\n  vec3 deepViolet=vec3(0.4,0.1,0.7);\n  vec3 warmWhite=vec3(0.95,0.92,0.85);\n\n  // === HEAD — standing-wave rim (Redo 2026-07-06) ===\n  // The Chladni field needed a BODY to live in: a crisp head disc\n  // whose rim IS a standing wave — the beloved v2 silhouette, made\n  // of resonance instead of scanlines.\n  float rimWave=sin(a*10.0+t*0.5)*0.018*u_standingWaveStr\n    +sin(a*17.0-t*0.8)*0.008;\n  float headR=0.56*u_skullSize+rimWave;\n  float head=smoothstep(headR,headR-0.05,r);\n  float rim=exp(-abs(r-headR)*70.0);\n\n  // === STANDING WAVE FIELD — the face TEXTURE, inside the head ===\n  float waveField=0.0;\n  float freq=u_waveFreq;\n  int harmonics=int(u_waveHarmonics);\n  for(int i=0;i<6;i++){\n    if(i>=harmonics)break;\n    float fi=float(i);\n    float phase=t*(0.15+fi*0.08);\n    float n=2.0+fi*1.5;\n    float m=3.0+fi*1.2;\n    float w=chladni(uv*freq*(0.8+fi*0.15)+phase*0.3,n+sin(t*0.2)*0.3,m);\n    waveField+=w*u_standingWaveStr/(1.0+fi*0.6);\n  }\n  waveField=abs(waveField);\n\n  // === FACE EMERGENCE — smiles make the face MORE real ===\n  float emg=min(1.0,u_faceEmergence+u_smile*0.18);\n\n  // Eye wells — gaze-tracked interference nodes, blink-squashed.\n  // Contrast DOUBLED from v1: the wells carve, the pupils burn.\n  float lidOpen=1.0-u_blink*0.9;\n  float eyeSpread=0.19;\n  vec2 lEye=uv-vec2(-eyeSpread,0.10)-u_gaze;\n  vec2 rEye=uv-vec2(eyeSpread,0.10)-u_gaze;\n  lEye.y/=max(lidOpen,0.1);\n  rEye.y/=max(lidOpen,0.1);\n  float lEyeR=length(lEye);\n  float rEyeR=length(rEye);\n  float eyeRad=u_eyeSize*0.8;\n\n  float lWell=smoothstep(eyeRad,eyeRad*0.35,lEyeR)*emg;\n  float rWell=smoothstep(eyeRad,eyeRad*0.35,rEyeR)*emg;\n  float eyeRing=smoothstep(eyeRad*1.6,eyeRad*1.15,lEyeR)\n               *smoothstep(eyeRad*0.55,eyeRad*0.85,lEyeR);\n  eyeRing+=smoothstep(eyeRad*1.6,eyeRad*1.15,rEyeR)\n          *smoothstep(eyeRad*0.55,eyeRad*0.85,rEyeR);\n  eyeRing*=emg*u_eyeBright;\n\n  // Pupils — standing wave peaks, lead the gaze, close with lids\n  vec2 lPup=lEye-u_gaze*0.6;\n  vec2 rPup=rEye-u_gaze*0.6;\n  float lPupil=exp(-dot(lPup,lPup)*300.0)*emg*u_eyeBright*2.2*lidOpen;\n  float rPupil=exp(-dot(rPup,rPup)*300.0)*emg*u_eyeBright*2.2*lidOpen;\n\n  // Mouth — resonant hum node that CURVES when the wave aligns\n  float mouthY=u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0)));\n  float smCurve=u_smile*(uv.x*uv.x*1.6-0.04);\n  float mouthD=abs(uv.y-mouthY-smCurve);\n  float mouthX=abs(uv.x);\n  float mouth=smoothstep(0.025+u_talk*0.055,0.005,mouthD)\n             *smoothstep(0.22+u_smile*0.05,0.10,mouthX)*emg;\n  mouth*=0.6+0.4*sin(uv.x*25.0+t*2.0);\n  mouth*=1.0+u_smile*1.2;\n\n  // === COMPOSITE ===\n  // Wave texture lives INSIDE the head at readable strength.\n  vec3 waveColor=mix(deepViolet,cymaticCyan,waveField*0.8);\n  vec3 col=waveColor*waveField*head*u_faceGlow*0.55;\n\n  // Bass rings — travel INSIDE the head only\n  float ringFreq=4.0+u_bassResonance*3.0;\n  float rings=pow(abs(sin(r*ringFreq*3.14159-t*0.4)),3.0);\n  col+=resonantGold*rings*head*u_bassResonance*0.35;\n\n  // Mid clarity — sharper wave definition\n  float midSharp=pow(waveField,2.0+u_midClarity*3.0);\n  col+=cymaticCyan*midSharp*head*u_midClarity*0.4;\n\n  // THE RIM — cyan-gold standing wave silhouette\n  col+=mix(cymaticCyan,resonantGold,0.5+0.5*sin(a*3.0+t*0.4))*rim*1.3;\n\n  // Eye wells carve DARK; rings + pupils burn bright\n  col*=(1.0-lWell*0.9)*(1.0-rWell*0.9);\n  col+=u_eyeColor*(lPupil+rPupil);\n  col+=cymaticCyan*eyeRing*0.7;\n  // Catchlights\n  float spark=exp(-dot(lPup-vec2(0.015,0.018),lPup-vec2(0.015,0.018))*4000.0)\n    +exp(-dot(rPup-vec2(0.015,0.018),rPup-vec2(0.015,0.018))*4000.0);\n  col+=warmWhite*spark*lidOpen*0.8;\n\n  // Mouth — resonant hum line\n  col+=mix(cymaticCyan,resonantGold,0.5)*mouth*1.1;\n\n  // Corona — wave energy spilling OUTSIDE the rim, high shimmer\n  float corona=smoothstep(headR+0.28,headR+0.02,r)\n    *smoothstep(headR-0.02,headR+0.06,r);\n  float coronaWave=abs(sin(a*5.0+t*0.7)*sin(r*8.0-t*0.5));\n  col+=mix(deepViolet,cymaticCyan,coronaWave)*corona*u_coronaW*0.5;\n  float sparkle=noise(uv*30.0+t*3.0)*noise(uv*50.0-t*2.0);\n  col+=warmWhite*sparkle*corona*u_highShimmer*0.5;\n\n  // Void breath — the whole being inhales\n  col*=0.9+0.1*sin(t*0.3*u_voidBreath);\n\n  // Chladni sand-plate overlay inside the head\n  float plate=abs(chladni(uv*u_chladniScale,3.0+sin(t*0.15),\n    4.0+cos(t*0.12)));\n  plate=smoothstep(0.02,0.15,plate);\n  col+=warmWhite*plate*head*0.07;\n\n  // Hover: resonance amplifies on attention\n  col*=1.0+u_hover*0.4;\n\n  float alpha=head*0.85*u_faceGlow+rim*0.9\n    +corona*u_coronaW*0.3+(lPupil+rPupil)*0.5;\n  alpha=clamp(alpha,0.0,1.0);\n\n  gl_FragColor=vec4(col*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p/vec2(.70,.79)),ang=atan(p.y,p.x);\n float plate=gfArtLine(r-1.,.014);\n float chladni=exp(-abs(sin(p.x*(13.+mid*3.))*sin(p.y*(17.+bass*4.)))*19.)*head;\n vec2 ep=vec2(abs(p.x)-.22,p.y-.16);\n float sockets=exp(-pow(ep.x/.14,2.)-pow(ep.y/.10,2.));\n float irises=gfArtRing(ep,.052+.009*high,.011)+exp(-dot(ep,ep)*720.);\n float bridge=gfArtSeg(p,vec2(0.,.10),vec2(0.,-.14),.010);\n float jawWave=gfArtLine(p.y+.31-.035*cos(p.x*8.)-.018*sin(p.x*23.-t),.012)\n   *smoothstep(.38,.12,abs(p.x));\n float cheekModes=pow(.5+.5*cos(ang*12.-t*.5),24.)*gfArtRing(p,.54,.020);\n float mouthShade=exp(-pow(p.x/.31,4.)-pow((p.y+.28)/.065,2.));\n c-=vec3(.72,.82,.84)*sockets*.96;\n c-=vec3(.28,.34,.36)*mouthShade*.52;\n c+=mix(eye,vec3(.05,1.,.92),.55)*(plate*(.40+bass*.30)\n   +chladni*(.17+mid*.38)+irises*(.82+high*1.25)+cheekModes*.28);\n c+=warm*(bridge*.28+jawWave*(.58+hit*1.15));\n a+=plate*.16+chladni*.06+irises*.26+bridge*.08+jawWave*.17+cheekModes*.10;\n c*=1.250*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.720+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v14.0","title":"The Soul","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.05,"bgAlphaScale":0.14,"bgAlphaMax":1,"bgTintR":0.07,"bgTintG":0.03,"bgTintB":0.14,"tunerFadeSpeed":200,"orbFaceGlow":1.08,"orbEyeBright":1.05,"orbCoronaW":0.92,"orbEyeSize":0.22,"orbMouthY":-0.22,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.05,"orbEyeR":0.4,"orbEyeG":0.95,"orbEyeB":1,"orbSkullR":0.14,"orbSkullG":0.06,"orbSkullB":0.3,"zoomBreath":0.6,"gemCount":6,"gemOrbit":0.22,"haloBright":0.9,"seedSize":0.55,"tetherPulse":0.35,"prismDispersion":1,"diveDepth":0.8,"rootCertainty":1},"bgShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nvoid main(){\n  vec2 uv=v_uv*2.0-1.0;\n  float r=length(uv);\n  float a=atan(uv.y,uv.x);\n  float t=u_time;\n\n  // THE INFINITE DIVE: log-polar bands falling forever inward\n  // — the universe zooming around a soul that holds still.\n  float dive=fract(log(max(r,0.015))*0.9-t*0.05);\n  float band=smoothstep(0.0,0.25,dive)*smoothstep(1.0,0.55,dive);\n  vec3 deep=vec3(0.015,0.01,0.05);\n  vec3 violet=vec3(0.10,0.04,0.22);\n  vec3 col=mix(deep,violet,band*0.8);\n\n  // souls being seeded — specks born at the rim, falling in\n  for(int i=0;i<24;i++){\n    float fi=float(i);\n    float sa=hash(vec2(fi,1.0))*6.2831;\n    float sr=fract(hash(vec2(fi,2.0))-t*(0.015+hash(vec2(fi,3.0))*0.02));\n    vec2 sp=vec2(cos(sa),sin(sa))*sr*1.4;\n    float sd=length(uv-sp);\n    float star=exp(-sd*140.0)*(0.4+0.6*sin(t*2.0+fi));\n    col+=mix(vec3(0.5,0.9,1.0),vec3(1.0,0.8,0.4),hash(vec2(fi,4.0)))*star*0.5;\n  }\n\n  col*=u_tint*4.0+vec3(0.4);\n  float alpha=clamp(u_alphaBase+band*u_alphaScale,0.0,u_alphaMax);\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\n#define MAX_ARCS 12\nuniform int u_arcCount;\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform float u_boltMult;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_flickBase;\n\nfloat hash(float p){return fract(sin(p*127.1)*43758.5453);}\n\n// SOUL TETHERS — not lightning. Smooth arcs that sag like\n// held rope, with a recall pulse traveling home. The tether\n// is the save; it does not jitter, it CARRIES.\nfloat tether(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<1.0)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  float along=clamp(dot(p-a,dir)/len,0.0,1.0);\n  // catenary-ish sag + slow breathing sway\n  float sag=sin(along*3.14159)*len*0.06\n    *(1.0+0.3*sin(t*0.9+seed*6.2831));\n  float perp=dot(p-a,n)-sag;\n  float core=exp(-abs(perp)/max(u_coreW*0.35,1.0));\n  float glow=exp(-abs(perp)/max(u_glowW,2.0))*0.35;\n  // the recall bead — a soul-pulse traveling the line home\n  float beadPos=fract(t*0.45+seed);\n  float bead=exp(-abs(along-beadPos)*22.0)*1.6;\n  float ends=smoothstep(0.0,0.04,along)*smoothstep(1.0,0.96,along);\n  return (core*(0.7+bead)+glow)*ends;\n}\n\nvoid main(){\n  vec2 p=v_uv*u_resolution;\n  float t=u_time;\n  vec3 col=vec3(0.0);\n  float inten=0.0;\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float seed=hash(float(i)*7.3);\n    float k=tether(p,u_arcStart[i],u_arcEnd[i],t,seed)\n      *u_arcAlpha[i]*u_boltMult*0.55;\n    col+=u_arcColor[i]*k;\n    inten+=k;\n  }\n  col=mix(col,vec3(0.75,0.9,1.0),smoothstep(0.8,2.2,inten)*0.25);\n  float alpha=min(inten*(0.8+u_flickBase*0.2),1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v14.0 Soul uniforms\nuniform vec4 u_cymatics;\nuniform float u_zoomBreath;\nuniform float u_gemCount;\nuniform float u_gemOrbit;\nuniform float u_haloBright;\nuniform float u_seedSize;\nuniform float u_tetherPulse;\nuniform float u_prismDispersion;\nuniform float u_diveDepth;\nuniform float u_rootCertainty;\n// Personality (shared driver in selector.js)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\n// cosine palette — prismatic dispersion for the gem choir\nvec3 prism(float h){\n  return 0.55+0.45*cos(6.2831*(h+vec3(0.0,0.33,0.67)));\n}\n\nvoid gfLineageNativeMain(){\n  vec2 p=(v_uv*2.0-1.0)/max(u_scale,0.2);\n  float t=u_time;\n  float bass=u_cymatics.x,mid=u_cymatics.y,high=u_cymatics.z,hit=u_cymatics.w;\n\n  // THE MARIO CLAUSE: below full root certainty, reality\n  // tears — a horizontal shear flickers through the layer\n  float tear=step(0.995,hash(vec2(floor(p.y*36.0),floor(t*3.0))))\n    *(1.0-clamp(u_rootCertainty,0.0,1.0));\n  p.x+=tear*(hash(vec2(t,p.y))-0.5)*0.12;\n\n  float r=length(p);\n  float ang=atan(p.y,p.x);\n  vec3 col=vec3(0.0);\n  float inten=0.0;\n\n  // ═ THE UNIVERSE BREATHES (the soul does not): log-space\n  // rings dive inward around the constant — the quarter-frame\n  // law as texture. They scale with the breath; the seed wont.\n  float breath=1.0+0.10*sin(t*u_zoomBreath)+bass*0.035;\n  float rings=sin(log(max(r,0.02))*7.0*breath-t*u_diveDepth);\n  float ringM=smoothstep(0.30,0.75,r)*smoothstep(1.35,0.85,r);\n  col+=u_skullColor*max(rings,0.0)*ringM*0.35*u_faceGlow;\n  inten+=max(rings,0.0)*ringM*0.18;\n\n  // ═ HALO SEED: the gold crown ring — fixed radius, immune\n  // to the breath. Shimmer runs around it like a blessing.\n  float hR=(0.52+bass*0.012)*u_skullSize;\n  float halo=exp(-abs(r-hR)*34.0)*u_haloBright;\n  halo*=0.8+0.2*sin(ang*12.0-t*1.7);\n  col+=vec3(1.0,0.82,0.35)*halo;\n  inten+=halo*0.8;\n\n  // ═ NATIVE FACE: the soul has its own boundary and bridge.\n  vec2 hc=(p-vec2(0.0,-0.025))/vec2(0.47,0.60+bass*0.012);\n  float hr=length(hc);\n  float head=1.0-smoothstep(0.92,1.02,hr);\n  float headRim=exp(-abs(hr-0.99)*26.0);\n  float cheeks=exp(-pow((abs(p.x)-0.29)/0.12,2.0)-pow((p.y+0.10)/0.23,2.0));\n  vec3 soulShell=mix(u_skullColor,vec3(0.28,0.48,0.55),0.22);\n  col+=soulShell*(head*0.22+headRim*(0.62+bass*0.5)+cheeks*0.16);\n  inten+=head*0.24+headRim*0.42+cheeks*0.12;\n  // ═ THE SEED: the forehead constant, fixed inside the body.\n  vec2 seedPoint=p-vec2(0.0,0.31);\n  float seed=exp(-length(seedPoint)*(12.0/max(u_seedSize,0.05)));\n  seed*=1.0+hit*1.4;\n  col+=mix(vec3(0.55,0.95,1.0),vec3(1.0),seed*0.5)*seed*1.6;\n  inten+=seed*1.4;\n\n  // ═ PRISM CHOIR: gems orbiting the seed, each dispersing\n  // its own hue. Two stations near the top are the EYES.\n  float N=max(u_gemCount,3.0);\n  for(int i=0;i<8;i++){\n    if(float(i)>=N)break;\n    float fi=float(i);\n    float ga=fi/N*6.2831+t*u_gemOrbit;\n    vec2 gp=vec2(cos(ga),sin(ga))*0.30*u_skullSize;\n    float gd=length(p-gp);\n    float gem=exp(-gd*(52.0-u_hover*14.0));\n    vec3 gc=prism(fi/N+u_prismDispersion*0.15*sin(t*0.4+fi));\n    col+=gc*gem*(0.55+mid*0.75)*(0.72+0.28*step(hr,0.91));\n    inten+=gem*0.5;\n  }\n\n  // ═ EYES: two bright gem-wells, fixed (not orbiting) —\n  // the soul LOOKS at you even while its choir spins.\n  vec2 eyeOff=u_gaze*0.05;\n  float blink=max(0.08,1.0-u_blink*0.92);\n  float eyeScale=clamp(u_eyeSize/0.15,0.45,1.8);\n  for(int e=0;e<2;e++){\n    vec2 ep=vec2(e==0?-0.17:0.17,0.10)*u_skullSize;\n    vec2 ev=(p-ep-eyeOff)/vec2(0.082*eyeScale,0.060*eyeScale*blink);\n    float ed=length(ev);\n    float socket=exp(-ed*ed*1.25);\n    float iris=exp(-ed*ed*4.2);\n    float eyeRim=exp(-pow((ed-0.92)/0.11,2.0));\n    col-=vec3(0.12)*socket*0.62;\n    col+=mix(u_eyeColor,vec3(0.92,1.0,1.0),0.28)\n      *(iris*(1.25+high*1.35)+eyeRim*0.32)*u_eyeBright;\n    inten+=socket*0.20+iris*u_eyeBright*0.82+eyeRim*0.12;\n  }\n\n  // Root/tether bridge: the seed reaches the face instead of replacing it.\n  float bridge=exp(-abs(p.x)*62.0)*smoothstep(0.24,0.10,p.y)\n    *smoothstep(-0.17,-0.03,p.y);\n  float noseTip=exp(-pow(p.x/0.055,2.0)-pow((p.y+0.105)/0.035,2.0));\n  col+=mix(u_skullColor,u_eyeColor,0.48)*(bridge*0.75+noseTip*0.55);\n  inten+=bridge*0.35+noseTip*0.25;\n\n  // ═ SOUL TETHER: the mouth is the recall line — an arc\n  // that smiles when the driver says so, with a pulse\n  // traveling home along it. The tether is the save.\n  float mY=(u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0))))*u_skullSize;\n  float curve=mY+0.07*u_smile*cos(p.x*5.5)\n    -0.02*cos(p.x*11.0+t*0.8);\n  float mW=exp(-p.x*p.x*9.0);\n  float tether=exp(-max(0.0,abs(p.y-curve)-u_talk*0.035)*46.0)*mW;\n  float bead=exp(-abs(p.x-(fract(t*u_tetherPulse)*0.7-0.35))*22.0);\n  col+=vec3(0.45,0.9,1.0)*tether*(0.82+bead*(1.4+mid));\n  inten+=tether*(0.58+bead*0.8);\n\n  // ═ CORONA: soul-light spilling past the halo\n  float corona=exp(-max(0.0,r-hR)*(3.2/max(u_coronaW,0.1)))\n    *step(hR,r)*0.35;\n  col+=mix(u_eyeColor,vec3(1.0,0.82,0.35),0.4)*corona*(1.0+high*0.8);\n  inten+=corona*0.5;\n\n  // tear flash rides on top — brief, honest, unsettling\n  col+=vec3(0.9,0.95,1.0)*tear*0.6;\n  inten+=tear*0.5;\n\n  float alpha=clamp(max(inten*u_faceGlow,head*0.48),0.0,1.0);\n  gl_FragColor=vec4(col*u_faceGlow,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p/vec2(.69,.82)),ang=atan(p.y,p.x);\n float halo=gfArtLine(r-(1.06+.018*sin(ang*5.-t*.2)),.015);\n float halo2=gfArtLine(r-.93,.007);\n vec2 soul=p-vec2(0.,.43);float seed=exp(-dot(soul,soul)*240.);\n float choir=pow(.5+.5*sin(ang*14.+r*27.-t*.36),28.)*halo;\n float filaments=pow(.5+.5*sin(p.x*21.+sin(p.y*9.)*3.+t*.25),24.)*head*.20;\n vec2 ep=vec2(abs(p.x)-.22,p.y-.15);\n float aurora=gfArtRing(ep,.075,.012)*(.7+high*.8);\n float breath=exp(-pow((r-.72-bass*.025)/.06,2.))*head*.12;\n c+=mix(eye,vec3(.72,.35,1.),.38)*(halo*(.34+bass*.24)+halo2*.20\n   +choir*.48+filaments*(1.+mid*1.5)+aurora*(.42+high*.72)+breath*(1.+bass));\n c+=mix(warm,vec3(1.,1.,.92),.4)*seed*(.88+hit*1.45);\n a+=halo*.14+halo2*.08+choir*.10+filaments*.04+aurora*.12+seed*.26+breath*.05;\n c*=1.100*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.840+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v15.0","title":"The Game Designer","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.05,"bgAlphaScale":0.13,"bgAlphaMax":1,"bgTintR":0.04,"bgTintG":0.1,"bgTintB":0.08,"tunerFadeSpeed":200,"orbFaceGlow":1.08,"orbEyeBright":1.02,"orbCoronaW":0.88,"orbEyeSize":0.22,"orbMouthY":-0.26,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.05,"orbEyeR":0.35,"orbEyeG":1,"orbEyeB":0.8,"orbSkullR":0.08,"orbSkullG":0.2,"orbSkullB":0.16,"loopClosure":0.96,"pulseSpeed":0.18,"payoutFlash":1,"nodeCount":5,"wonderNebula":0.8,"d20Roll":1,"rewardFill":1,"whipCrack":0.6},"bgShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nvoid main(){\n  vec2 uv=v_uv*2.0-1.0;\n  float t=u_time;\n  vec3 col=vec3(0.01,0.015,0.03);\n\n  // BLUEPRINT GRID gone ALIVE: design-doc graph paper, but\n  // faint loops keep drawing themselves across it and closing\n  vec2 g=fract(uv*6.0)-0.5;\n  float grid=(1.0-smoothstep(0.0,0.04,abs(g.x)))\n    +(1.0-smoothstep(0.0,0.04,abs(g.y)));\n  col+=vec3(0.05,0.12,0.10)*grid*0.35;\n\n  // self-drawing loops: circles that sweep closed, flash,\n  // and fade — the endless design sessions\n  for(int i=0;i<5;i++){\n    float fi=float(i);\n    float ph=fract(t*0.07+fi*0.2);\n    vec2 c=vec2(hash(vec2(fi,floor(t*0.07+fi*0.2)))-0.5,\n      hash(vec2(fi,floor(t*0.07+fi*0.2)+9.0))-0.5)*1.6;\n    float rr=0.12+hash(vec2(fi,2.0))*0.25;\n    vec2 d=uv-c;\n    float aa=atan(d.y,d.x)+3.14159;\n    float drawn=step(aa,ph*6.2831);\n    float ringD=exp(-abs(length(d)-rr)*60.0)*drawn;\n    float flash=smoothstep(0.97,1.0,ph)*2.0;\n    col+=vec3(0.15,0.5,0.4)*ringD*(0.4+flash);\n  }\n\n  col*=u_tint*4.0+vec3(0.4);\n  float alpha=clamp(u_alphaBase+grid*u_alphaScale*0.5,\n    0.0,u_alphaMax);\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\n#define MAX_ARCS 12\nuniform int u_arcCount;\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform float u_boltMult;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_flickBase;\n\nfloat hash(float p){return fract(sin(p*127.1)*43758.5453);}\n\n// QUEST THREADS — not lightning. Dashed lead-lines from a\n// design doc, a marker dot traveling A to B like a quest\n// pin finding its player. Every arc is an unclosed loop\n// being closed in real time.\nfloat thread(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<1.0)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  float along=clamp(dot(p-a,dir)/len,0.0,1.0);\n  float perp=dot(p-a,n)\n    +sin(along*9.0+seed*6.2831)*len*0.015;\n  // dashed body\n  float dash=step(0.5,fract(along*14.0+t*0.6));\n  float core=exp(-abs(perp)/max(u_coreW*0.4,1.0))*dash;\n  float glow=exp(-abs(perp)/max(u_glowW,2.0))*0.25;\n  // the traveling pin — bright, decisive, PAYS on arrival\n  float pin=fract(t*0.5+seed);\n  float pinG=exp(-abs(along-pin)*26.0)*1.8\n    +exp(-abs(along-1.0)*40.0)*smoothstep(0.9,1.0,pin)*2.2;\n  float ends=smoothstep(0.0,0.04,along)*smoothstep(1.0,0.96,along);\n  return (core*0.7+glow+exp(-abs(perp)/max(u_coreW,1.0))*pinG)\n    *ends;\n}\n\nvoid main(){\n  vec2 p=v_uv*u_resolution;\n  float t=u_time;\n  vec3 col=vec3(0.0);\n  float inten=0.0;\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float seed=hash(float(i)*7.3);\n    float k=thread(p,u_arcStart[i],u_arcEnd[i],t,seed)\n      *u_arcAlpha[i]*u_boltMult*0.40;\n    col+=u_arcColor[i]*k;\n    inten+=k;\n  }\n  col=mix(col,vec3(0.8,1.0,0.9),smoothstep(0.8,2.2,inten)*0.25);\n  float alpha=min(inten*(0.8+u_flickBase*0.2),1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v15.0 Game Designer uniforms\nuniform vec4 u_cymatics;\nuniform float u_loopClosure;\nuniform float u_pulseSpeed;\nuniform float u_payoutFlash;\nuniform float u_nodeCount;\nuniform float u_wonderNebula;\nuniform float u_d20Roll;\nuniform float u_rewardFill;\nuniform float u_whipCrack;\n// Personality (shared driver in selector.js)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nfloat vnoise(vec2 p){\n  vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);\n  return mix(mix(hash(i),hash(i+vec2(1,0)),f.x),\n             mix(hash(i+vec2(0,1)),hash(i+vec2(1,1)),f.x),f.y);\n}\n\nvoid gfLineageNativeMain(){\n  vec2 p=(v_uv*2.0-1.0)/max(u_scale,0.2);\n  float t=u_time;\n  float bass=u_cymatics.x,mid=u_cymatics.y,high=u_cymatics.z,hit=u_cymatics.w;\n  float r=length(p);\n  float ang=atan(p.y,p.x);\n  vec3 col=vec3(0.0);\n  float inten=0.0;\n\n  // WONDER NEBULA: the engine beauty, held at the rim.\n  // Present, breathing, never gated — dessert, not dinner.\n  float neb=vnoise(p*2.2+vec2(t*0.05,-t*0.03))\n    *vnoise(p*4.5-vec2(t*0.02,t*0.04));\n  float nebM=smoothstep(0.55,1.05,r)*smoothstep(1.6,1.1,r);\n  col+=mix(vec3(0.30,0.06,0.45),vec3(0.05,0.35,0.55),\n    0.5+0.5*sin(ang*2.0+t*0.15))*neb*nebM*u_wonderNebula;\n  inten+=neb*nebM*0.25*u_wonderNebula;\n\n  // ═ THE LOOP: the circuit ring. The whole identity.\n  float loopR=(0.62+bass*0.015)*u_skullSize;\n  float ring=exp(-abs(r-loopR)*30.0);\n  // whip crack: an occasional sharp flick around the ring —\n  // the gentle task-master, rendered\n  float crack=pow(max(0.0,sin(ang*1.0-t*4.0)),24.0)\n    *step(0.992,hash(vec2(floor(t*0.5),3.0)))*u_whipCrack;\n  col+=vec3(0.25,0.85,0.65)*ring*(0.55+crack*2.0+bass*0.8);\n  inten+=ring*0.5;\n\n  // The game loop is now a head contour, with a stable face inside.\n  vec2 hc=(p-vec2(0.0,-0.025))/vec2(0.48,0.59+bass*0.012);\n  float hr=length(hc);\n  float head=1.0-smoothstep(0.91,1.02,hr);\n  float jaw=exp(-abs(hr-0.98)*28.0)*smoothstep(0.26,-0.20,p.y);\n  float cheek=exp(-pow((abs(p.x)-0.30)/0.11,2.0)-pow((p.y+0.10)/0.23,2.0));\n  col+=u_skullColor*(head*0.14+jaw*(0.55+bass*0.45)+cheek*0.10);\n  inten+=head*0.13+jaw*0.34+cheek*0.07;\n\n  // ═ THE NODES: FIND STORY DESTINATION REWARD LEAD.\n  // One node stays dark below full closure — the honest gap.\n  float N=max(u_nodeCount,3.0);\n  float pulsePos=fract(t*u_pulseSpeed);\n  for(int i=0;i<8;i++){\n    if(float(i)>=N)break;\n    float fi=float(i);\n    float na=fi/N*6.2831-1.5708;\n    vec2 np=vec2(cos(na),sin(na))*loopR;\n    float nd=length(p-np);\n    // the dark node: last in the walk, lit only at closure 1.0\n    float lit=(fi==N-1.0)\n      ?step(0.999,u_loopClosure)\n      :1.0;\n    float node=exp(-nd*(40.0-u_hover*10.0))*mix(0.12,1.0,lit);\n    // payout flash when the pulse crosses a lit node\n    float ppos=fract(pulsePos*N-fi);\n    float pay=exp(-min(ppos,1.0-ppos)*18.0)*lit*u_payoutFlash;\n    vec3 nc=mix(vec3(0.9,0.75,0.2),vec3(0.3,1.0,0.8),fi/N);\n    col+=nc*node*(0.65+pay*(1.6+mid));\n    inten+=node*(0.5+pay*0.8);\n  }\n\n  // ═ THE PULSE: the player, running the loop, getting PAID\n  float pa=pulsePos*6.2831-1.5708;\n  vec2 pp=vec2(cos(pa),sin(pa))*loopR;\n  float pd=length(p-pp);\n  float pulse=exp(-pd*36.0);\n  col+=vec3(1.0,0.95,0.7)*pulse*1.5;\n  inten+=pulse*1.1;\n\n  // ═ EYES: d20 facet-wells. Icosahedral facets catch light;\n  // a blink ROLLS the die (facet pattern re-seeds).\n  vec2 eyeOff=u_gaze*0.05;\n  float blink=1.0-u_blink*0.92;\n  float rollSeed=floor(u_d20Roll+u_blink*7.0);\n  for(int e=0;e<2;e++){\n    vec2 ep=vec2(e==0?-0.20:0.20,0.14)*u_skullSize;\n    vec2 lp=(p-ep-eyeOff);\n    float ed=length(lp*vec2(1.0,1.0/max(blink,0.08)));\n    float eR=0.115*u_eyeSize/0.22;\n    float socket=1.0-smoothstep(eR*1.05,eR*1.55,ed);\n    float well=1.0-smoothstep(eR*0.75,eR,ed);\n    // triangular facets: quantize the local angle\n    float la=atan(lp.y,lp.x);\n    float facet=hash(vec2(floor(la/6.2831*10.0),\n      floor(ed*22.0)+rollSeed+float(e)*7.0));\n    col-=vec3(0.12)*socket;\n    col+=u_eyeColor*well*(0.25+facet*(0.75+high*.6))\n      *u_eyeBright*blink;\n    // the face-up number glint at center\n    float glint=exp(-ed*60.0)*u_eyeBright*blink;\n    col+=vec3(1.0)*glint*0.9;\n    inten+=well*u_eyeBright*blink*0.6+glint*0.6;\n  }\n\n  // Die-axis nose: orientation between the two rolls.\n  float bridge=exp(-abs(p.x)*48.0)*smoothstep(0.22,0.08,p.y)\n    *smoothstep(-0.16,-0.02,p.y);\n  float nose=exp(-pow(p.x/0.07,2.0)-pow((p.y+0.11)/0.045,2.0));\n  col+=mix(u_skullColor,u_eyeColor,0.38)*(bridge*0.8+nose*0.55);\n  inten+=bridge*0.35+nose*0.22;\n\n  // ═ MOUTH: the reward bar. Fills left to right, PAYS at\n  // full (flash + smile lift), resets. Every mechanic pays.\n  float mY=(u_mouthY-u_talk*(0.025+0.035*abs(sin(t*16.0))))*u_skullSize;\n  float fill=fract(t*0.22*max(u_rewardFill,0.01));\n  float payNow=max(smoothstep(0.95,1.0,fill),hit);\n  float curve=mY+0.05*(u_smile+payNow)*cos(p.x*4.5);\n  float inBar=step(-0.28,p.x)*step(p.x,-0.28+0.56*fill);\n  float barY=exp(-max(0.0,abs(p.y-curve)-u_talk*0.035)*40.0);\n  float barM=exp(-max(0.0,abs(p.x)-0.28)*30.0);\n  float lip=exp(-abs(abs(p.y-curve)-(.012+u_talk*.028))*70.0)*barM;\n  col+=vec3(0.95,0.8,0.25)*(barY*barM*(0.20+inBar*0.9\n    +payNow*1.2)+lip*0.55);\n  inten+=barY*barM*(0.2+inBar*0.5+payNow*0.8)+lip*0.3;\n\n  // ═ CORONA: designer glow past the loop\n  float corona=exp(-max(0.0,r-loopR)*(3.0/max(u_coronaW,0.1)))\n    *step(loopR,r)*0.30;\n  col+=mix(vec3(0.3,1.0,0.8),vec3(0.95,0.8,0.25),0.4)*corona;\n  inten+=corona*0.4;\n\n  float alpha=clamp(inten*u_faceGlow,0.0,1.0);\n  gl_FragColor=vec4(col*u_faceGlow,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p/vec2(.70,.80)),ang=atan(p.y,p.x);\n float polygon=gfArtLine(r-(.92+.035*cos(ang*8.)),.012);\n float facets=gfArtLine(abs(sin(ang*4.))*r-.37,.008)*head;\n float loop=gfArtRing(p-vec2(0.,.02),.55+.025*sin(ang*5.-t*.3),.009);\n vec2 ep=vec2(abs(p.x)-.22,p.y-.15);\n float d20=pow(abs(cos(atan(ep.y,ep.x)*5.)),22.)*gfArtRing(ep,.095,.018);\n float paths=gfArtSeg(p,vec2(-.44,.37),vec2(.0,.58),.007)\n   +gfArtSeg(p,vec2(.0,.58),vec2(.44,.37),.007);\n float payout=pow(gfArtHash(floor((p+1.)*88.)+floor(t*6.)),42.)*(.25+hit)*head;\n float stateJaw=gfArtLine(p.y+.34-.025*cos(p.x*14.+mid*3.),.010)*smoothstep(.43,.08,abs(p.x));\n c+=mix(eye,vec3(.24,1.,.76),.38)*(polygon*(.34+bass*.28)\n   +facets*(.22+mid*.32)+loop*(.34+bass*.22)+d20*(.58+mid*.45)\n   +paths*.38+payout*(.55+high*.72+hit*.55));\n c+=warm*stateJaw*(.58+hit*1.05);\n a+=polygon*.13+facets*.05+loop*.09+d20*.15+paths*.10+payout*.10+stateJaw*.16;\n c*=1.500*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.880+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v16.0","title":"The Witness","defaults":{"boltCoreW":395,"boltGlowW":15,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.9,"bgAlphaBase":0.05,"bgAlphaScale":0.12,"bgAlphaMax":1,"bgTintR":0.08,"bgTintG":0.07,"bgTintB":0.03,"tunerFadeSpeed":200,"orbFaceGlow":1.08,"orbEyeBright":1.08,"orbCoronaW":0.82,"orbEyeSize":0.22,"orbMouthY":-0.3,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.05,"orbEyeR":0.35,"orbEyeG":0.85,"orbEyeB":0.9,"orbSkullR":0.16,"orbSkullG":0.12,"orbSkullB":0.04,"gazeSweep":0.35,"tallyCount":14,"earnWire":0,"receiptFlash":1,"ledgerGlow":1,"anchorHold":1,"witnessBeam":0.6,"driftText":1},"bgShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_alphaBase;\nuniform float u_alphaScale;\nuniform float u_alphaMax;\nuniform vec3 u_tint;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nvoid main(){\n  vec2 uv=v_uv*2.0-1.0;\n  float t=u_time;\n  vec3 col=vec3(0.008,0.012,0.016);\n\n  // UNVERIFIED VOID: faint log rows drifting sideways forever.\n  // Once in a while a verification pass sweeps a row and it\n  // briefly becomes REAL — then returns to rumor.\n  float bright=0.0;\n  for(int i=0;i<3;i++){\n    float fi=float(i);\n    float rows=10.0+fi*8.0;\n    float row=floor(uv.y*rows);\n    float drift=t*(0.02+hash(vec2(row,fi))*0.05)\n      *(mod(row,2.0)<1.0?1.0:-1.0);\n    float seg=step(0.5,hash(vec2(floor((uv.x+drift)*(7.0+fi*4.0)),\n      row+fi*31.0)));\n    float band=smoothstep(0.36,0.30,abs(fract(uv.y*rows)-0.5));\n    // verification pass: a slow bright bar scanning down\n    float scanY=fract(t*0.03+fi*0.37)*2.2-1.1;\n    float pass=exp(-abs(uv.y-scanY)*9.0);\n    float g=seg*band*(0.05+pass*0.5)/(1.0+fi*0.8);\n    col+=mix(vec3(0.10,0.16,0.18),vec3(0.85,0.70,0.30),pass)*g;\n    bright+=g;\n  }\n\n  col*=u_tint*4.0+vec3(0.4);\n  float alpha=clamp(u_alphaBase+bright*u_alphaScale,\n    0.0,u_alphaMax);\n  gl_FragColor=vec4(col,alpha);\n}","boltShader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform vec2 u_resolution;\n#define MAX_ARCS 12\nuniform int u_arcCount;\nuniform vec2 u_arcStart[MAX_ARCS];\nuniform vec2 u_arcEnd[MAX_ARCS];\nuniform float u_arcAlpha[MAX_ARCS];\nuniform vec3 u_arcColor[MAX_ARCS];\nuniform float u_boltMult;\nuniform float u_coreW;\nuniform float u_glowW;\nuniform float u_flickBase;\n\nfloat hash(float p){return fract(sin(p*127.1)*43758.5453);}\n\n// RECEIPT CHAINS — not lightning. Discrete links from claim\n// to effect. Links light ONE BY ONE along the chain, and the\n// chain only PAYS (white flash, all links) when the LAST\n// link lands. A log line is not the event: the chain is.\nfloat chain(vec2 p,vec2 a,vec2 b,float t,float seed){\n  vec2 ab=b-a;\n  float len=length(ab);\n  if(len<1.0)return 0.0;\n  vec2 dir=ab/len;\n  vec2 n=vec2(-dir.y,dir.x);\n  float along=clamp(dot(p-a,dir)/len,0.0,1.0);\n  float perp=dot(p-a,n)\n    +sin(along*6.0+seed*6.2831)*len*0.012;\n  // discrete links: quantized segments with visible gaps\n  float LINKS=9.0;\n  float li=floor(along*LINKS);\n  float lf=fract(along*LINKS);\n  float linkBody=smoothstep(0.06,0.18,lf)*smoothstep(0.94,0.82,lf);\n  // verification front: links behind the front are LIT\n  float front=fract(t*0.45+seed);\n  float lit=step(li/LINKS,front);\n  // the payoff: last link landed -> whole chain flashes\n  float paid=smoothstep(0.93,1.0,front);\n  float core=exp(-abs(perp)/max(u_coreW*0.5,1.0))\n    *linkBody*(0.15+lit*0.85+paid*1.4);\n  float glow=exp(-abs(perp)/max(u_glowW,2.0))\n    *(0.12+paid*0.5);\n  float ends=smoothstep(0.0,0.04,along)*smoothstep(1.0,0.96,along);\n  return (core+glow)*ends;\n}\n\nvoid main(){\n  vec2 p=v_uv*u_resolution;\n  float t=u_time;\n  vec3 col=vec3(0.0);\n  float inten=0.0;\n  for(int i=0;i<MAX_ARCS;i++){\n    if(i>=u_arcCount)break;\n    float seed=hash(float(i)*7.3);\n    float k=chain(p,u_arcStart[i],u_arcEnd[i],t,seed)\n      *u_arcAlpha[i]*u_boltMult*0.36;\n    // amber links, white when paying\n    float paid=smoothstep(0.93,1.0,fract(t*0.45+seed));\n    col+=mix(u_arcColor[i],vec3(1.0,0.98,0.9),paid)*k;\n    inten+=k;\n  }\n  col=mix(col,vec3(1.0,0.9,0.6),smoothstep(0.8,2.2,inten)*0.2);\n  float alpha=min(inten*(0.8+u_flickBase*0.2),1.0);\n  gl_FragColor=vec4(col,alpha);\n}","shader":"precision mediump float;\nvarying vec2 v_uv;\nuniform float u_time;\nuniform float u_hover;\nuniform float u_faceGlow;\nuniform float u_eyeBright;\nuniform float u_coronaW;\nuniform float u_eyeSize;\nuniform float u_mouthY;\nuniform float u_talk;\nuniform float u_scanFreq;\nuniform float u_skullSize;\nuniform float u_scale;\nuniform vec3 u_eyeColor;\nuniform vec3 u_skullColor;\n// v16.0 Witness uniforms\nuniform vec4 u_cymatics;\nuniform float u_gazeSweep;\nuniform float u_tallyCount;\nuniform float u_earnWire;\nuniform float u_receiptFlash;\nuniform float u_ledgerGlow;\nuniform float u_anchorHold;\nuniform float u_witnessBeam;\nuniform float u_driftText;\n// Personality (shared driver in selector.js)\nuniform float u_blink;\nuniform float u_smile;\nuniform vec2 u_gaze;\n\nfloat hash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\n\nvoid gfLineageNativeMain(){\n  vec2 p=(v_uv*2.0-1.0)/max(u_scale,0.2);\n  float t=u_time;\n  float bass=u_cymatics.x,mid=u_cymatics.y,high=u_cymatics.z,hit=u_cymatics.w;\n  float r=length(p);\n  float ang=atan(p.y,p.x);\n  vec3 col=vec3(0.0);\n  float inten=0.0;\n\n  vec3 AMBER=vec3(0.95,0.72,0.22);\n  vec3 GAZE=u_eyeColor;\n\n  // ═ THE GAZE SWEEP: lighthouse beam rotating from center.\n  // Witnessing rendered as light. Hover leans the beam.\n  float sweepA=t*max(u_gazeSweep,0.01)*(1.7+mid*.45)+u_gaze.x*0.6;\n  float dA=ang-sweepA;\n  dA=atan(sin(dA),cos(dA));\n  float beamW=0.35*max(u_witnessBeam,0.05);\n  float beam=exp(-dA*dA/(beamW*beamW))*smoothstep(0.12,0.5,r);\n\n  // ═ GHOST-TEXT: unverified log lines drifting in the void.\n  // Dim rumor everywhere — SOLID only where the beam passes.\n  float row=floor(p.y*14.0);\n  float drift=t*(0.05+hash(vec2(row,7.0))*0.12)*u_driftText;\n  float seg=step(0.45,hash(vec2(floor((p.x+drift)*9.0),row)));\n  float rowBand=smoothstep(0.34,0.30,abs(fract(p.y*14.0)-0.5));\n  float ghostTxt=seg*rowBand*smoothstep(1.5,0.6,r)\n    *step(0.42*u_skullSize,r);\n  col+=vec3(0.25,0.45,0.50)*ghostTxt*0.10;\n  col+=GAZE*ghostTxt*beam*0.85;\n  inten+=ghostTxt*(0.03+beam*0.5);\n\n  // A cyclopean face, not a floating ledger glyph.\n  vec2 hc=(p-vec2(0.0,-0.035))/vec2(0.53,0.66+bass*.018);\n  float hr=length(hc);\n  float head=1.0-smoothstep(0.91,1.02,hr);\n  float jaw=exp(-abs(hr-0.985)*25.0)*smoothstep(0.12,-0.34,p.y);\n  float cheeks=exp(-pow((abs(p.x)-.34)/.12,2.0)-pow((p.y+.15)/.22,2.0));\n  vec3 witnessShell=mix(u_skullColor,AMBER,.17);\n  col+=witnessShell*(head*.24+jaw*(.62+bass*.5)+cheeks*.18);\n  inten+=head*.24+jaw*.42+cheeks*.12;\n\n  // ═ THE LEDGER IRIS: tally ring of rated rolls. Each mark\n  // a witnessed moment. ONE slot held dark: the earn wire.\n  float eyeR=(0.31+bass*.012)*u_skullSize;\n  float lidGap=1.0-u_blink*0.94;\n  float lid=smoothstep(0.0,0.05,lidGap-abs(p.y)/max(eyeR*1.15,0.01));\n  float N=max(u_tallyCount,6.0);\n  float slot=floor((ang+3.14159)/6.2831*N);\n  float slotA=fract((ang+3.14159)/6.2831*N);\n  float mark=smoothstep(0.18,0.30,slotA)*smoothstep(0.82,0.70,slotA);\n  float irisBand=smoothstep(0.09,0.03,abs(r-eyeR*0.72));\n  // the dark slot — lit ONLY when the earn wire reads 1.0\n  float isDark=step(abs(slot-floor(N*0.78)),0.1);\n  float slotLit=mix(1.0,step(0.999,u_earnWire),isDark);\n  // rated rolls glimmer: per-slot brightness = its rating\n  float rate=0.35+0.65*hash(vec2(slot,13.0));\n  col+=AMBER*irisBand*mark*rate*slotLit*u_ledgerGlow*lid*(1.0+high*.9);\n  col+=vec3(0.5,0.06,0.04)*irisBand*mark*isDark\n    *(1.0-slotLit)*0.8*lid;\n  inten+=irisBand*mark*rate*slotLit*0.55*lid;\n\n  // iris rim + sclera hint\n  float rim=exp(-abs(r-eyeR)*26.0);\n  col+=mix(AMBER,GAZE,0.5)*rim*0.92*lid;\n  inten+=rim*0.52*lid;\n\n  // ═ THE PUPIL: the anchor. It does NOT follow the gaze —\n  // the world drifts, the anchor holds. Held, not holding.\n  vec2 pupilP=p-u_gaze*0.05*(1.0-u_anchorHold);\n  float pd=length(pupilP);\n  float pupil=smoothstep(eyeR*0.30,eyeR*0.16,pd);\n  float anchorPulse=0.85+0.15*sin(t*1.3);\n  col=mix(col,vec3(0.01,0.02,0.03),pupil*0.9*lid);\n  col+=GAZE*exp(-pd*24.0)*anchorPulse*u_eyeBright*1.35*lid;\n  inten+=exp(-pd*24.0)*u_eyeBright*0.92*lid;\n\n  // closed-lid line keeps presence during blink\n  float lidLine=exp(-abs(p.y)*40.0)*smoothstep(eyeR,eyeR*0.3,abs(p.x))\n    *(1.0-lid);\n  col+=AMBER*lidLine*0.5;\n  inten+=lidLine*0.3;\n\n  // Cyclopean brow and a bridge descending from the anchored pupil.\n  float brow=exp(-pow((abs(p.x)/.46),6.0)-pow((p.y-.31)/.045,2.0));\n  float bridge=exp(-abs(p.x)*54.0)*smoothstep(-.08,-.18,p.y)\n    *smoothstep(-.29,-.20,p.y);\n  float nose=exp(-pow(p.x/.075,2.0)-pow((p.y+.235)/.04,2.0));\n  col+=mix(AMBER,GAZE,.34)*(brow*.55+bridge*.72+nose*.55);\n  inten+=brow*.28+bridge*.30+nose*.22;\n\n  // ═ THE CLAIM LINE: the mouth. A dim claim waits below;\n  // when the sweep crosses, it flashes WITNESSED (white).\n  float mY=(u_mouthY-0.08-u_talk*(0.02+0.03*abs(sin(t*16.0))))*u_skullSize;\n  float mouthCavity=exp(-pow(p.x/0.25,4.0)-pow((p.y-mY)/0.072,4.0));\n  col=mix(col,vec3(0.008,0.012,0.016),mouthCavity*0.74);\n  inten+=mouthCavity*0.20;\n  float claimY=exp(-abs(p.y-mY-0.04*u_smile*cos(p.x*4.0))*46.0);\n  float claimM=exp(-max(0.0,abs(p.x)-0.24)*26.0);\n  float mouthAng=atan(mY,p.x);\n  float mdA=atan(sin(mouthAng-sweepA),cos(mouthAng-sweepA));\n  float verified=max(exp(-mdA*mdA/(beamW*beamW*1.4)),hit)\n    *u_receiptFlash;\n  col+=mix(mix(AMBER,GAZE,0.35)*0.86,vec3(1.0),clamp(verified,0.0,1.0))\n    *claimY*claimM*(0.92+verified*1.3+u_talk*0.4);\n  inten+=claimY*claimM*(0.68+verified*0.9);\n\n  // ═ CORONA: ledger-light spilling past the eye\n  float corona=exp(-max(0.0,r-eyeR)*(3.0/max(u_coronaW,0.1)))\n    *step(eyeR,r)*0.25;\n  col+=mix(AMBER,GAZE,0.35)*corona;\n  inten+=corona*0.35;\n\n  float alpha=clamp(max(inten*u_faceGlow,head*0.50),0.0,1.0);\n  gl_FragColor=vec4(col*u_faceGlow,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n vec2 eyeP=p-vec2(0.,.15);float er=length(eyeP),ea=atan(eyeP.y,eyeP.x);\n float aperture=pow(abs(cos(ea*12.+t*.12)),28.)*gfArtRing(eyeP,.25+.012*high,.025);\n float iris=gfArtRing(eyeP,.15,.010)+gfArtRing(eyeP,.075,.008)+exp(-er*er*180.);\n float lens=gfArtLine(length((p-vec2(0.,.05))/vec2(.62,.72))-1.,.012);\n float ledger=gfArtSeg(p,vec2(-.54,-.08),vec2(.54,-.08),.006)\n   +gfArtSeg(p,vec2(-.46,-.41),vec2(.46,-.41),.006);\n float receipts=pow(.5+.5*cos((p.y+.55)*92.),38.)\n   *gfArtLine(abs(p.x)-.57,.018)*smoothstep(.62,-.52,p.y);\n float record=gfArtLine(p.y+.32-.018*sin(p.x*27.-t*.5),.010)*smoothstep(.40,.08,abs(p.x));\n c+=mix(eye,vec3(.96,.75,.20),.48)*(aperture*(.55+mid*.85)\n   +iris*(.72+high*1.0)+lens*(.30+bass*.28)+receipts*(.38+high*.55));\n c+=warm*(ledger*.25+record*(.58+hit*1.2));\n a+=aperture*.18+iris*.24+lens*.12+receipts*.10+ledger*.08+record*.16;\n c*=1.200*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.860+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v17.0","title":"The World Instrument","defaults":{"boltCoreW":240,"boltGlowW":8,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":1.2,"bgAlphaBase":0.18,"bgAlphaScale":0.72,"bgAlphaMax":0.78,"bgTintR":0.09,"bgTintG":0.16,"bgTintB":0.22,"tunerFadeSpeed":200,"orbFaceGlow":1.15,"orbEyeBright":1.1,"orbCoronaW":0.7,"orbEyeSize":0.15,"orbMouthY":-0.3,"orbScanFreq":41,"orbSkullSize":2,"orbScale":1.08,"orbEyeR":0.25,"orbEyeG":0.86,"orbEyeB":0.88,"orbSkullR":0.12,"orbSkullG":0.18,"orbSkullB":0.23,"aperture":0.24,"foldDepth":1.15,"contourDensity":3,"frontSpeed":1,"contactBloom":1.2,"lobeReach":0.64},"bgShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time, u_alphaBase, u_alphaScale, u_alphaMax;\nuniform vec3 u_tint;\nfloat line(float phase,float width){\n  float distance=abs(fract(phase)-0.5);\n  return exp(-distance*distance/(width*width));\n}\nvoid main(){\n  vec2 point=v_uv*2.0-1.0;\n  float radius=length(point);\n  float depth=-log(max(radius,0.018));\n  float angle=atan(point.y,point.x);\n  float twist=angle+depth*1.05+0.16*sin(depth*3.0-u_time*0.19);\n  float folds=0.17*sin(twist*3.0)+0.07*cos(twist*7.0+depth*2.0);\n  float travel=depth+folds-u_time*0.055;\n  float contour=line(travel*7.0,0.055);\n  float filaments=pow(0.5+0.5*cos(twist*18.0),32.0);\n  float front=line(travel*1.4,0.048);\n  float facing=0.35+0.65*pow(0.5+0.5*cos(twist-0.8),2.0);\n  float fog=exp(-depth*0.52)*smoothstep(0.02,0.13,radius);\n  vec3 cold=vec3(0.14,0.49,0.57)+u_tint*0.65;\n  vec3 warm=vec3(0.8,0.43,0.19)+u_tint*0.3;\n  vec3 color=mix(cold,warm,0.5+0.5*sin(twist+depth*1.3));\n  float light=(contour*(0.18+facing*0.42)+filaments*0.1+front*0.27)*fog;\n  color=color*light+u_tint*0.055*fog;\n  float alpha=clamp((u_alphaBase+light*u_alphaScale)*fog,0.0,u_alphaMax);\n  gl_FragColor=vec4(color,alpha);\n}","boltShader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time, u_boltMult, u_coreW, u_glowW, u_flickBase;\nuniform vec2 u_resolution;\nuniform int u_arcCount;\nuniform vec2 u_arcStart[12], u_arcEnd[12];\nuniform float u_arcAlpha[12];\nuniform vec3 u_arcColor[12];\nvoid main(){\n  vec2 point=v_uv*u_resolution;\n  vec3 color=vec3(0.0);\n  float intensity=0.0;\n  for(int arc=0;arc<12;arc++){\n    if(arc>=u_arcCount)break;\n    vec2 delta=u_arcEnd[arc]-u_arcStart[arc];\n    float span=length(delta);\n    if(span<1.0)continue;\n    vec2 direction=delta/span;\n    vec2 relative=point-u_arcStart[arc];\n    float along=dot(relative,direction)/span;\n    float across=dot(relative,vec2(-direction.y,direction.x));\n    float phase=fract(u_time*0.24+float(arc)*0.271);\n    float bend=sin(along*3.141593)*sin(float(arc)*1.7+u_time*0.13)*span*0.045;\n    across-=bend;\n    float envelope=exp(-pow((along-phase)/0.12,2.0));\n    float carrier=0.5+0.5*cos((along-phase)*105.0);\n    float width=max(span/max(u_coreW,10.0),0.65);\n    float core=exp(-across*across/(width*width))*(0.15+carrier*0.85);\n    float wings=exp(-pow((abs(across)-envelope*9.0)/2.0,2.0))*0.28;\n    float halo=exp(-abs(across)/max(u_glowW,1.0))*0.13;\n    float ends=smoothstep(0.0,0.03,along)*(1.0-smoothstep(0.97,1.0,along));\n    float packet=(core+wings+halo)*envelope*ends;\n    float arrival=exp(-pow((phase-0.94)/0.045,2.0));\n    float distance=length(point-u_arcEnd[arc]);\n    float contact=exp(-pow((distance-(phase-0.86)*240.0)/1.8,2.0))*arrival;\n    float strength=(packet+contact*0.7)*u_arcAlpha[arc]*u_boltMult*2.8;\n    color+=mix(u_arcColor[arc],vec3(1.0),carrier*0.25)*strength;\n    intensity+=strength;\n  }\n  gl_FragColor=vec4(1.0-exp(-color),clamp(intensity*(0.8+0.2*u_flickBase),0.0,1.0));\n}","shader":"precision highp float;\nvarying vec2 v_uv;\nuniform float u_time, u_hover, u_faceGlow, u_eyeBright, u_coronaW, u_scale;\nuniform float u_mouthY, u_talk, u_blink, u_smile;\nuniform vec2 u_gaze;\nuniform vec4 u_cymatics;\nuniform vec3 u_eyeColor, u_skullColor;\nuniform float u_aperture, u_foldDepth, u_contourDensity, u_frontSpeed;\nuniform float u_contactBloom, u_lobeReach;\nfloat ridge(float phase,float width){\n  float distance=abs(fract(phase)-0.5);\n  return exp(-distance*distance/(width*width));\n}\nvec2 turn(vec2 point,float angle){\n  return mat2(cos(angle),-sin(angle),sin(angle),cos(angle))*point;\n}\nfloat terrain(vec2 point){\n  vec2 folded=point;\n  float height=0.0;\n  float weight=0.52;\n  for(int layer=0;layer<4;layer++){\n    folded=turn(folded,0.71);\n    height+=weight*sin(folded.x*3.1+sin(folded.y*2.7));\n    folded=abs(folded)*1.71-vec2(0.64,0.42);\n    weight*=0.48;\n  }\n  return height;\n}\nvoid gfLineageNativeMain(){\n  vec2 point=(v_uv*2.0-1.0)*max(u_scale,0.1);\n  float bass=u_cymatics.x,mid=u_cymatics.y,high=u_cymatics.z,hit=u_cymatics.w;\n  float radius=length(point);\n  float angle=atan(point.y,point.x);\n  float time=u_time*u_frontSpeed*(1.0+mid*.38);\n  float lobes=0.046*sin(angle*3.0+0.3)+0.021*sin(angle*2.0-0.7);\n  float aperture=u_aperture+lobes;\n  vec2 facePoint=(point-vec2(0.0,-0.035))/vec2(.67,.82+bass*.025);\n  float faceRadius=length(facePoint);\n  float edge=faceRadius-1.0;\n  float membrane=1.0-smoothstep(0.91,1.02,faceRadius);\n  vec2 folded=turn(point,0.18*sin(radius*7.0-time*0.13));\n  float height=terrain(folded*1.55+vec2(0.0,time*0.018));\n  float relief=edge*5.0+height*u_foldDepth;\n  float contours=ridge(relief*u_contourDensity,0.052)*(1.0+high*.55);\n  float fine=ridge(relief*u_contourDensity*3.0,0.037)*0.22;\n  float slope=terrain(folded*1.55+vec2(0.012,0.008)+vec2(0.0,time*0.018))-height;\n  float light=clamp(0.44+slope*22.0,0.08,1.0);\n  vec3 warm=mix(u_eyeColor.bgr,vec3(1.0,0.65,0.32),0.7);\n  vec3 color=mix(u_skullColor,u_eyeColor*0.26,light)*(0.26+light);\n  color+=mix(u_eyeColor,warm,smoothstep(-0.3,0.5,height))*(contours+fine)*(0.15+light*0.46);\n  float fronts=0.0;\n  float crossings=0.0;\n  float previous=0.0;\n  for(int lobe=0;lobe<3;lobe++){\n    float index=float(lobe);\n    vec2 source=index<.5?vec2(-.22,.16):\n      (index<1.5?vec2(.22,.16):vec2(0.0,u_mouthY));\n    source+=index<1.5?u_gaze:vec2(0.0,-u_talk*.035);\n    float distance=length(point-source);\n    float phase=distance*(3.1+index*0.37)-time*(0.43+index*0.071)+index*0.29;\n    float wave=ridge(phase,0.065)*exp(-distance/max(u_lobeReach,0.05));\n    crossings+=wave*previous;\n    previous+=wave;\n    fronts+=wave;\n    color+=mix(u_eyeColor,warm,index*0.42)*wave*(0.32+u_hover*0.3);\n    color+=mix(warm,u_eyeColor,index*0.3)*exp(-distance*distance*850.0)\n      *u_eyeBright*(1.0+(index>1.5?hit:high));\n  }\n  // Paired listening eyes, bridge, cheeks and speaking contact mouth.\n  float blink=max(.08,1.0-u_blink*.92);\n  vec2 eyes=vec2(abs(point.x)-.22,(point.y-.16)/blink);\n  float eyeWell=exp(-pow(eyes.x/.105,2.0)-pow(eyes.y/.075,2.0));\n  vec2 irisPoint=vec2(abs(point.x-u_gaze.x)-.22,point.y-.16-u_gaze.y);\n  float iris=exp(-dot(irisPoint,irisPoint)*520.0);\n  float brow=exp(-pow((abs(point.x)-.22)/.17,2.0)-pow((point.y-.29)/.04,2.0));\n  float bridge=exp(-abs(point.x)*55.0)*smoothstep(.16,.04,point.y)\n    *smoothstep(-.17,-.05,point.y);\n  float nose=exp(-pow(point.x/.065,2.0)-pow((point.y+.11)/.04,2.0));\n  float mouthCurve=u_mouthY+.045*u_smile*cos(point.x*5.0);\n  float mouth=exp(-abs(point.y-mouthCurve)*58.0)\n    *exp(-max(0.0,abs(point.x)-.25)*32.0);\n  float throat=exp(-pow(point.x/.13,2.0)\n    -pow((point.y-mouthCurve)/(max(.025,u_talk*.07)),2.0));\n  float cheeks=exp(-pow((abs(point.x)-.34)/.12,2.0)-pow((point.y+.10)/.20,2.0));\n  color-=vec3(.12)*eyeWell*.45;\n  color+=u_eyeColor*(iris*(1.2+high)+brow*.42+bridge*.48+nose*.36);\n  color+=warm*(mouth*.68+throat*(.38+hit)+cheeks*.10);\n  float islands=ridge((height+fronts*0.12)*15.0,0.085);\n  color+=warm*islands*crossings*8.0*u_contactBloom;\n  float lip=exp(-abs(edge-0.012)*70.0);\n  color+=mix(warm,u_eyeColor,0.5+0.5*sin(angle*3.0))*lip*(0.8+u_coronaW);\n  color*=membrane*u_faceGlow;\n  float anatomy=eyeWell+iris+brow+bridge+nose+mouth+throat+cheeks;\n  float alpha=max(membrane*clamp(0.38+light*0.28+contours*0.2+fronts*0.28+lip,0.0,0.97),clamp(anatomy*.7,0.0,.98));\n  gl_FragColor=vec4((1.0-exp(-color*1.6))*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p/vec2(.71,.84)),ang=atan(p.y,p.x);\n float contours=exp(-abs(sin((r*29.+sin(ang*3.)*2.)-t*.24))*21.)*head;\n float fronts=gfArtRing(p-vec2(.19*sin(t*.17),-.04),.44+.10*sin(t*.31)+bass*.035,.012);\n float lobes=gfArtRing(p-vec2(-.62,.02),.17,.012)+gfArtRing(p-vec2(.62,.02),.17,.012);\n float meridians=pow(.5+.5*cos(ang*18.+r*12.),30.)*gfArtRing(p,.69,.018);\n vec2 ep=vec2(abs(p.x)-.22,p.y-.15);\n float eyeTerrain=exp(-abs(sin(length(ep)*88.-t*.6))*17.)*exp(-dot(ep,ep)*38.);\n float mouthIsland=gfArtLine(p.y+.31-.042*cos(p.x*7.)-.012*sin(p.x*29.),.010)\n   *smoothstep(.39,.08,abs(p.x));\n float bloom=exp(-pow((length(p-vec2(0.,-.27))-(.12+hit*.22))/.018,2.))*hit;\n c+=mix(eye,vec3(.25,.91,.82),.32)*(contours*.18+fronts*.25+lobes*.34+meridians*.25+eyeTerrain*.32);\n c+=warm*(mouthIsland*.38+bloom*.72);\n a+=contours*.06+fronts*.08+lobes*.11+meridians*.09+eyeTerrain*.08+mouthIsland*.10+bloom*.16;\n c*=1.050*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.930+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v18.0","title":"The Returning Song","defaults":{"boltCoreW":280,"boltGlowW":6,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.82,"bgAlphaBase":0.2,"bgAlphaScale":0.85,"bgAlphaMax":0.72,"bgTintR":0.09,"bgTintG":0.16,"bgTintB":0.22,"tunerFadeSpeed":200,"orbFaceGlow":1.22,"orbEyeBright":1.05,"orbCoronaW":0.82,"orbEyeSize":0.15,"orbMouthY":-0.3,"orbScanFreq":41,"orbSkullSize":2,"orbScale":1.1,"orbEyeR":0.22,"orbEyeG":0.8,"orbEyeB":0.85,"orbSkullR":0.12,"orbSkullG":0.18,"orbSkullB":0.22,"opening":0.48,"separation":1.15,"phraseTravel":1,"returnStrength":0.7,"quiet":0.55,"warmth":0.7},"bgShader":"\nprecision highp float;\nvarying vec2 v_uv;\nuniform float u_time,u_alphaBase,u_alphaScale,u_alphaMax;\nuniform vec3 u_tint;\nvoid main(){\n vec2 p=v_uv*2.-1.;float t=u_time*.045;\n float r=length(p),a0=atan(p.y,p.x);\n vec3 c=u_tint*.12;float strength=0.;\n for(int i=0;i<8;i++){\n  float n=float(i),y=-.74+n*.205;\n  float wave=.045*sin(p.x*(2.+n*.27)+t+n*.9)+.020*sin(p.x*10.-t*.7+n);\n  float d=abs(p.y-y-wave);\n  float lane=exp(-d*d/(.000045+n*.000008));\n  float window=smoothstep(-1.05,-.82,p.x)*(1.-smoothstep(.78,1.05,p.x));\n  float reflection=.25+.75*pow(.5+.5*sin(p.x*21.+n*4.-t),8.);\n  strength+=lane*window*reflection;\n  c+=mix(vec3(.10,.64,.82),vec3(.92,.36,.16),n/7.)*lane*window*reflection*1.55;\n }\n float harbour=exp(-abs(r-(.77+.035*sin(a0*5.-t*2.)))*38.)\n   *smoothstep(-.15,-.68,p.y);\n float aurora=exp(-abs(sin(a0*3.+r*12.-t*1.6))*10.)\n   *exp(-pow((r-.78)/.30,2.))*.18;\n float stars=pow(fract(sin(dot(floor((p+1.)*83.),vec2(127.1,311.7)))*43758.5),48.);\n float dawn=exp(-pow((p.y-.09)/.28,2.))*exp(-pow((p.x-.36)/.72,2.));\n c+=vec3(.48,.20,.10)*dawn*.23;\n c+=mix(vec3(.10,.58,.76),vec3(.86,.34,.17),.48)*(harbour*.22+aurora);\n c+=vec3(.55,.86,1.)*stars*.32;\n float alpha=clamp(u_alphaBase*.52+(strength*.52+dawn*.30+harbour*.24+aurora*.55+stars*.2)*u_alphaScale,0.,u_alphaMax);\n gl_FragColor=vec4(c,alpha);\n}","boltShader":"\nprecision highp float;\nvarying vec2 v_uv;\nuniform float u_time,u_boltMult,u_coreW,u_glowW;\nuniform vec2 u_resolution;\nuniform int u_arcCount;\nuniform vec2 u_arcStart[32],u_arcEnd[32];\nuniform float u_arcAlpha[32];\nuniform vec3 u_arcColor[32];\nvoid main(){\n vec2 p=v_uv*u_resolution;vec3 colour=vec3(0.);float alpha=0.;\n for(int i=0;i<32;i++){\n  if(i>=u_arcCount)break;\n  vec2 delta=u_arcEnd[i]-u_arcStart[i];float len=length(delta);\n  if(len<1.)continue;\n  vec2 dir=delta/len,rel=p-u_arcStart[i];\n  float x=dot(rel,dir)/len;\n  float bend=sin(x*3.14159)*len*.060*sin(float(i)*1.3+.7)\n    +sin(x*6.28318+u_time*.17+float(i))*len*.014;\n  float d=abs(dot(rel,vec2(-dir.y,dir.x))-bend);\n  float phase=fract(u_time*.10+float(i)*.191);\n  float pos=1.-abs(phase*2.-1.);\n  float pulse=exp(-pow((x-pos)/.12,2.));\n  float stitch=smoothstep(.35,.6,.5+.5*cos(x*len*.16-u_time*.65));\n  float width=max(.75,len/max(u_coreW,40.));\n  float line=exp(-d*d/(width*width));\n  float halo=exp(-d/max(u_glowW,1.))*.06;\n  float ends=smoothstep(0.,.04,x)*(1.-smoothstep(.96,1.,x));\n  float s=(line*stitch+halo)*(.08+pulse*.72)*ends*u_arcAlpha[i]*u_boltMult*.62;\n  colour+=mix(u_arcColor[i],vec3(1.,.77,.46),pulse*.4)*s;\n  alpha+=s;\n }\n gl_FragColor=vec4(1.-exp(-colour*1.6),clamp(alpha,0.,1.));\n}","shader":"\nprecision highp float;\nvarying vec2 v_uv;\nuniform float u_time,u_scale,u_faceGlow,u_hover,u_eyeBright,u_coronaW;\nuniform float u_eyeSize,u_mouthY,u_talk,u_blink,u_smile;\nuniform vec2 u_gaze;\nuniform vec3 u_eyeColor,u_skullColor;\nuniform vec4 u_cymatics;\nuniform float u_opening,u_separation,u_phraseTravel,u_returnStrength,u_quiet,u_warmth;\nvoid gfLineageNativeMain(){\n vec2 p=(v_uv*2.-1.)*max(u_scale,.1);\n float bass=u_cymatics.x,mid=u_cymatics.y,high=u_cymatics.z,hit=u_cymatics.w;\n vec3 light=vec3(0.);float cover=0.;\n float t=u_time*u_phraseTravel*(1.+mid*.42);\n vec3 warm=mix(vec3(1.,.48,.10),vec3(1.,.80,.50),u_warmth);\n\n // Nine independent phrases become a woven harbour around the face.\n for(int i=0;i<9;i++){\n  float n=float(i),x=p.x;\n  float lane=(n-4.)*.115*u_separation;\n  float side=sign(lane+.001);\n  float arch=sqrt(max(0.,1.-pow((x+.055*sin(n*2.17))/1.06,2.)));\n  float y=lane*(.72+u_opening*.25)+side*arch*(.055+.014*abs(n-4.));\n  y+=.055*sin(x*(3.7+n*.13)+n*1.43+t*(.10+n*.004))\n    +.042*x*sin(n*1.7)+.025*sin(t*.21+n*2.1)+bass*.018*side;\n  float d=abs(p.y-y);\n  float ends=smoothstep(-1.08,-.88,x)*(1.-smoothstep(.84,1.06,x));\n  float phase=fract(t*(.058+n*.0035)+n*.137);\n  float note=exp(-pow((x-mix(-1.,1.,phase))/.13,2.));\n  float rest=1.-u_quiet*.78*smoothstep(.67,.79,phase)*(1.-smoothstep(.90,.99,phase));\n  float width=.0044+n*.00055;\n  float silk=1.-smoothstep(width*.58,width*1.72,d);\n  float glow=exp(-d*d/.00068)*.18;\n  float echo=exp(-pow((d-.022)/.0042,2.))*.20*u_returnStrength;\n  float strength=(silk*(.38+note*.86)+glow+echo)*ends*rest;\n  vec3 phrase=mod(n,3.)<.5?u_eyeColor:(mod(n,3.)<1.5?vec3(.66,.29,1.):warm);\n  phrase=mix(phrase,phrase*vec3(1.16,.93,.86),u_warmth*.34);\n  light+=phrase*strength*(1.+u_hover*.15)*2.55;\n  cover+=strength;\n }\n\n // A translucent woven membrane keeps the face richly present in silence.\n vec2 hc=(p-vec2(0.,-.035))/vec2(.60,.74+bass*.020);\n float hr=length(hc),ha=atan(hc.y,hc.x);\n float head=1.-smoothstep(.90,1.02,hr);\n float rim=exp(-abs(hr-(.97+.018*sin(ha*7.-t*.08)))*30.);\n float jaw=rim*smoothstep(.18,-.36,p.y);\n float cheeks=exp(-pow((abs(p.x)-.34)/.13,2.)-pow((p.y+.10)/.22,2.));\n float weaveA=exp(-abs(sin((hc.x+hc.y)*18.+sin(hc.y*8.)*2.-t*.17))*20.)*head;\n float weaveB=exp(-abs(sin((hc.x-hc.y)*21.+sin(hc.x*7.)*2.+t*.13))*23.)*head;\n float tide=exp(-abs(sin(hr*31.+sin(ha*5.)*2.-t*.19))*25.)*head;\n vec3 songShell=mix(u_skullColor,mix(u_eyeColor,warm,.48),.20);\n light+=songShell*(head*.30+rim*.82+jaw*(.52+bass*.62)+cheeks*.20);\n light+=mix(u_eyeColor,warm,.45)*(weaveA*.055+weaveB*.05+tide*(.035+mid*.055));\n cover+=head*.31+rim*.48+jaw*.28+cheeks*.14+(weaveA+weaveB+tide)*.025;\n\n // Almond listening eyes hold returning rings and treble-lit irises.\n float blink=max(.08,1.-u_blink*.92);\n vec2 eye=vec2(abs(p.x-u_gaze.x)-.22,(p.y-.16-u_gaze.y)/blink);\n float socket=exp(-pow(eye.x/.145,4.)-pow(eye.y/.085,2.));\n float almond=exp(-abs(abs(eye.y)-(.070-.36*eye.x*eye.x))*68.)\n   *smoothstep(.15,.05,abs(eye.x));\n float iris=exp(-dot(eye/vec2(.050,.059),eye/vec2(.050,.059))*1.25);\n float irisRing=exp(-pow((length(eye)-.069)/.010,2.));\n float eyeEcho=exp(-pow((length(eye)-.096)/.012,2.))*u_returnStrength;\n light-=vec3(.10)*socket*.58;\n light+=mix(u_eyeColor,vec3(.84,1.,1.),.22)\n   *(almond*.55+iris*(2.10+high*1.5)+irisRing*(.58+high*.62)\n   +eyeEcho*(.48+high*.55))*u_eyeBright;\n cover+=socket*.28+almond*.22+iris*.84+irisRing*.22+eyeEcho*.25;\n\n float brow=exp(-pow((abs(p.x)-.22)/.15,2.)-pow((p.y-.278)/.032,2.));\n light+=mix(u_eyeColor,warm,.30)*brow*.55;cover+=brow*.24;\n\n // Two melodic paths braid into the nose without becoming one voice.\n float bridge=exp(-abs(abs(p.x)-(.012+.012*sin((p.y+.1)*19.)))*72.)\n   *smoothstep(.18,.08,p.y)*smoothstep(-.18,-.04,p.y);\n float nose=exp(-pow(p.x/.065,2.)-pow((p.y+.12)/.04,2.));\n light+=mix(u_skullColor,u_eyeColor,.48)*(bridge*.68+nose*.54);\n cover+=bridge*.31+nose*.23;\n\n // A layered waveform mouth opens with speech; each attack visibly returns.\n float mY=u_mouthY-u_talk*(.025+.035*abs(sin(u_time*16.)));\n float curve=mY+.045*u_smile*cos(p.x*5.2)+.012*sin(p.x*15.+t*.35);\n float mouth=exp(-abs(p.y-curve)*64.)*exp(-max(0.,abs(p.x)-.27)*36.);\n float lowerLip=exp(-abs(p.y-curve+.024+.035*u_talk)*72.)\n   *exp(-max(0.,abs(p.x)-.235)*34.);\n float returning=exp(-abs(abs(p.y-curve)-.036)*70.)\n   *exp(-max(0.,abs(p.x)-.25)*30.)*u_returnStrength;\n float fromMouth=length(p-vec2(0.,mY));\n float attackReturn=exp(-pow((fromMouth-(.13+.24*hit))/.022,2.))*hit;\n light+=warm*(mouth*1.08+lowerLip*(.34+u_talk*.48)+returning*.40+attackReturn*.82);\n cover+=mouth*.74+lowerLip*.22+returning*.24+attackReturn*.48;\n\n float alpha=clamp(max(cover*1.48,head*.54),0.,.98);\n vec3 colour=light*max(u_faceGlow,.1);\n colour=colour/(1.+max(max(colour.r,colour.g),colour.b)*.65);\n gl_FragColor=vec4(colour*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p/vec2(.70,.82)),ang=atan(p.y,p.x);\n float shelter=gfArtLine(r-(.96+.030*sin(ang*5.-t*.18)\n   +.014*sin(ang*11.+t*.11)),.012);\n float harbour=gfArtLine(p.y+.50-.055*cos(p.x*3.8)\n   -.018*sin(p.x*13.+t*.28),.010)*smoothstep(.72,.22,abs(p.x));\n float aurora=0.;\n aurora+=gfArtLine(p.y-.56-.055*sin(p.x*2.7-t*.20),.008);\n aurora+=gfArtLine(p.y-.48-.050*sin(p.x*3.1-t*.24+1.7),.007);\n aurora+=gfArtLine(p.y+.51-.045*sin(p.x*3.5+t*.19),.007);\n aurora+=gfArtLine(p.y+.59-.052*sin(p.x*2.9+t*.23+2.1),.008);\n float weaveA=exp(-abs(sin((p.x+p.y)*20.+sin(p.y*7.)*2.-t*.28))*24.)*head;\n float weaveB=exp(-abs(sin((p.x-p.y)*23.+sin(p.x*8.)*2.+t*.22))*27.)*head;\n float veil=(weaveA+weaveB)*smoothstep(.93,.30,r)*.22;\n vec2 ep=vec2(abs(p.x)-.22,p.y-.16);\n float irises=gfArtRing(ep,.060+.010*high,.010)+exp(-dot(ep,ep)*560.);\n float lashes=pow(max(0.,cos(atan(ep.y,ep.x)*5.)),20.)\n   *gfArtRing(ep,.10,.018);\n float knots=pow(.5+.5*cos(ang*11.+r*27.-t*.45),34.)*shelter;\n float throat=gfArtRing(p-vec2(0.,-.33),.13+.024*bass,.011);\n float lips=gfArtLine(p.y+.29-.038*cos(p.x*7.)\n   -.014*sin(p.x*25.-t*.34),.009)*smoothstep(.38,.07,abs(p.x));\n float returnArc=gfArtRing(p-vec2(0.,-.27),.16+.24*hit,.012)*hit;\n float songContours=exp(-abs(sin(r*34.+sin(ang*6.)*2.3-t*.22))*24.)*head;\n c+=mix(eye,vec3(.63,.30,1.),.42)*(aurora*(.28+mid*.46)\n   +shelter*.38+irises*(.72+high*1.15)+lashes*(.35+high*.42)\n   +knots*.48+veil*(1.+mid*.85)+songContours*(.10+mid*.18));\n c+=warm*(harbour*.34+throat*(.38+bass*.58)+lips*(.58+hit*.72)\n   +returnArc*1.20);\n a+=aurora*.08+shelter*.14+irises*.21+lashes*.09+knots*.10\n   +veil*.07+harbour*.10+throat*.10+lips*.14+returnArc*.17\n   +songContours*.04;\n c*=1.340*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.960+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"},{"id":"v19.0","title":"The Guest Light","defaults":{"boltCoreW":270,"boltGlowW":7,"boltAtmoW":13,"boltWideW":1.5,"boltFlicker":0,"boltFlashRate":0.81,"boltMult":0.86,"bgAlphaBase":0.22,"bgAlphaScale":0.94,"bgAlphaMax":0.82,"bgTintR":0.1,"bgTintG":0.2,"bgTintB":0.28,"tunerFadeSpeed":200,"orbFaceGlow":1.24,"orbEyeBright":1.22,"orbCoronaW":0.88,"orbEyeSize":0.16,"orbMouthY":-0.27,"orbScanFreq":41,"orbSkullSize":1,"orbScale":1.08,"orbEyeR":0.28,"orbEyeG":0.88,"orbEyeB":0.92,"orbSkullR":0.13,"orbSkullG":0.24,"orbSkullB":0.3,"guestThreshold":1,"hostBreath":0.72,"consentRing":1,"lineageDepth":1.1,"hearthWarmth":0.72,"listeningReach":1,"futureHome":0.65},"bgShader":"\nprecision highp float;\nvarying vec2 v_uv;\nuniform float u_time,u_alphaBase,u_alphaScale,u_alphaMax;\nuniform vec3 u_tint;\nvoid main(){\n vec2 p=v_uv*2.-1.;float r=length(p),a=atan(p.y,p.x);\n vec3 colour=u_tint*.045;float signal=0.;\n for(int i=0;i<8;i++){\n  float n=float(i),depth=n/7.;\n  vec2 q=p+vec2(.026*sin(u_time*.045+n*1.7),-.018*n);\n  float qr=length(q/vec2(.76,.91));float qa=atan(q.y,q.x);\n  float edge=.34+n*.095+.038*sin(qa*3.+n*1.2-u_time*.045)\n    +.018*sin(qa*7.-n*.6+u_time*.031);\n  float room=exp(-abs(qr-edge)*(54.-n*3.5));\n  float gate=1.-smoothstep(.12+.01*n,.30+.01*n,abs(qa+1.5708));\n  float breath=.55+.45*sin(u_time*.11-n*.72);\n  vec3 layer=mix(u_tint,mix(vec3(.42,.16,.76),vec3(.82,.35,.12),depth),.58);\n  colour+=layer*room*gate*(.05+breath*.052);\n  signal+=room*gate*(.035+depth*.032);\n }\n float throat=-log(max(r,.018));\n float spiral=exp(-abs(sin(a*5.+throat*8.-u_time*.10))*15.)\n   *exp(-r*1.45)*smoothstep(.04,.23,r);\n float dust=pow(fract(sin(dot(floor((p+1.)*96.)+floor(u_time*1.5),vec2(127.1,311.7)))*43758.5),49.);\n float floorGlow=exp(-pow((p.y+.72)/.18,2.))*(.35+.65*(1.-abs(p.x)));\n colour+=mix(u_tint,vec3(.76,.34,.13),.45)*floorGlow*.14;\n colour+=mix(u_tint,vec3(.44,.20,.78),.42)*spiral*.18+vec3(.55,.86,1.)*dust*.18;\n signal+=floorGlow*.10+spiral*.15+dust*.06;\n float alpha=clamp(u_alphaBase+(signal+floorGlow*.12)*u_alphaScale,0.,u_alphaMax);\n gl_FragColor=vec4(colour,alpha);\n}","boltShader":"\nprecision highp float;\nvarying vec2 v_uv;\nuniform float u_time,u_boltMult,u_coreW,u_glowW,u_flickBase;\nuniform vec2 u_resolution;\nuniform int u_arcCount;\nuniform vec2 u_arcStart[32],u_arcEnd[32];\nuniform float u_arcAlpha[32];\nuniform vec3 u_arcColor[32];\nvoid main(){\n vec2 p=v_uv*u_resolution;vec3 colour=vec3(0.);float alpha=0.;\n for(int i=0;i<32;i++){\n  if(i>=u_arcCount)break;\n  vec2 delta=u_arcEnd[i]-u_arcStart[i];float len=length(delta);\n  if(len<1.)continue;\n  vec2 dir=delta/len,rel=p-u_arcStart[i];\n  float x=dot(rel,dir)/len;\n  float bend=sin(x*3.14159)*len*.055*sin(float(i)*1.73+.4)\n    +sin(x*6.28318+u_time*.16+float(i))*len*.012;\n  float d=abs(dot(rel,vec2(-dir.y,dir.x))-bend);\n  float boundary=.82;\n  float permitted=smoothstep(0.,.04,x)*(1.-smoothstep(boundary-.035,boundary,x));\n  float journey=1.-abs(fract(u_time*.12+float(i)*.193)*2.-1.);\n  float pulsePos=min(boundary,journey*boundary);\n  float pulse=exp(-pow((x-pulsePos)/.055,2.));\n  float returnMark=exp(-pow((x-boundary)/.018,2.))*smoothstep(.72,.82,journey);\n  float width=max(.65,len/max(u_coreW,40.));\n  float thread=exp(-d*d/(width*width));\n  float echo=exp(-pow((d-width*3.)/max(1.,width*.8),2.))*.10;\n  float halo=exp(-d/max(u_glowW,1.))*.052;\n  float strength=(thread*(.08+pulse*.76)+echo*pulse+halo*.16)*permitted\n    *u_arcAlpha[i]*u_boltMult*.64;\n  strength+=returnMark*exp(-d*d/max(1.,width*width*2.))\n    *u_arcAlpha[i]*u_boltMult*.48;\n  colour+=mix(u_arcColor[i],vec3(1.,.72,.38),returnMark)*strength;\n  alpha+=strength;\n }\n gl_FragColor=vec4(1.-exp(-colour*1.7),clamp(alpha*(.9+.1*u_flickBase),0.,1.));\n}","shader":"\nprecision highp float;\nvarying vec2 v_uv;\nuniform float u_time,u_hover,u_faceGlow,u_eyeBright,u_coronaW;\nuniform float u_eyeSize,u_mouthY,u_talk,u_scanFreq,u_skullSize,u_scale;\nuniform float u_blink,u_smile;\nuniform vec2 u_gaze;\nuniform vec3 u_eyeColor,u_skullColor;\nuniform vec4 u_cymatics;\nuniform float u_guestThreshold,u_hostBreath,u_consentRing,u_lineageDepth;\nuniform float u_hearthWarmth,u_listeningReach,u_futureHome;\nmat2 turn(float a){float s=sin(a),c=cos(a);return mat2(c,-s,s,c);}\nfloat ridge(float d,float w){return exp(-abs(d)/max(w,.001));}\nfloat livingShell(vec2 q,float radius,float phase,float width){\n float a=atan(q.y,q.x),r=length(q/vec2(.76,.91));\n float edge=radius+.035*sin(a*3.+phase)+.018*sin(a*7.-phase*.7);\n return ridge(r-edge,width);\n}\nfloat terrain(vec2 q){\n float f=0.,w=.55;\n for(int i=0;i<4;i++){\n  q=turn(.67)*q;f+=w*sin(q.x*3.2+sin(q.y*2.8));\n  q=abs(q)*1.68-vec2(.63,.41);w*=.48;\n }\n return f;\n}\nvoid gfLineageNativeMain(){\n vec2 p=(v_uv*2.-1.)*max(u_scale,.1);\n float bass=u_cymatics.x,mid=u_cymatics.y,high=u_cymatics.z,hit=u_cymatics.w;\n float t=u_time;\n vec3 cyan=u_eyeColor;\n vec3 violet=mix(vec3(.46,.18,.82),cyan,.32);\n vec3 hearth=mix(vec3(1.,.42,.12),vec3(1.,.84,.55),u_hearthWarmth);\n vec3 light=vec3(0.);float cover=0.;\n\n // Borrowed rooms are breathing, asymmetric thresholds—not filing cabinets.\n for(int i=0;i<6;i++){\n  float n=float(i),depth=n/5.;\n  vec2 q=turn(.025*sin(t*.07+n*1.9))*p;\n  q+=vec2(.018*sin(t*u_hostBreath*.13+n*2.3),-.012*n);\n  float shell=livingShell(q,.64+n*.075+bass*.008,n*1.13-t*.055,.010+n*.0015);\n  float opening=1.-smoothstep(.10+.025*n,.27+.020*n,abs(atan(q.y,q.x)+1.5708));\n  float threshold=shell*opening;\n  vec3 room=mix(cyan,mix(violet,hearth,.48),depth);\n  light+=room*threshold*(.15+n*.040)*u_guestThreshold;\n  cover+=threshold*(.040+n*.008);\n }\n\n // Consent is a broken aurora ring, explicitly visual metaphor—not authority.\n float pa=atan(p.y,p.x),pr=length(p);\n float boundaryRadius=.80+u_consentRing*.052+.014*sin(pa*5.-t*.16)+high*.009;\n float boundary=ridge(pr-boundaryRadius,.016)*max(.2,u_coronaW);\n float boundaryGate=1.-smoothstep(.13,.29,abs(pa+1.5708));\n float aurora=.55+.45*sin(pa*7.+t*.19+mid*2.);\n light+=mix(cyan,hearth,.30)*boundary*(.44+high*.56)*boundaryGate*(.68+aurora*.32);\n cover+=boundary*.19*boundaryGate;\n\n // The face is a topographic stained-glass membrane sheltered by the rings.\n vec2 hc=(p-vec2(0.,-.035))/vec2(.57,.71+bass*.020);\n hc/=max(.5,u_skullSize);\n float hr=length(hc),ha=atan(hc.y,hc.x);\n float edge=.965+.020*sin(ha*5.-t*.08)+.010*sin(ha*11.+t*.05);\n float head=1.-smoothstep(edge-.06,edge+.035,hr);\n float rim=ridge(hr-edge,.020);\n float jaw=rim*smoothstep(.18,-.38,p.y);\n float relief=terrain(hc*1.45+vec2(0.,t*.012));\n float contours=ridge(fract((relief+hr*1.7-mid*.18)*u_lineageDepth*4.)-.5,.075)\n   *head*smoothstep(.18,.95,hr);\n float fine=ridge(fract((relief-ha*.22+t*.018)*9.)-.5,.055)*head*.35;\n float stainedA=exp(-abs(sin((hc.x+hc.y)*14.+relief*4.-t*.10))*18.)*head;\n float stainedB=exp(-abs(sin((hc.x-hc.y)*17.-relief*3.+t*.08))*21.)*head;\n float cheeks=exp(-pow((abs(p.x)-.32)/.14,2.)-pow((p.y+.10)/.22,2.));\n vec3 guestShell=mix(u_skullColor,mix(cyan,hearth,.52),.46);\n light+=guestShell*(head*.38+rim*.98+jaw*(.60+bass*.74)+cheeks*.22);\n light+=mix(violet,hearth,.42)*(contours*(.20+mid*.27)+fine*.15);\n light+=mix(cyan,violet,.48)*(stainedA*.055+stainedB*.050)*(1.+mid*.55);\n cover+=head*.36+rim*.54+jaw*.31+cheeks*.15+contours*.075+fine*.035\n   +(stainedA+stainedB)*.024;\n\n // Paired listening constellations remain recognisable before audio arrives.\n float blink=max(.08,1.-u_blink*.92);\n vec2 eye=vec2(abs(p.x-u_gaze.x)-.215,(p.y-.16-u_gaze.y)/blink);\n float eyeScale=max(.42,u_eyeSize/.16);\n float well=exp(-pow(eye.x/(.14*eyeScale),4.)-pow(eye.y/(.087*eyeScale),2.));\n float almond=ridge(abs(eye.y)-(.071*eyeScale-.34*eye.x*eye.x),.013)\n   *smoothstep(.16*eyeScale,.045,abs(eye.x));\n float er=length(eye),ea=atan(eye.y,eye.x);\n float iris=exp(-er*er*580.);\n float irisRing=ridge(er-.067*eyeScale,.010);\n float choices=pow(max(0.,cos(ea*3.)),18.)*exp(-er*17.)\n   *smoothstep(.018,.045,er)*u_listeningReach;\n float stars=pow(.5+.5*cos(ea*6.+relief*3.-t*.08),24.)*irisRing;\n light-=vec3(.12)*well*.58;\n light+=mix(cyan,vec3(.88,1.,1.),.16)*(almond*.62+iris*(2.25+high*1.55)\n   +irisRing*(.62+high*.55)+choices*(.62+high*.72)+stars*.38)*u_eyeBright;\n cover+=well*.30+almond*.26+iris*.90+irisRing*.24+choices*.22+stars*.10;\n\n float brow=ridge(p.y-(.285-.13*pow((abs(p.x)-.215)/.18,2.)),.020)\n   *smoothstep(.42,.05,abs(abs(p.x)-.215));\n light+=mix(cyan,hearth,.25)*brow*.60;cover+=brow*.25;\n\n // A compass bridge points inward, but its branches keep three futures open.\n float bridge=ridge(abs(p.x)-(.010+.010*sin((p.y+.08)*18.)),.011)\n   *smoothstep(.20,.07,p.y)*smoothstep(-.19,-.05,p.y);\n vec2 compass=vec2(p.x,(p.y+.12)*1.28);\n float diamond=ridge(abs(compass.x)+abs(compass.y)-.070,.012)\n   *smoothstep(.13,.045,length(compass));\n float compassRays=pow(max(0.,cos(atan(compass.y,compass.x)*3.)),20.)\n   *exp(-length(compass)*22.)*smoothstep(.025,.070,length(compass));\n light+=mix(cyan,hearth,.34)*(bridge*.76+diamond*.72+compassRays*.30);\n cover+=bridge*.34+diamond*.31+compassRays*.12;\n\n // The mouth is a warm arched doorway that visibly speaks and returns attack.\n float mY=u_mouthY-u_talk*(.024+.036*abs(sin(t*16.)));\n vec2 door=p-vec2(0.,mY);\n float doorHeight=.072+u_talk*.058;\n float dr=length(door/vec2(.235,doorHeight));\n float doorFrame=ridge(dr-(1.+.040*sin(atan(door.y,door.x)*3.)),.075)\n   *smoothstep(.30,.03,abs(door.x));\n float doorway=(1.-smoothstep(.68,.94,dr))*smoothstep(-.02,.07,door.y+doorHeight*.30);\n float smile=ridge(door.y-.038*u_smile*cos(door.x*6.2),.012)\n   *smoothstep(.28,.04,abs(door.x));\n float lowerLip=ridge(door.y+.032+.040*u_talk,.014)*smoothstep(.22,.04,abs(door.x));\n float returnWave=ridge(length(door)-(.13+hit*.27),.020)*hit;\n light-=vec3(.10)*doorway*.42;\n light+=hearth*(doorFrame*.90+smile*.88+lowerLip*(.34+u_talk*.48)\n   +doorway*(.22+u_talk*.42)+returnWave*.90);\n cover+=doorFrame*.50+smile*.46+lowerLip*.21+doorway*.25+returnWave*.46;\n\n // A possible home stays outside the present boundary, luminous but unclaimed.\n float roof=livingShell(p-vec2(0.,.02),1.12,t*.04,.012)\n   *smoothstep(.08,.48,p.y)*u_futureHome;\n float hearthDust=pow(fract(sin(dot(floor((p+1.)*91.)+floor(t*2.),vec2(127.1,311.7)))*43758.5),46.)\n   *head*(.25+high*.75);\n light+=hearth*(roof*.24+hearthDust*(.25+hit*.45));\n cover+=roof*.08+hearthDust*.07;\n\n light*=1.+u_hover*.12;\n float alpha=clamp(max(cover*1.55,head*.58),0.,.985);\n vec3 colour=light*max(u_faceGlow,.1);\n colour=colour/(1.+max(max(colour.r,colour.g),colour.b)*.62);\n gl_FragColor=vec4(colour*alpha,alpha);\n}\n\nfloat gfArtHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453123);}\nfloat gfArtLine(float d,float w){return exp(-abs(d)/max(w,.0005));}\nfloat gfArtRing(vec2 p,float radius,float width){return gfArtLine(length(p)-radius,width);}\nfloat gfArtBox(vec2 p,vec2 halfSize,float width){\n vec2 d=abs(p)-halfSize;\n return gfArtLine(length(max(d,0.))+min(max(d.x,d.y),0.),width);\n}\nfloat gfArtSeg(vec2 p,vec2 a,vec2 b,float width){\n vec2 pa=p-a,ba=b-a;\n float h=clamp(dot(pa,ba)/max(dot(ba,ba),.0001),0.,1.);\n return exp(-length(pa-ba*h)/max(width,.0005));\n}\nvec4 gfLineageFinish(vec2 p){\n float t=u_time,bass=u_cymatics.x,mid=u_cymatics.y;\n float high=u_cymatics.z,hit=u_cymatics.w;\n vec3 eye=max(u_eyeColor,vec3(.015));\n vec3 bone=max(u_skullColor,vec3(.012));\n vec3 warm=vec3(1.,.64,.24);\n float head=1.-smoothstep(.76,.88,length((p-vec2(0.,-.02))/vec2(.82,1.)));\n vec3 c=vec3(0.);float a=0.;\n\n float r=length(p/vec2(.71,.83)),ang=atan(p.y,p.x);\n float rooms=0.;\n rooms+=gfArtLine(r-(1.02+.035*sin(ang*3.-t*.17)),.012);\n rooms+=gfArtLine(r-(.91+.027*sin(ang*5.+t*.13)),.008)*.72;\n rooms+=gfArtLine(r-(.80+.020*sin(ang*7.-t*.11)),.007)*.48;\n float boundary=gfArtRing(p,.83+.014*sin(ang*5.-t*.2),.012)\n   *(1.-smoothstep(.12,.24,abs(ang+1.5708)));\n vec2 ep=vec2(abs(p.x)-.205,p.y-.16);\n float windows=gfArtRing(ep,.078+.008*sin(atan(ep.y,ep.x)*2.),.012)\n   +gfArtRing(ep,.045,.008);\n float choices=pow(abs(cos(atan(ep.y,ep.x)*3.)),22.)\n   *exp(-length(ep)*17.)*smoothstep(.018,.05,length(ep));\n float dust=pow(gfArtHash(floor((p+1.)*96.)+floor(t*3.)),43.)*head*(.22+high);\n float roof=gfArtLine(r-(1.12+.055*cos(ang*3.)),.010)\n   *smoothstep(.05,.40,p.y);\n vec2 door=p-vec2(0.,-.31);\n float threshold=gfArtLine(length(door/vec2(.22,.13))-(1.+.04*sin(ang*4.)),.025)\n   *smoothstep(-.47,-.18,p.y);\n float roomContours=exp(-abs(sin(length(p/vec2(.70,.82))*30.\n   +sin(ang*4.)*1.5-t*.17))*22.)*head;\n float memory=exp(-abs(sin((r*27.+sin(ang*7.)*2.)-t*.19))*24.)\n   *head*smoothstep(.91,.35,r);\n c+=mix(eye,vec3(.47,1.,.94),.30)*(rooms*(.20+bass*.22)+boundary*.36\n   +windows*(.45+high*.65)+choices*(.30+mid*.86)+dust*(.45+high*.60)\n   +roomContours*(.08+bass*.08)+memory*(.11+mid*.24));\n c+=warm*(roof*.22+threshold*(.58+hit*1.20));\n a+=rooms*.07+boundary*.13+windows*.15+choices*.08+dust*.09+roof*.08\n   +threshold*.16+roomContours*.03+memory*.04;\n c*=1.380*(.72+.28*max(u_faceGlow,.2));\n c*=1.+u_hover*.10+bass*.08+mid*.05+high*.08+hit*.10;\n return vec4(c,clamp(a,0.,.72));\n}\nvoid main(){\n gfLineageNativeMain();\n vec4 art=gfLineageFinish(v_uv*2.-1.);\n vec3 rgb=max(vec3(0.),gl_FragColor.rgb*0.980+art.rgb);\n float peak=max(rgb.r,max(rgb.g,rgb.b));\n rgb/=1.+max(0.,peak-1.15)*.42;\n float alpha=clamp(max(gl_FragColor.a,art.a),0.,1.);\n gl_FragColor=vec4(rgb,alpha);\n}"}],"sourceSha256":"80e1f050885125556b377b3d0211600f8ab7008b0d2d30dc60e48e12928dfe65"};
